    before=str(plan.get("schema") or ""); accepted=discover_builder_schema(root); live_stage=(inbox/"stage").resolve(); off_stage=Path("/tmp/eira2_builder_stage")/packet_id
    if off_stage.exists(): shutil.rmtree(off_stage)
