                    p=row['process']; code=p.poll(); age=time.time()-row['started_unix']
                    if code is None and age<=WORKER_STALE_SECONDS: continue
                    if code is None:
                        try: os.killpg(p.pid,signal.SIGKILL)
                        except Exception:
                            try: p.kill()
                            except Exception: pass
                        code=124
                    del active[rid]
                    if code!=0: retry[rid]=time.time()+RETRY_SECONDS
                for src in sorted(inbox.glob('*.json')):
                    try:
                        req=json.loads(src.read_text()); raw=src.read_bytes(); digest=b.sha256_bytes(raw); rid=str(req.get('request_id') or ''); op=str(req.get('operation') or '').casefold()
                        if req.get('schema')!=REQUEST_SCHEMA or op not in {'inspect','deploy'} or not rid: continue
                        if (state/f'{digest}.success.json').exists() or rid in active or time.time()<retry.get(rid,0): continue
                        started={'schema':'eira2_transport_terminal_receipt_v4','request_id':rid,'operation':op,'transport_request_sha256':digest,'status':'STARTED','ok':None,'stage':'worker_spawned','supervisor_pid':os.getpid(),'started_unix':time.time()}
                        b.publish(control,rid,started); sync_repo(control); b=base(control)
                        p=subprocess.Popen([sys.executable,str(Path(__file__).resolve()),'--root',str(root),'--worker-request',src.name],cwd=str(root),stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
                        active[rid]={'process':p,'started_unix':time.time()}
                        atomic(runtime/'leases'/f'{rid}.json',{'request_id':rid,'pid':p.pid,'operation':op,'request_file':src.name,'started_unix':time.time()})
                    except Exception as exc:
                        (runtime/'request_errors.log').write_text(f'{time.time()} {src.name} {type(exc).__name__}:{exc}\n')
            except Exception as exc:
                runtime.mkdir(parents=True,exist_ok=True); (runtime/'supervisor_error.log').write_text(f'{time.time()} {type(exc).__name__}:{exc}\n')
            touch_heartbeat(runtime,'loop_end',{'active_workers':len(active)})
            time.sleep(max(1.0,interval))
    finally:
        stop.set(); hb.join(timeout=1)

def main()->int:
    ap=argparse.ArgumentParser(); ap.add_argument('--root',required=True); ap.add_argument('--interval',type=float,default=2.0); ap.add_argument('--worker-request'); a=ap.parse_args()
    root=Path(a.root).resolve(); runtime=root/'eira_probe'/'transport_runtime_v2_3'
    if a.worker_request: return worker(root,runtime,a.worker_request)
    return supervisor(root,a.interval)

if __name__=='__main__': raise SystemExit(main())

#!/usr/bin/env python3
from __future__ import annotations

import ast, hashlib, importlib.util, json, os, re, subprocess, sys, tempfile, time, urllib.request
from pathlib import Path
from typing import Any

REQUEST_SCHEMA = "eira2_transport_request_v1"
LANE_NAME = "EIRA2_BLUEPRINT_DEPLOYMENT_LANE_V4.py"
ID_RE = re.compile(r"^[A-Za-z0-9._-]{1,96}$")
HERE = Path(__file__).resolve().parent


def run(cmd: list[str], *, cwd: Path | None = None, timeout: int = 2400) -> subprocess.CompletedProcess[str]:
    return subprocess.run(cmd, cwd=str(cwd) if cwd else None, text=True, capture_output=True, timeout=timeout, check=False)


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for c in iter(lambda: f.read(1024 * 1024), b""):
            h.update(c)
    return h.hexdigest()


def atomic_json(path: Path, payload: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + f".tmp.{os.getpid()}")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.replace(tmp, path)


def safe_rel(value: str) -> str:
    p = Path(str(value or ""))
    if p.is_absolute() or not p.parts or ".." in p.parts:
        raise RuntimeError("unsafe_relative_path:" + value)
    return p.as_posix()


def git_blob(repo: Path, commit: str, repo_path: str) -> bytes:
    rel = safe_rel(repo_path)
    p = subprocess.run(["git", "-C", str(repo), "show", f"{commit}:{rel}"], capture_output=True, timeout=180, check=False)
    if p.returncode:
        raise RuntimeError("source_blob_missing:" + p.stderr[-1200:].decode(errors="replace"))
    return p.stdout


def extract_payload(source: bytes, target_path: str) -> bytes:
    if b"NEW = " not in source or b"TARGET = " not in source:
        return source
    text = source.decode("utf-8")
    tree = ast.parse(text)
    for node in tree.body:
        if isinstance(node, (ast.Assign, ast.AnnAssign)):
            targets = node.targets if isinstance(node, ast.Assign) else [node.target]
            if any(isinstance(t, ast.Name) and t.id == "NEW" for t in targets):
                value = ast.literal_eval(node.value)
                if not isinstance(value, str):
                    raise RuntimeError("embedded_NEW_not_string")
                if target_path.endswith(".py"):
                    compile(value, target_path, "exec")
                return value.encode()
    return source


def _load(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError("module_load_failed:" + str(path))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def _qualification_success(result: Any, returncode: int) -> tuple[bool, str | None]:
    if returncode != 0 or not isinstance(result, dict):
        return False, None
    if result.get("ok") is True:
        return True, "ok_true"
    if result.get("pass") is True:
        return True, "pass_true"
    if str(result.get("status") or "").casefold() in {"pass", "passed", "success", "successful"}:
        return True, "status_pass"
    return False, None


def _execute_read_only_qualification(root: Path, spec: dict[str, Any]) -> dict[str, Any]:
    q = spec.get("execute_source") or {}
    commit = str(q.get("commit") or "")
    repo_path = safe_rel(str(q.get("path") or ""))
    expected = str(q.get("sha256") or "").lower()
    timeout = int(q.get("timeout_seconds") or 480)
    if not re.fullmatch(r"[0-9a-fA-F]{40}", commit):
