    return evidence


def synthetic_commit(work: Path, request_id: str, gen_rel: str, payload: bytes) -> str:
    blob = subprocess.run(["git", "-C", str(work), "hash-object", "-w", "--stdin"], input=payload, capture_output=True, timeout=120, check=False)
    if blob.returncode:
