from __future__ import annotations

import hashlib, json, os, subprocess, sys, threading, time
from pathlib import Path
from typing import Any

ROLE = "repair_watcher_ai"
VERSION = "2.3.0-eira2"
SUPERPROBE_SCHEMA = "eira2_superprobe_forensic_v3"
SUPERPROBE_EVIDENCE_SCHEMA = "eira2_superprobe_evidence_bundle_v2"
PACKAGE_SCHEMA = "eira2_offsystem_surgery_package_v2"
INDEX_SCHEMA = "eira2_offsystem_file_index_v2"
BUILDER_PLAN_SCHEMA = "eira2_watcher_builder_plan_v2"
_LOCK = threading.RLock(); _STOP = threading.Event(); _THREAD: threading.Thread | None = None
_LAST_CHECK = 0.0; _LAST_ERROR = ""; _LAST_RESULT: dict[str, Any] = {}


def _root() -> Path:
    return Path(os.environ.get("EIRA_LIVE_ROOT", "/media/domenicleonetti/easystore/EIRA/LIVE")).expanduser().resolve()


def _probe_dir() -> Path:
    p = _root() / "eira_probe"; p.mkdir(parents=True, exist_ok=True); return p


def _inbox() -> Path:
    p = Path(os.environ.get("EIRA2_SURGERY_INBOX", str(_probe_dir() / "offsystem_inbox"))).expanduser().resolve(); p.mkdir(parents=True, exist_ok=True); return p


def _read(path: Path) -> dict[str, Any]:
    try:
        v = json.loads(path.read_text(encoding="utf-8")); return v if isinstance(v, dict) else {}
    except Exception: return {}


def _write(path: Path, value: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True); t = path.with_name(path.name + ".tmp"); t.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8"); os.replace(t, path)


def _sha(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for c in iter(lambda: f.read(1024 * 1024), b""): h.update(c)
    return h.hexdigest()


def _run_superprobe() -> dict[str, Any]:
    root = _root(); probe = root / "tools" / "eira2_superprobe.py"
    r = subprocess.run([sys.executable, str(probe), "--root", str(root), "--summary-only", "--verify-artifacts"], cwd=str(root), capture_output=True, text=True, timeout=2400)
    combo = (r.stdout or "") + "\n" + (r.stderr or "")
    if r.returncode or "EIRA2_SUPERPROBE=PASS" not in combo: raise RuntimeError("superprobe_rejected:" + combo[-1200:])
    report = _read(_probe_dir() / "eira2_superprobe_report.json")
    if report.get("ok") is not True or report.get("schema") != SUPERPROBE_SCHEMA or report.get("evidence_schema") != SUPERPROBE_EVIDENCE_SCHEMA or report.get("mutates_live") is not False: raise RuntimeError("superprobe_receipt_invalid")
    for name, row in (report.get("artifacts") or {}).items():
        p = Path(str((row or {}).get("path") or ""))
        if not p.is_file() or _sha(p) != str((row or {}).get("sha256") or ""): raise RuntimeError(f"superprobe_artifact_invalid:{name}")
    return report


def _verify_package() -> tuple[dict[str, Any], dict[str, Any]]:
    inbox = _inbox(); package, index = _read(inbox / "surgery_package.json"), _read(inbox / "file_index.json")
    if package.get("schema") != PACKAGE_SCHEMA or index.get("schema") != INDEX_SCHEMA: raise RuntimeError("offsystem_package_missing_or_invalid")
    if package.get("built_off_live") is not True or package.get("writes_live") is not False or package.get("eira2_only") is not True: raise RuntimeError("offsystem_package_authority_invalid")
    if _sha(inbox / "file_index.json") != package.get("file_index_sha256"): raise RuntimeError("offsystem_file_index_hash_mismatch")
    seen = set()
    for row in index.get("files") or []:
        target, staged_rel, digest = str(row.get("target_path") or ""), str(row.get("staged_path") or row.get("target_path") or ""), str(row.get("sha256") or "")
        if not target or target in seen or ".." in Path(target).parts: raise RuntimeError("offsystem_target_invalid")
        seen.add(target); staged = (inbox / "stage" / staged_rel).resolve(); staged.relative_to((inbox / "stage").resolve())
        if not staged.is_file() or _sha(staged) != digest: raise RuntimeError(f"offsystem_staged_hash_invalid:{target}")
    if sorted(seen) != sorted(package.get("targets") or []): raise RuntimeError("offsystem_targets_mismatch")
    return package, index


def _impact(report: dict[str, Any], target: str) -> dict[str, Any]:
    row = (report.get("artifacts") or {}).get("semantic_impact_index") or {}; payload = _read(Path(str(row.get("path") or "")))
    return dict((payload.get("impact_index") or {}).get(target) or (payload.get("files") or {}).get(target) or {})


def _build_plan(report: dict[str, Any], package: dict[str, Any], index: dict[str, Any]) -> dict[str, Any]:
    files, blast = [], {}
    for row in index.get("files") or []:
        target = str(row.get("target_path")); files.append({"target_path": target, "staged_path": str(row.get("staged_path") or target), "sha256": str(row.get("sha256"))}); blast[target] = _impact(report, target)
    fp = str(report.get("evidence_bundle_fingerprint_sha256") or "")
    return {"schema": BUILDER_PLAN_SCHEMA, "authorized_by": ROLE, "watcher_version": VERSION, "eira2_only": True, "superprobe_evidence_verified": True, "superprobe_evidence_fingerprint_sha256": fp, "pre_superprobe_fingerprint_sha256": fp, "package_fingerprint_sha256": package.get("package_fingerprint_sha256"), "source_commit_sha": package.get("source_commit_sha"), "builder_probe_may_decide_changes": False, "offsystem_stage_root": str((_inbox() / "stage").resolve()), "files": files, "bridges": [], "bash_blocks": [], "semantic_blast_radius": blast, "requires_package_reseal": True, "requires_post_superprobe": True, "rollback_on_post_probe_failure": True, "retire_after_acceptance": [], "generated_unix": time.time()}


def inspect_once() -> dict[str, Any]:
    global _LAST_CHECK, _LAST_ERROR, _LAST_RESULT
    with _LOCK:
        _LAST_CHECK = time.time()
        try:
            report = _run_superprobe(); package, index = _verify_package(); plan = _build_plan(report, package, index); path = _probe_dir() / "eira2_builder_plan.json"; _write(path, plan)
            _LAST_ERROR = ""; _LAST_RESULT = {"ok": True, "status": "builder_plan_ready", "builder_plan": str(path), "planned_files": len(plan["files"]), "evidence_fingerprint": plan["pre_superprobe_fingerprint_sha256"], "package_fingerprint": plan["package_fingerprint_sha256"], "apply_enabled": True}; return dict(_LAST_RESULT)
        except Exception as exc:
            _LAST_ERROR = f"{type(exc).__name__}:{exc}"[:1400]; _LAST_RESULT = {"ok": False, "status": "builder_plan_rejected", "error": _LAST_ERROR}; return dict(_LAST_RESULT)


def deploy_builder_probe() -> dict[str, Any]:
    plan = inspect_once()
    if not plan.get("ok"): return plan
    root = _root(); executor = root / "tools" / "eira2_transaction_executor.py"
    r = subprocess.run([sys.executable, str(executor), "--root", str(root), "--inbox", str(_inbox()), "--plan", str(_probe_dir() / "eira2_builder_plan.json")], cwd=str(root), capture_output=True, text=True, timeout=3600)
    combo = (r.stdout or "") + "\n" + (r.stderr or "")
    if r.returncode or "EIRA2_TRANSACTION_EXECUTOR=PASS" not in combo: return {"ok": False, "status": "transaction_failed_or_rolled_back", "detail": combo[-1600:]}
    receipt = _read(_probe_dir() / "eira2_transaction_receipt.json"); return {"ok": receipt.get("ok") is True, "status": receipt.get("status"), "receipt": receipt}


def check_once(*, apply_if_safe: bool = False) -> dict[str, Any]: return deploy_builder_probe() if apply_if_safe else inspect_once()

def _loop(interval_seconds: int) -> None:
    while not _STOP.wait(max(300, int(interval_seconds))): inspect_once()

def boot(interval_seconds: int = 900) -> dict[str, Any]:
    global _THREAD
    with _LOCK:
        if _THREAD and _THREAD.is_alive(): return status()
        _STOP.clear(); initial = inspect_once(); _THREAD = threading.Thread(target=_loop, args=(interval_seconds,), name="eira2-repair-watcher", daemon=True); _THREAD.start(); return {"ok": True, "status": "watching", "initial": initial, **status()}

def stop() -> dict[str, Any]:
    global _THREAD
    _STOP.set();
    if _THREAD and _THREAD.is_alive(): _THREAD.join(timeout=3)
    _THREAD = None; return status()

def status() -> dict[str, Any]: return {"ok": True, "node": ROLE, "version": VERSION, "watching": bool(_THREAD and _THREAD.is_alive()), "last_check": _LAST_CHECK, "last_error": _LAST_ERROR, "last_result": dict(_LAST_RESULT), "eira2_only": True, "superprobe_role": "read_only_exploratory_watchdog", "builder_probe_role": "watcher_controlled_write_transport_and_constructor", "single_watcher_authority": True, "apply_enabled": True}
def register(context=None): return {"node": ROLE, "version": VERSION, "ask": ask, "boot": boot, "status": status, "stop": stop, "check_once": check_once, "inspect_once": inspect_once, "deploy_builder_probe": deploy_builder_probe}
def ask(prompt: str, context=None):
    text = str(prompt or "").casefold()
    if any(w in text for w in ("deploy", "build", "repair", "apply")): return deploy_builder_probe()
    if any(w in text for w in ("inspect", "probe", "plan", "forensic", "semantic")): return inspect_once()
    if "stop" in text: return stop()
    return status()

from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
import tempfile
import threading
import time
import wave
from pathlib import Path
from typing import Any

from .voice_prosody import cadence_chunks, synthesis_controls


AUDIO_UUID_MARKERS = (
    "audio sink",
    "advanced audio",
    "0000110b",
    "0000110d",
)
AUDIO_ICON_MARKERS = ("audio-card", "audio-headset", "headset", "headphones")
MAC_RE = re.compile(r"(?i)\b([0-9a-f]{2}(?::[0-9a-f]{2}){5})\b")


class NativeBluetoothVoiceRuntime:
    """EIRA2-owned synchronous Bluetooth/Piper spoken-output backend.

    This backend deliberately has no global boot hook, reconnect daemon, queue, or
    import path into the retired EIRA1 tree. Lifecycle authority remains with the
    EIRA2 Supervisor through ``delivery.voice``. Voice models and optional Piper
    vendor packages live under EIRA2 ``var/voice`` unless explicitly overridden.
    """

    def __init__(self, runtime_root: Path, *, voice_model: Path | None = None) -> None:
        self.runtime_root = runtime_root.expanduser().resolve()
        self.voice_root = self.runtime_root / "var" / "voice"
        vendor_override = str(os.environ.get("EIRA2_PIPER_VENDOR", "")).strip()
        self.vendor = Path(vendor_override).expanduser().resolve() if vendor_override else self.voice_root / "_vendor"
        model_override = str(os.environ.get("EIRA2_VOICE_MODEL", "")).strip()
        self.voice_model = (
            Path(model_override).expanduser().resolve()
            if model_override
            else voice_model.expanduser().resolve() if voice_model is not None else self.voice_root / "voices" / "en_US-hfc_female-medium.onnx"
        )
        self._lock = threading.RLock()
        self._connected: dict[str, str] = {}
        self._active_sinks: list[str] = []
        self._default_sink: str | None = None
        self._last_error: str | None = None
        self._last_acquire = 0.0
        self._last_spoken = 0.0
        self._connect_attempt_at: dict[str, float] = {}
        self._connect_cooldown_seconds = float(os.environ.get("EIRA2_BT_CONNECT_COOLDOWN_SECONDS", "12"))
        self._voice: Any | None = None
        self._loaded_voice_model: Path | None = None
        self._player = self._detect_player()

    @staticmethod
    def _run(args, *, timeout: int | float | None = 20, input_text: str | None = None):
        return subprocess.run(
            list(args), input=input_text, text=True, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, timeout=timeout, check=False,
        )

    @staticmethod
    def _detect_player() -> str | None:
        for command in ("paplay", "pw-play", "aplay"):
            if shutil.which(command):
                return command
        return None

    def set_voice_model(self, model: Path) -> None:
        selected = model.expanduser().resolve()
        if selected == self.voice_model:
            return
        self.voice_model = selected
        self._voice = None
        self._loaded_voice_model = None

    def _bluetoothctl(self, *args: str, timeout: int = 20):
        return self._run(("bluetoothctl", *args), timeout=timeout)

    @staticmethod
    def _parse_devices(text: str) -> list[tuple[str, str]]:
        found: list[tuple[str, str]] = []
        seen: set[str] = set()
        for raw in str(text or "").splitlines():
            match = MAC_RE.search(raw)
            if not match:
                continue
            mac = match.group(1).upper()
            if mac in seen:
                continue
            name = raw[match.end():].strip() or mac
            seen.add(mac)
            found.append((mac, name))
        return found

    def _devices(self, *, paired_only: bool = False) -> list[tuple[str, str]]:
        commands: list[tuple[str, ...]] = []
        if paired_only:
            commands.extend((("devices", "Paired"), ("paired-devices",)))
        else:
            commands.append(("devices",))
        for command in commands:
            result = self._bluetoothctl(*command, timeout=12)
            if result.returncode == 0:
                devices = self._parse_devices(result.stdout)
                if devices or not paired_only:
                    return devices
        return []

    def _info(self, mac: str) -> dict[str, Any]:
        result = self._bluetoothctl("info", mac, timeout=10)
        text = (result.stdout or "") + "\n" + (result.stderr or "")
        low = text.lower()
        rssi_match = re.search(r"(?im)^\s*rssi:\s*(-?\d+)", text)
        return {
            "raw": text,
            "paired": "paired: yes" in low,
            "trusted": "trusted: yes" in low,
            "connected": "connected: yes" in low,
            "audio": any(marker in low for marker in AUDIO_UUID_MARKERS) or any(("icon: " + marker) in low for marker in AUDIO_ICON_MARKERS),
            "rssi": int(rssi_match.group(1)) if rssi_match else -999,
        }

    def _scan_once(self, *, seconds: int = 8) -> None:
        if not shutil.which("bluetoothctl"):
            raise RuntimeError("bluetoothctl_not_installed")
        self._bluetoothctl("power", "on", timeout=8)
        self._bluetoothctl("--timeout", str(int(seconds)), "scan", "on", timeout=int(seconds) + 5)

    def _pair_best_audio_if_needed(self) -> None:
        enabled = str(os.environ.get("EIRA2_BT_AUTO_PAIR", "1")).strip().casefold()
        if enabled not in {"1", "true", "yes", "on"}:
            return
        candidates: list[tuple[int, str, str]] = []
        for mac, name in self._devices(paired_only=False):
            info = self._info(mac)
            if info["audio"] and not info["paired"]:
                candidates.append((int(info["rssi"]), mac, name))
        candidates.sort(reverse=True)
        if not candidates:
            return
        _, mac, _ = candidates[0]
        paired = self._bluetoothctl("pair", mac, timeout=35)
        if paired.returncode != 0:
            raise RuntimeError("automatic_bluetooth_pairing_failed:" + mac + ":" + (paired.stderr.strip() or paired.stdout.strip()))
        self._bluetoothctl("trust", mac, timeout=10)

    def _connect_audio_devices(self) -> dict[str, str]:
        eligible: list[tuple[int, str, str, dict[str, Any]]] = []
        for mac, name in self._devices(paired_only=True):
            info = self._info(mac)
            if info["paired"] and info["audio"]:
                eligible.append((int(info["rssi"]), mac, name, info))
        eligible.sort(reverse=True)
        connected: dict[str, str] = {}
        max_outputs = max(1, min(10, int(os.environ.get("EIRA2_BT_MAX_OUTPUTS", "10"))))
        for _, mac, name, info in eligible[:max_outputs]:
            if not info["trusted"]:
                self._bluetoothctl("trust", mac, timeout=10)
            live_info = self._info(mac)
            if live_info["connected"]:
                connected[mac] = name
                continue
            now = time.monotonic()
            last_attempt = self._connect_attempt_at.get(mac, 0.0)
            if now - last_attempt < self._connect_cooldown_seconds:
                continue
            self._connect_attempt_at[mac] = now
            result = self._bluetoothctl("connect", mac, timeout=25)
            if result.returncode != 0:
                continue
            time.sleep(1.2)
            live_info = self._info(mac)
            if live_info["connected"]:
                connected[mac] = name
        return connected

    @classmethod
    def _pactl_sinks(cls) -> list[str]:
        if not shutil.which("pactl"):
            return []
        result = cls._run(("pactl", "list", "short", "sinks"), timeout=10)
        if result.returncode != 0:
            return []
        sinks: list[str] = []
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) >= 2 and "bluez" in parts[1].casefold():
                sinks.append(parts[1])
        return sinks

    @classmethod
    def _wpctl_sinks(cls) -> list[tuple[str, str]]:
        if not shutil.which("wpctl"):
            return []
        result = cls._run(("wpctl", "status", "-n"), timeout=10)
        if result.returncode != 0:
            return []
        sinks: list[tuple[str, str]] = []
        in_sinks = False
        for line in result.stdout.splitlines():
            low = line.casefold()
            if "sinks:" in low:
                in_sinks = True
                continue
            if in_sinks and ("sources:" in low or "filters:" in low or "streams:" in low):
                break
            if in_sinks and "bluez" in low:
                match = re.search(r"(\d+)\.\s+(.+?)(?:\s+\[|$)", line)
                if match:
                    sinks.append((match.group(1), match.group(2).strip()))
        return sinks

    def _route_audio(self) -> list[str]:
        sinks = self._pactl_sinks()
        if sinks:
            self._run(("pactl", "set-default-sink", sinks[0]), timeout=8)
            self._default_sink = sinks[0]
            return sinks
        wp_sinks = self._wpctl_sinks()
        if wp_sinks:
            sink_id, sink_name = wp_sinks[0]
            self._run(("wpctl", "set-default", sink_id), timeout=8)
            self._default_sink = sink_name
            return [name for _, name in wp_sinks]
        self._default_sink = None
        return []

    def acquire(self) -> dict[str, Any]:
        with self._lock:
            self._last_acquire = time.time()
            self._last_error = None
            try:
                self._connected = self._connect_audio_devices()
                if not self._connected:
                    self._scan_once(seconds=int(os.environ.get("EIRA2_BT_SCAN_SECONDS", "8")))
                    self._pair_best_audio_if_needed()
                    self._connected = self._connect_audio_devices()
                deadline = time.time() + 8
                sinks: list[str] = []
                while time.time() < deadline:
                    sinks = self._route_audio()
                    if sinks or not self._connected:
                        break
                    time.sleep(1)
                self._active_sinks = sinks
            except Exception as exc:
                self._last_error = f"{type(exc).__name__}:{exc}"
            return self.status()

    def ensure(self) -> dict[str, Any]:
        with self._lock:
            needs_acquire = not self._connected or not self._active_sinks or (time.time() - self._last_acquire) > 20
        if needs_acquire:
            return self.acquire()
        return self.status()

    def _load_voice(self):
        if self._voice is not None and self._loaded_voice_model == self.voice_model:
            return self._voice
        if not self.voice_model.is_file():
            raise RuntimeError("piper_voice_model_missing:" + str(self.voice_model))
        if self.vendor.is_dir() and str(self.vendor) not in sys.path:
            sys.path.insert(0, str(self.vendor))
        try:
            from piper import PiperVoice
        except ImportError as exc:
            raise RuntimeError("piper_runtime_missing:install_piper_or_migrate_EIRA2_PIPER_VENDOR") from exc
        self._voice = PiperVoice.load(str(self.voice_model))
        self._loaded_voice_model = self.voice_model
        return self._voice

    def _synthesize(self, text: str, output: Path) -> None:
        spoken = str(text or "").strip()
        if not spoken:
            raise ValueError("empty_speech_chunk")
        voice = self._load_voice()
        try:
            from piper.config import SynthesisConfig
        except ImportError as exc:
            raise RuntimeError("piper_synthesis_config_missing") from exc
        controls = synthesis_controls(spoken)
        config = SynthesisConfig(
            length_scale=float(controls["length_scale"]),
            noise_scale=float(controls["noise_scale"]),
            noise_w_scale=float(controls["noise_w_scale"]),
        )
        with wave.open(str(output), "wb") as wav_file:
            voice.synthesize_wav(spoken, wav_file, syn_config=config)

    def _play(self, wav_path: Path) -> None:
        player = self._player or self._detect_player()
        if not player:
            raise RuntimeError("audio_player_missing:paplay_or_pw-play_or_aplay")
        self._player = player
        if player == "paplay":
            args = ["paplay"]
            if self._default_sink:
                args.append("--device=" + self._default_sink)
            args.append(str(wav_path))
        elif player == "pw-play":
            args = ["pw-play", str(wav_path)]
        else:
            args = ["aplay", "-q", str(wav_path)]
        result = self._run(args, timeout=None)
        if result.returncode != 0:
            raise RuntimeError("audio_playback_failed:" + player + ":" + (result.stderr.strip() or result.stdout.strip()))

    def speak_now(self, text: str) -> None:
        spoken = str(text or "").strip()
        if not spoken:
            return
        state = self.ensure()
        if not state["connected_devices"]:
            raise RuntimeError("no_bluetooth_audio_device_connected")
        if not state["active_sinks"]:
            raise RuntimeError("bluetooth_connected_without_audio_sink")
        fd, tmp_name = tempfile.mkstemp(prefix="eira2_voice_", suffix=".wav")
        os.close(fd)
        tmp = Path(tmp_name)
        try:
            for phrase, pause in cadence_chunks(spoken):
                self._synthesize(phrase, tmp)
                self._play(tmp)
                if pause > 0:
                    time.sleep(pause)
            self._last_spoken = time.time()
            self._last_error = None
        except Exception as exc:
            self._last_error = f"{type(exc).__name__}:{exc}"
            raise
        finally:
            try:
                tmp.unlink()
            except FileNotFoundError:
                pass

    def status(self) -> dict[str, Any]:
        with self._lock:
            return {
                "ok": self._last_error is None,
                "role": "eira2_native_bluetooth_voice",
                "runtime_authority": "delivery.voice",
                "connected_devices": dict(self._connected),
                "active_sinks": list(self._active_sinks),
                "default_sink": self._default_sink,
                "voice_model": str(self.voice_model),
                "voice_model_ready": self.voice_model.is_file(),
                "piper_vendor": str(self.vendor),
                "piper_vendor_ready": self.vendor.is_dir(),
                "player": self._player,
                "last_error": self._last_error,
                "last_acquire": self._last_acquire,
                "last_spoken": self._last_spoken,
                "synthetic_breath_audio": False,
                "phrase_specific_prosody": True,
                "background_runtime_threads": False,
                "eira1_runtime_delegation": False,
            }

from __future__ import annotations

from dataclasses import dataclass
from enum import Enum
from time import time
from uuid import uuid4

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState


class InputKind(str, Enum):
    TERMINAL = "terminal"
    IPHONE_TEXT = "iphone_text"
    IPHONE_VOICE = "iphone_voice"
    LOCAL_VOICE = "local_voice"


@dataclass(frozen=True, slots=True)
class InputEnvelope:
    text: str
    kind: InputKind
    correlation_id: str
    received_at: float

    @classmethod
    def create(cls, text: str, kind: InputKind) -> "InputEnvelope":
        clean = str(text or "").strip()
        if not clean:
            raise ValueError("empty_input")
        if not isinstance(kind, InputKind):
            kind = InputKind(str(kind))
        return cls(clean, kind, str(uuid4()), time())


class IngressService:
    """Canonical normalization boundary for all normal EIRA inputs.

    Ingress owns input normalization and correlation identity only. It never routes,
    reasons, speaks, writes state, or depends on outward delivery.
    """

    spec = ServiceSpec("interfaces.ingress", required=True, dependencies=())

    def __init__(self) -> None:
        self._state = ServiceState.DECLARED

    async def start(self, context: RuntimeContext) -> None:
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        return Health(self._state, "canonical_input_normalization")

    def accept(self, text: str, kind: InputKind) -> InputEnvelope:
        if self._state != ServiceState.READY:
            raise RuntimeError("ingress_not_ready")
        return InputEnvelope.create(text, kind)

