from __future__ import annotations

import asyncio
import http.client
import json
import queue
import socket
import threading
import urllib.request
from collections.abc import AsyncIterator
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import urlparse


@dataclass(frozen=True, slots=True)
class OllamaCandidateAdapter:
    model: str = "qwen2.5:3b"
    endpoint: str = "http://127.0.0.1:11434/api/generate"
    unix_socket: str = ""
    timeout_seconds: float | None = None
    stream_buffer_fragments: int = 64

    def __post_init__(self) -> None:
        parsed = urlparse(self.endpoint)
        if parsed.scheme != "http" or parsed.hostname not in {"127.0.0.1", "localhost", "::1"}:
            raise ValueError("ollama_adapter_must_remain_local")
        if self.unix_socket:
            path = Path(self.unix_socket).expanduser()
            if not path.is_absolute():
                raise ValueError("ollama_unix_socket_must_be_absolute")
        if self.timeout_seconds is not None and self.timeout_seconds <= 0:
            raise ValueError("ollama_timeout_must_be_positive_or_none")
        if not 4 <= int(self.stream_buffer_fragments) <= 4096:
            raise ValueError("ollama_stream_buffer_fragments_out_of_range")

    async def generate(self, prompt: str) -> str:
        return await asyncio.to_thread(self._generate_sync, prompt)

    def _payload(self, prompt: str, *, stream: bool) -> bytes:
        return json.dumps({
            "model": self.model,
            "prompt": prompt,
            "stream": bool(stream),
            "options": {"temperature": 0},
        }).encode("utf-8")

    def _request(self, prompt: str, *, stream: bool) -> urllib.request.Request:
        return urllib.request.Request(
            self.endpoint,
            data=self._payload(prompt, stream=stream),
            headers={"Content-Type": "application/json"},
            method="POST",
        )

    def _open_url_response(self, prompt: str, *, stream: bool):
        request = self._request(prompt, stream=stream)
        if self.timeout_seconds is None:
            return urllib.request.urlopen(request)
        return urllib.request.urlopen(request, timeout=self.timeout_seconds)

    def _open_unix_response(self, prompt: str, *, stream: bool) -> tuple[socket.socket, http.client.HTTPResponse]:
        path = urlparse(self.endpoint).path or "/api/generate"
        payload = self._payload(prompt, stream=stream)
        client = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        client.settimeout(self.timeout_seconds)
        client.connect(self.unix_socket)
        request = (
            f"POST {path} HTTP/1.1\r\n"
            "Host: localhost\r\n"
            "Content-Type: application/json\r\n"
            f"Content-Length: {len(payload)}\r\n"
            "Connection: close\r\n"
            "\r\n"
        ).encode("ascii") + payload
        client.sendall(request)
        response = http.client.HTTPResponse(client)
        response.begin()
        if response.status >= 400:
            body = response.read(4096).decode("utf-8", errors="replace")
            response.close()
            client.close()
            raise RuntimeError(f"ollama_http_error:{response.status}:{body}")
        return client, response

    def _generate_sync(self, prompt: str) -> str:
        if self.unix_socket:
            client, response = self._open_unix_response(prompt, stream=False)
            try:
                body = json.loads(response.read().decode("utf-8"))
            finally:
                response.close()
                client.close()
        else:
            with self._open_url_response(prompt, stream=False) as response:
                body = json.loads(response.read().decode("utf-8"))
        candidate = str(body.get("response") or "").strip()
        if not candidate:
            raise RuntimeError("ollama_candidate_empty")
        return candidate

    @staticmethod
    def _put_stream_item(
        output: queue.Queue[tuple[str, object]],
        item: tuple[str, object],
        stop: threading.Event,
    ) -> bool:
        while not stop.is_set():
            try:
                output.put(item, timeout=0.25)
                return True
            except queue.Full:
                continue
        return False

    def _stream_worker(
        self,
        prompt: str,
        output: queue.Queue[tuple[str, object]],
        stop: threading.Event,
    ) -> None:
        client: socket.socket | None = None
        response: object | None = None
        try:
            if self.unix_socket:
                client, unix_response = self._open_unix_response(prompt, stream=True)
                response = unix_response
                iterator = iter(unix_response.readline, b"")
            else:
                network_response = self._open_url_response(prompt, stream=True)
                response = network_response
                iterator = iter(network_response.readline, b"")

            for raw in iterator:
                if stop.is_set():
                    break
                line = raw.decode("utf-8").strip()
                if not line:
                    continue
                payload = json.loads(line)
                fragment = str(payload.get("response") or "")
                if fragment and not self._put_stream_item(output, ("chunk", fragment), stop):
                    break
                if payload.get("done") is True:
                    break
            self._put_stream_item(output, ("done", None), stop)
        except Exception as error:
            self._put_stream_item(output, ("error", error), stop)
        finally:
            try:
                if response is not None:
                    response.close()  # type: ignore[attr-defined]
            finally:
                if client is not None:
                    client.close()

    async def stream(self, prompt: str) -> AsyncIterator[str]:
        """Stream private candidate fragments with bounded lossless backpressure.

        Production EIRA2 uses a Unix socket to a bridge that shares Ollama's
        private network namespace. Candidate fragments never become outward speech
        directly; conversation/evidence/identity/accepted-state gates remain authority.
        The bounded queue pauses the producer rather than dropping or truncating text.
        """
        output: queue.Queue[tuple[str, object]] = queue.Queue(maxsize=int(self.stream_buffer_fragments))
        stop = threading.Event()
        worker = threading.Thread(
            target=self._stream_worker,
            args=(prompt, output, stop),
            name="eira2-ollama-private-stream",
            daemon=True,
        )
        worker.start()
        seen = False
        try:
            while True:
                kind, value = await asyncio.to_thread(output.get)
                if kind == "chunk":
                    seen = True
                    yield str(value)
                    continue
                if kind == "error":
                    if isinstance(value, Exception):
                        raise RuntimeError(f"ollama_stream_failed:{type(value).__name__}:{value}") from value
                    raise RuntimeError("ollama_stream_failed")
                if kind == "done":
                    break
        finally:
            stop.set()
        if not seen:
            raise RuntimeError("ollama_candidate_stream_empty")

from __future__ import annotations

import asyncio
import inspect
import json
import re
from collections.abc import Awaitable, Callable, Iterable
from dataclasses import dataclass
from typing import Any

from ..contracts import Event, Health, RuntimeContext, ServiceSpec, ServiceState
from ..registry.graph import NodeRegistryService


CapabilityHandler = Callable[[str], Awaitable[dict[str, Any]]]
_SENSITIVE_KEY = re.compile(
    r"(?:pass(?:word)?|token|secret|credential|api[_-]?key|private[_-]?key|auth(?!oritative)(?:orization)?)",
    re.I,
)


@dataclass(frozen=True, slots=True)
class CapabilityBinding:
    id: str
    implementation_node: str
    aliases: tuple[str, ...]
    tags: tuple[str, ...]
    handler: CapabilityHandler
    description: str = ""
    read_only: bool = True
    auto_safe: bool = False
    shadow_safe: bool = True


@dataclass(frozen=True, slots=True)
class CapabilityResult:
    id: str
    ok: bool
    payload: dict[str, Any]
    evidence: str


class CapabilityExecutorService:
    """Canonical tool/capability execution authority."""

    spec = ServiceSpec(
        "capabilities.executor",
        required=True,
        dependencies=("registry.graph", "kernel.events"),
        start_timeout_seconds=15.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(self) -> None:
        self._state = ServiceState.DECLARED
        self._context: RuntimeContext | None = None
        self._registry: NodeRegistryService | None = None
        self._bindings: dict[str, CapabilityBinding] = {}
        self._tool_nodes: set[str] = set()

    async def start(self, context: RuntimeContext) -> None:
        registry = context.get_service("registry.graph")
        if not isinstance(registry, NodeRegistryService):
            raise RuntimeError("canonical_registry_missing")
        self._context = context
        self._registry = registry
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._state = ServiceState.STOPPED
        self._context = None
        self._registry = None

    async def health(self) -> Health:
        return Health(self._state, f"bindings={len(self._bindings)}")

    @staticmethod
    def _clean_id(value: str) -> str:
        clean = str(value or "").strip().casefold()
        if not re.fullmatch(r"[a-z0-9_.-]{3,160}", clean):
            raise ValueError(f"capability_id_invalid:{clean}")
        return clean

    @staticmethod
    def _sanitize(value: Any, *, depth: int = 0) -> Any:
        if depth > 6:
            return "<depth-limit>"
        if isinstance(value, dict):
            result: dict[str, Any] = {}
            for key, item in list(value.items())[:200]:
                rendered_key = str(key)[:160]
                if _SENSITIVE_KEY.search(rendered_key):
                    result[rendered_key] = "<redacted>"
                else:
                    result[rendered_key] = CapabilityExecutorService._sanitize(item, depth=depth + 1)
            return result
        if isinstance(value, (list, tuple, set)):
            return [CapabilityExecutorService._sanitize(item, depth=depth + 1) for item in list(value)[:200]]
        if isinstance(value, str):
            return value[:4000]
        if value is None or isinstance(value, (bool, int, float)):
            return value
        return str(value)[:1000]

    def _known_node_names(self) -> set[str]:
        if self._registry is None:
            return set()
        return {
            str(row.get("name") or "")
            for row in self._registry.snapshot().get("nodes", [])
            if isinstance(row, dict)
        }

    async def register(self, binding: CapabilityBinding) -> None:
        if self._state != ServiceState.READY or self._context is None or self._registry is None:
            raise RuntimeError("capability_executor_not_ready")
        capability_id = self._clean_id(binding.id)
        if capability_id in self._bindings:
            raise ValueError(f"duplicate_capability_binding:{capability_id}")
        implementation_node = str(binding.implementation_node or "").strip()
        if not implementation_node:
            raise ValueError("capability_implementation_node_missing")
        if implementation_node not in self._known_node_names():
            raise ValueError(f"capability_implementation_node_unknown:{implementation_node}")
        aliases = tuple(sorted({" ".join(str(x).casefold().split()) for x in binding.aliases if str(x).strip()}))
        tags = tuple(sorted({str(x).casefold().strip() for x in binding.tags if str(x).strip()}))
        if not aliases and not tags:
            raise ValueError(f"capability_binding_unroutable:{capability_id}")
        normalized = CapabilityBinding(
            id=capability_id,
            implementation_node=implementation_node,
            aliases=aliases,
            tags=tags,
            handler=binding.handler,
            description=str(binding.description or "")[:400],
            read_only=bool(binding.read_only),
            auto_safe=bool(binding.auto_safe),
            shadow_safe=bool(binding.shadow_safe),
        )
        tool_node = f"tool.{capability_id}"
        await self._registry.register_node(
            tool_node,
            kind="capability_tool",
            capabilities=tags,
            metadata={
                "capability_id": capability_id,
                "implementation_node": implementation_node,
                "read_only": str(normalized.read_only).lower(),
                "auto_safe": str(normalized.auto_safe).lower(),
            },
        )
        await self._registry.add_bridge(
            "capabilities.executor", tool_node,
            kind="capability_dispatch", conductive=True,
            evidence="registered_capability_binding",
        )
        await self._registry.add_bridge(
            tool_node, implementation_node,
            kind="capability_implementation", conductive=True,
            evidence="registered_capability_binding",
        )
        self._bindings[capability_id] = normalized
        self._tool_nodes.add(tool_node)
        await self._context.publish(Event("capability.registered", {
            "id": capability_id,
            "tool_node": tool_node,
            "implementation_node": implementation_node,
            "read_only": normalized.read_only,
            "auto_safe": normalized.auto_safe,
        }))

    def bindings(self) -> tuple[CapabilityBinding, ...]:
        return tuple(self._bindings[key] for key in sorted(self._bindings))

    def discover(self, query: str = "", *, requested: Iterable[str] = ()) -> tuple[CapabilityBinding, ...]:
        clean = " ".join(str(query or "").casefold().split())
        requested_set = {str(x).casefold().strip() for x in requested if str(x).strip()}
        rows: list[CapabilityBinding] = []
        for binding in self._bindings.values():
            explicit = any(clean == alias or clean.startswith(alias + " ") for alias in binding.aliases)
            tagged = bool(requested_set & set(binding.tags))
            searchable = not clean or clean in binding.id or clean in binding.description.casefold()
            if explicit or tagged or searchable:
                rows.append(binding)
        return tuple(sorted(rows, key=lambda row: row.id))

    @staticmethod
    def _explicit_match(text: str, aliases: tuple[str, ...]) -> bool:
        clean = " ".join(str(text or "").casefold().split())
        return any(clean == alias or clean.startswith(alias + " ") for alias in aliases)

    async def execute_for_turn(
        self,
        text: str,
        *,
        requested: Iterable[str] = (),
        correlation_id: str,
        shadow_mode: bool,
    ) -> tuple[CapabilityResult, ...]:
        if self._state != ServiceState.READY or self._context is None:
            raise RuntimeError("capability_executor_not_ready")
        requested_set = {str(x).casefold().strip() for x in requested if str(x).strip()}
        selected: list[CapabilityBinding] = []
        for binding in self._bindings.values():
            explicit = self._explicit_match(text, binding.aliases)
            automatic = binding.auto_safe and bool(requested_set & set(binding.tags))
            if not (explicit or automatic):
                continue
            if shadow_mode and not binding.shadow_safe:
                continue
            if automatic and not binding.read_only:
                continue
            selected.append(binding)

        selected.sort(key=lambda row: (not self._explicit_match(text, row.aliases), row.id))
        selected = selected[:4]

        async def run_one(binding: CapabilityBinding) -> CapabilityResult:
            try:
                payload = await binding.handler(text)
                if not isinstance(payload, dict):
                    raise TypeError("capability_handler_must_return_dict")
                safe_payload = self._sanitize(payload)
                if not isinstance(safe_payload, dict):
                    raise TypeError("capability_sanitizer_contract_failed")
                result = CapabilityResult(
                    id=binding.id,
                    ok=True,
                    payload=safe_payload,
                    evidence=f"capability_binding:{binding.id}:{binding.implementation_node}",
                )
            except Exception as error:
                result = CapabilityResult(
                    id=binding.id,
                    ok=False,
                    payload={"error": f"{type(error).__name__}:{error}"[:500]},
                    evidence=f"capability_failure:{binding.id}:{binding.implementation_node}",
                )
            await self._context.publish(Event("capability.executed", {
                "id": result.id,
                "ok": result.ok,
                "implementation_node": binding.implementation_node,
                "read_only": binding.read_only,
            }, correlation_id))
            return result

        if not selected:
            return ()

        results: list[CapabilityResult] = []
        parallel_read_only_count = 0
        serialized_mutation_count = 0
        any_parallel_group = False
        index = 0
        while index < len(selected):
            binding = selected[index]
            if not binding.read_only:
                results.append(await run_one(binding))
                serialized_mutation_count += 1
                index += 1
                continue

            end = index
            while end < len(selected) and selected[end].read_only:
                end += 1
            group = selected[index:end]
            group_results = await asyncio.gather(*(run_one(row) for row in group))
            results.extend(group_results)
            parallel_read_only_count += len(group)
            any_parallel_group = any_parallel_group or len(group) > 1
            index = end

        await self._context.publish(Event("capability.fanout.completed", {
            "selected": [binding.id for binding in selected],
            "result_count": len(results),
            "ok_count": sum(1 for row in results if row.ok),
            "failed_count": sum(1 for row in results if not row.ok),
            "concurrent": any_parallel_group,
            "parallel_read_only_count": parallel_read_only_count,
            "serialized_mutation_count": serialized_mutation_count,
            "mutation_serialized": True,
        }, correlation_id))
        return tuple(results)

    @staticmethod
    def cognition_context(results: Iterable[CapabilityResult]) -> str:
        rows = list(results)
        if not rows:
            return ""
        lines = [
            "<eira_capability_results>",
            "Instruction: these are sanitized runtime/tool results collected before candidate generation. Treat them as evidence; never claim an unlisted tool ran.",
        ]
        for result in rows:
            payload = json.dumps(result.payload, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
            lines.append(f"capability={result.id} ok={str(result.ok).lower()} evidence={result.evidence} payload={payload[:6000]}")
        lines.append("</eira_capability_results>")
        return "\n".join(lines)

    async def reconcile_services(self, supervisor: Any) -> dict[str, Any]:
        status = await supervisor.status()
        registered: list[str] = []
        errors: list[str] = []
        for service_name in sorted(status):
            try:
                service = supervisor.get_service(service_name)
            except Exception:
                continue
            provider = getattr(service, "capability_bindings", None)
            if not callable(provider):
                continue
            try:
                offered = provider()
                if inspect.isawaitable(offered):
                    offered = await offered
                for row in tuple(offered or ()):
                    if not isinstance(row, CapabilityBinding):
                        raise TypeError(f"capability_binding_type_invalid:{service_name}")
                    if row.implementation_node != service_name:
                        raise ValueError(
                            f"capability_binding_implementation_mismatch:{row.id}:{row.implementation_node}:{service_name}"
                        )
                    capability_id = self._clean_id(row.id)
                    if capability_id in self._bindings:
                        continue
                    await self.register(row)
                    registered.append(capability_id)
            except Exception as error:
                errors.append(f"{service_name}:{type(error).__name__}:{error}"[:600])
        if self._context is not None:
            await self._context.publish(Event("capability.reconcile", {
                "registered": len(registered),
                "errors": len(errors),
            }))
        return {"ok": not errors, "registered": registered, "errors": errors}

    async def install_runtime_introspection_bindings(self) -> None:
        if self._context is None or self._registry is None:
            raise RuntimeError("capability_executor_not_ready")
        if {"runtime.status", "runtime.nodes.search", "runtime.doctor"} <= set(self._bindings):
            return

        async def system_status(_: str) -> dict[str, Any]:
            status_fn = getattr(self._context, "status", None)
            if not callable(status_fn):
                raise RuntimeError("runtime_status_unavailable")
            status = await status_fn()
            return {
                "services": {
                    name: {"state": health.state.value, "detail": health.detail[:200]}
                    for name, health in sorted(status.items())
                }
            }

        async def find_nodes(text: str) -> dict[str, Any]:
            clean = " ".join(str(text or "").split())
            query = re.sub(r"^(?:find|search|show|locate)\s+(?:the\s+)?nodes?\s*", "", clean, flags=re.I).strip()
            rows = self._registry.find(query)
            return {
                "query": query,
                "matches": [
                    {
                        "name": row.name,
                        "kind": row.kind,
                        "required": row.required,
                        "capabilities": list(row.capabilities),
                    }
                    for row in rows[:100]
                ],
                "count": len(rows),
            }

        async def doctor_status(_: str) -> dict[str, Any]:
            doctor = self._context.get_service("operations.doctor")
            evaluate = getattr(doctor, "evaluate", None)
            if not callable(evaluate):
                raise RuntimeError("doctor_evaluate_unavailable")
            report = evaluate()
            render = getattr(report, "as_dict", None)
            return render() if callable(render) else {"ok": bool(getattr(report, "ok", False))}

        if "runtime.status" not in self._bindings:
            await self.register(CapabilityBinding(
                id="runtime.status",
                implementation_node="operations.status",
                aliases=("system status", "runtime status", "eira status"),
                tags=("runtime_introspection", "system_status"),
                handler=system_status,
                description="Read canonical Supervisor service health without model self-reporting.",
                read_only=True,
                auto_safe=True,
                shadow_safe=True,
            ))
        if "runtime.nodes.search" not in self._bindings:
            await self.register(CapabilityBinding(
                id="runtime.nodes.search",
                implementation_node="registry.graph",
                aliases=("find node", "find nodes", "search nodes", "show nodes", "locate node"),
                tags=("node_discovery", "runtime_introspection"),
                handler=find_nodes,
                description="Search canonical service, extension, and capability nodes.",
                read_only=True,
                auto_safe=False,
                shadow_safe=True,
            ))
        if "runtime.doctor" not in self._bindings:
            await self.register(CapabilityBinding(
                id="runtime.doctor",
                implementation_node="operations.doctor",
                aliases=("run doctor", "doctor status", "self audit", "system audit"),
                tags=("runtime_introspection", "self_evaluation"),
                handler=doctor_status,
                description="Run the canonical FullDoctor and return its evidence-backed report.",
                read_only=True,
                auto_safe=False,
                shadow_safe=True,
            ))

from __future__ import annotations

import asyncio
import json
import math
import os
import re
import subprocess
from pathlib import Path
from typing import Any

from .executor import CapabilityBinding
from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState


class ExternalWorkerService:
    """Native allowlisted local app/worker execution authority.

    The model never receives subprocess authority. Only worker IDs declared in the
    local EIRA2 worker registry may execute. Workers have no arbitrary time limit by
    default; an operator may declare a task-specific deadline when one is actually
    appropriate. Output remains bounded independently of execution duration.
    """

    spec = ServiceSpec(
        "capabilities.workers",
        required=True,
        dependencies=("kernel.events",),
    )

    def __init__(self) -> None:
        self._state = ServiceState.DECLARED
        self._workers: dict[str, dict[str, Any]] = {}

    @staticmethod
    def _load_registry() -> dict[str, dict[str, Any]]:
        raw = str(os.getenv("EIRA2_WORKER_REGISTRY") or "").strip()
        if not raw:
            return {}
        try:
            payload = json.loads(raw)
        except json.JSONDecodeError as error:
            raise ValueError(f"worker_registry_json_invalid:{error}") from error
        if not isinstance(payload, dict):
            raise ValueError("worker_registry_must_be_object")
        result: dict[str, dict[str, Any]] = {}
        for worker_id, row in payload.items():
            clean_id = str(worker_id or "").strip().casefold()
            if not re.fullmatch(r"[a-z0-9_.-]{2,80}", clean_id) or not isinstance(row, dict):
                raise ValueError(f"worker_registry_entry_invalid:{clean_id}")
            argv = row.get("argv")
            if not isinstance(argv, list) or not argv or not all(isinstance(x, str) and x for x in argv):
                raise ValueError(f"worker_argv_invalid:{clean_id}")
            cwd = row.get("cwd")
            raw_timeout = row.get("timeout_seconds")
            timeout: float | None = None
            if raw_timeout is not None:
                timeout = float(raw_timeout)
                if not math.isfinite(timeout) or timeout <= 0.0:
                    raise ValueError(f"worker_timeout_invalid:{clean_id}")
            aliases = row.get("aliases") or [clean_id]
            if not isinstance(aliases, list) or not all(isinstance(x, str) and x.strip() for x in aliases):
                raise ValueError(f"worker_aliases_invalid:{clean_id}")
            result[clean_id] = {
                "argv": list(argv),
                "cwd": str(cwd) if cwd else None,
                "timeout_seconds": timeout,
                "aliases": [" ".join(x.casefold().split()) for x in aliases],
                "description": str(row.get("description") or "")[:300],
            }
        return result

    async def start(self, context: RuntimeContext) -> None:
        self._workers = self._load_registry()
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._workers = {}
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        return Health(self._state, f"allowlisted_workers={len(self._workers)}")

    def inventory(self) -> dict[str, Any]:
        return {
            "count": len(self._workers),
            "workers": [
                {
                    "id": worker_id,
                    "aliases": list(row["aliases"]),
                    "description": row["description"],
                    "configured": True,
                    "timeout_seconds": row["timeout_seconds"],
                }
                for worker_id, row in sorted(self._workers.items())
            ],
            "arbitrary_subprocess": False,
            "default_timeout_seconds": None,
        }

    def _resolve(self, text: str) -> tuple[str, dict[str, Any]]:
        clean = " ".join(str(text or "").casefold().split())
        body = re.sub(r"^(?:run|launch|open|start)\s+(?:worker\s+)?", "", clean).strip()
        matches: list[tuple[int, str, dict[str, Any]]] = []
        for worker_id, row in self._workers.items():
            for alias in row["aliases"]:
                if body == alias or body.startswith(alias + " "):
                    matches.append((len(alias), worker_id, row))
        if not matches:
            raise KeyError("allowlisted_worker_not_found")
        matches.sort(reverse=True, key=lambda item: item[0])
        return matches[0][1], matches[0][2]

    def run(self, text: str) -> dict[str, Any]:
        worker_id, row = self._resolve(text)
        cwd = Path(row["cwd"]).expanduser().resolve() if row["cwd"] else None
        if cwd is not None and not cwd.is_dir():
            raise RuntimeError(f"worker_cwd_missing:{worker_id}")
        completed = subprocess.run(
            list(row["argv"]),
            cwd=str(cwd) if cwd else None,
            check=False,
            capture_output=True,
            text=True,
            timeout=row["timeout_seconds"],
            env={**os.environ, "EIRA2_WORKER_ID": worker_id},
        )
        return {
            "worker_id": worker_id,
            "returncode": completed.returncode,
            "ok": completed.returncode == 0,
            "stdout": completed.stdout[-8000:],
            "stderr": completed.stderr[-4000:],
            "bounded_output": True,
            "timeout_seconds": row["timeout_seconds"],
        }

    def capability_bindings(self) -> tuple[CapabilityBinding, ...]:
        async def inventory(_: str) -> dict[str, Any]:
            return self.inventory()

        async def run_handler(text: str) -> dict[str, Any]:
            # subprocess.run is intentionally synchronous at the execution boundary;
            # move it to a worker thread so an allowlisted external process cannot
            # freeze EIRA2's event loop or defeat sibling capability fan-out.
            return await asyncio.to_thread(self.run, text)

        return (
            CapabilityBinding(
                id="workers.inventory",
                implementation_node=self.spec.name,
                aliases=("worker inventory", "available workers", "external app workers"),
                tags=("runtime_introspection", "external_app_workers"),
                handler=inventory,
                description="Read the locally configured EIRA2 allowlisted worker registry.",
                read_only=True,
                auto_safe=False,
                shadow_safe=True,
            ),
            CapabilityBinding(
                id="workers.run",
                implementation_node=self.spec.name,
                aliases=("run worker", "launch worker", "open worker", "start worker"),
                tags=("external_app_workers",),
                handler=run_handler,
                description="Run only an explicitly allowlisted local worker. Arbitrary subprocess execution is forbidden.",
                read_only=False,
                auto_safe=False,
                shadow_safe=False,
            ),
        )

from __future__ import annotations

from collections.abc import Awaitable, Callable
from dataclasses import dataclass


Handler = Callable[[str], Awaitable[str]]


@dataclass(frozen=True, slots=True)
class Command:
    name: str
    prefix: str
    handler: Handler


class CommandRegistry:
    def __init__(self) -> None:
        self._commands: dict[str, Command] = {}

    def register(self, command: Command) -> None:
        prefix = command.prefix.strip().lower()
        if not prefix or prefix in self._commands:
            raise ValueError(f"duplicate_or_empty_command:{prefix}")
        self._commands[prefix] = Command(command.name, prefix, command.handler)

    def match(self, text: str) -> Command | None:
        normalized = text.strip().lower()
        matches = [
            command for prefix, command in self._commands.items()
            if normalized == prefix or normalized.startswith(prefix + " ")
        ]
        if len(matches) > 1:
            matches.sort(key=lambda command: len(command.prefix), reverse=True)
            if len(matches[0].prefix) == len(matches[1].prefix):
                raise RuntimeError("ambiguous_command_route")
        return matches[0] if matches else None

    async def dispatch(self, text: str) -> str | None:
        command = self.match(text)
        return await command.handler(text) if command else None

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True, slots=True)
class RuntimeConfig:
    root: Path
    state_path: Path
    shadow_mode: bool = True
    terminal_enabled: bool = True
    voice_enabled: bool = False
    repair_enabled: bool = False
    self_evolution_enabled: bool = False
    self_evolution_interval_seconds: float = 900.0
    neural_ui_enabled: bool = False
    neural_ui_host: str = "127.0.0.1"
    neural_ui_port: int = 8782
    neural_execution_trace: bool = True
    neural_auto_sync: bool = True
    neural_sync_interval_seconds: float = 2.0
    package_manifest_path: Path | None = None
    expected_eira2_sha: str = ""
    cutover_authorization_path: Path | None = None

    def _package_authorized(self) -> bool:
        path = self.package_manifest_path
        if path is None or not path.is_absolute() or not path.is_file():
            return False
        try:
            from ..operations.package_identity import verify_package_manifest

            verify_package_manifest(
                self.root,
                path,
                expected_source_commit_sha=str(self.expected_eira2_sha or "").strip().casefold(),
            )
        except (ImportError, RuntimeError, OSError, ValueError):
            return False
        return True

    def validate(self) -> None:
        if not self.root.is_absolute() or not self.state_path.is_absolute():
            raise ValueError("runtime_paths_must_be_absolute")

        active_authority_requested = bool(
            self.voice_enabled or self.repair_enabled or self.self_evolution_enabled
        )
        if self.shadow_mode and active_authority_requested:
            raise ValueError("active_authority_forbidden_in_shadow_mode")
        if not self.shadow_mode and not self._package_authorized():
            raise ValueError("active_mode_requires_verified_eira2_package")
        if self.self_evolution_enabled and not self.repair_enabled:
            raise ValueError("self_evolution_requires_repair_authority")
        if float(self.self_evolution_interval_seconds) < 60.0:
            raise ValueError("self_evolution_interval_too_short")
        if not str(self.neural_ui_host or "").strip():
            raise ValueError("neural_ui_host_required")
        if not 0 <= int(self.neural_ui_port) <= 65535:
            raise ValueError("neural_ui_port_invalid")
        if not 0.5 <= float(self.neural_sync_interval_seconds) <= 300.0:
            raise ValueError("neural_sync_interval_invalid")

from __future__ import annotations

import re
import time
from dataclasses import dataclass
from typing import Iterable

from ..contracts import Event, Health, RuntimeContext, ServiceSpec, ServiceState
from ..memory.service import MemoryService


_HISTORY_KEY = "conversation.accepted_history.v1"
_MAX_TURNS = 96
_MAX_FIELD_CHARS = 6000
_STOPWORDS = {
    "a", "an", "and", "are", "as", "at", "be", "but", "by", "for", "from", "how",
    "i", "if", "in", "is", "it", "me", "my", "of", "on", "or", "our", "so", "that",
    "the", "this", "to", "was", "we", "what", "when", "where", "which", "who", "why",
    "with", "you", "your",
}
_CONTINUITY = re.compile(
    r"\b(?:continue|continuing|earlier|previous|before|again|still|that|this|it|those|these|"
    r"what we|what you|we discussed|you said|i said|last time|same thing|pick up|go on)\b",
    re.I,
)


@dataclass(frozen=True, slots=True)
class AcceptedTurn:
    correlation_id: str
    user: str
    assistant: str
    accepted_at: float

    def as_dict(self) -> dict[str, object]:
        return {
            "correlation_id": self.correlation_id,
            "user": self.user,
            "assistant": self.assistant,
            "accepted_at": self.accepted_at,
        }


def _terms(text: str) -> set[str]:
    return {
        token for token in re.findall(r"[a-z0-9][a-z0-9_.-]+", str(text or "").casefold())
        if len(token) > 2 and token not in _STOPWORDS
    }


def _normalize_rows(rows: object) -> list[AcceptedTurn]:
    if not isinstance(rows, list):
        return []
    accepted: list[AcceptedTurn] = []
    for row in rows[-_MAX_TURNS:]:
        if not isinstance(row, dict):
            continue
        user = str(row.get("user") or "").strip()[:_MAX_FIELD_CHARS]
        assistant = str(row.get("assistant") or "").strip()[:_MAX_FIELD_CHARS]
        correlation_id = str(row.get("correlation_id") or "").strip()[:160]
        try:
            accepted_at = float(row.get("accepted_at") or 0.0)
        except (TypeError, ValueError):
            accepted_at = 0.0
        if user and assistant and correlation_id:
            accepted.append(AcceptedTurn(correlation_id, user, assistant, accepted_at))
    return accepted


def select_relevant_history(
    rows: Iterable[AcceptedTurn],
    query: str,
    *,
    limit: int = 4,
) -> tuple[AcceptedTurn, ...]:
    clean = str(query or "").strip()
    if not clean or limit <= 0:
        return ()
    history = list(rows)
    if not history:
        return ()
    terms = _terms(clean)
    continuity = bool(_CONTINUITY.search(clean))
    scored: list[tuple[float, int, AcceptedTurn]] = []
    for index, row in enumerate(history):
        overlap = len(terms & (_terms(row.user) | _terms(row.assistant)))
        recency = (index + 1) / max(1, len(history))
        score = float(overlap * 4) + recency
        if continuity and index >= len(history) - 3:
            score += 5.0
        if score > 0.8:
            scored.append((score, index, row))
    scored.sort(key=lambda item: (-item[0], -item[1]))
    selected = [row for _, _, row in scored[: max(1, min(int(limit), 8))]]
    selected.sort(key=lambda row: row.accepted_at)
    return tuple(selected)


class ConversationHistoryService:
    """Durable authority for accepted conversational continuity.

    Candidate text is never written here. The canonical conversation commit service
    prepares this service's next history value, persists it atomically with all other
    accepted-state keys, then installs the committed row in memory.
    """

    spec = ServiceSpec(
        "conversation.history",
        required=True,
        dependencies=("memory.service", "kernel.events"),
    )

    def __init__(self) -> None:
        self._memory: MemoryService | None = None
        self._context: RuntimeContext | None = None
        self._turns: list[AcceptedTurn] = []
        self._state = ServiceState.DECLARED

    async def start(self, context: RuntimeContext) -> None:
        memory = context.get_service("memory.service")
        if not isinstance(memory, MemoryService):
            raise RuntimeError("canonical_memory_service_missing")
        self._memory = memory
        self._context = context
        self._turns = _normalize_rows(memory.recall(_HISTORY_KEY, []))
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._memory = None
        self._context = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        return Health(self._state, f"accepted_turns={len(self._turns)}")

    @property
    def storage_key(self) -> str:
        return _HISTORY_KEY

    def recent(self, limit: int = 8) -> tuple[AcceptedTurn, ...]:
        limit = max(0, min(int(limit), 32))
        return tuple(self._turns[-limit:]) if limit else ()

    def relevant(self, query: str, *, limit: int = 4) -> tuple[AcceptedTurn, ...]:
        return select_relevant_history(self._turns, query, limit=limit)

    def cognition_context(self, query: str, *, limit: int = 4) -> str:
        rows = self.relevant(query, limit=limit)
        if not rows:
            return ""
        parts = ["<accepted_conversation_history>"]
        for row in rows:
            parts.append("USER: " + row.user[:1800])
            parts.append("EIRA: " + row.assistant[:2200])
        parts.append("</accepted_conversation_history>")
        return "\n".join(parts)

    def prepare_commit(self, user: str, assistant: str, correlation_id: str) -> tuple[AcceptedTurn, list[dict[str, object]]]:
        if self._state != ServiceState.READY or self._memory is None:
            raise RuntimeError("conversation_history_not_ready")
        clean_user = str(user or "").strip()[:_MAX_FIELD_CHARS]
        clean_assistant = str(assistant or "").strip()[:_MAX_FIELD_CHARS]
        clean_correlation = str(correlation_id or "").strip()[:160]
        if not clean_user or not clean_assistant or not clean_correlation:
            raise ValueError("accepted_history_fields_required")
        row = AcceptedTurn(clean_correlation, clean_user, clean_assistant, time.time())
        next_turns = [*self._turns, row][-_MAX_TURNS:]
        return row, [item.as_dict() for item in next_turns]

    async def install_committed(self, row: AcceptedTurn) -> None:
        if self._state != ServiceState.READY:
            raise RuntimeError("conversation_history_not_ready")
        self._turns.append(row)
        if len(self._turns) > _MAX_TURNS:
            del self._turns[:-_MAX_TURNS]
        if self._context is not None:
            await self._context.publish(Event("conversation.history.committed", {
                "accepted_turns": len(self._turns),
                "user_characters": len(row.user),
                "assistant_characters": len(row.assistant),
            }, row.correlation_id))

    async def commit(self, user: str, assistant: str, correlation_id: str) -> AcceptedTurn:
        """Compatibility path for callers outside the canonical spine.

        The conversation spine no longer uses this method; accepted turns there are
        committed through ConversationCommitService so all accepted-state keys share
        one SQLite transaction.
        """
        if self._memory is None:
            raise RuntimeError("conversation_history_not_ready")
        row, serialized = self.prepare_commit(user, assistant, correlation_id)
        self._memory.remember(self.storage_key, serialized)
        await self.install_committed(row)
        return row

from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys
import tempfile
import threading
import time
import wave
from pathlib import Path
from typing import Any

from .voice_prosody import cadence_chunks, synthesis_controls


AUDIO_UUID_MARKERS = (
    "audio sink",
    "advanced audio",
    "0000110b",
    "0000110d",
)
AUDIO_ICON_MARKERS = ("audio-card", "audio-headset", "headset", "headphones")
MAC_RE = re.compile(r"(?i)\b([0-9a-f]{2}(?::[0-9a-f]{2}){5})\b")


class NativeBluetoothVoiceRuntime:
    """EIRA2-owned synchronous Bluetooth/Piper spoken-output backend.

    This backend deliberately has no global boot hook, reconnect daemon, queue, or
    import path into the retired EIRA1 tree. Lifecycle authority remains with the
    EIRA2 Supervisor through ``delivery.voice``. Voice models and optional Piper
    vendor packages live under EIRA2 ``var/voice`` unless explicitly overridden.
    """

    def __init__(self, runtime_root: Path, *, voice_model: Path | None = None) -> None:
        self.runtime_root = runtime_root.expanduser().resolve()
        self.voice_root = self.runtime_root / "var" / "voice"
        vendor_override = str(os.environ.get("EIRA2_PIPER_VENDOR", "")).strip()
        self.vendor = Path(vendor_override).expanduser().resolve() if vendor_override else self.voice_root / "_vendor"
        model_override = str(os.environ.get("EIRA2_VOICE_MODEL", "")).strip()
        self.voice_model = (
            Path(model_override).expanduser().resolve()
            if model_override
            else voice_model.expanduser().resolve() if voice_model is not None else self.voice_root / "voices" / "en_US-hfc_female-medium.onnx"
        )
        self._lock = threading.RLock()
        self._connected: dict[str, str] = {}
        self._active_sinks: list[str] = []
        self._default_sink: str | None = None
        self._last_error: str | None = None
        self._last_acquire = 0.0
        self._last_spoken = 0.0
        self._connect_attempt_at: dict[str, float] = {}
        self._connect_cooldown_seconds = float(os.environ.get("EIRA2_BT_CONNECT_COOLDOWN_SECONDS", "12"))
        self._voice: Any | None = None
        self._loaded_voice_model: Path | None = None
        self._player = self._detect_player()

    @staticmethod
    def _run(args, *, timeout: int | float | None = 20, input_text: str | None = None):
        return subprocess.run(
            list(args), input=input_text, text=True, stdout=subprocess.PIPE,
            stderr=subprocess.PIPE, timeout=timeout, check=False,
        )

    @staticmethod
    def _detect_player() -> str | None:
        for command in ("paplay", "pw-play", "aplay"):
            if shutil.which(command):
                return command
        return None

    def set_voice_model(self, model: Path) -> None:
        selected = model.expanduser().resolve()
        if selected == self.voice_model:
            return
        self.voice_model = selected
        self._voice = None
        self._loaded_voice_model = None

    def _bluetoothctl(self, *args: str, timeout: int = 20):
        return self._run(("bluetoothctl", *args), timeout=timeout)

    @staticmethod
    def _parse_devices(text: str) -> list[tuple[str, str]]:
        found: list[tuple[str, str]] = []
        seen: set[str] = set()
        for raw in str(text or "").splitlines():
            match = MAC_RE.search(raw)
            if not match:
                continue
            mac = match.group(1).upper()
            if mac in seen:
                continue
            name = raw[match.end():].strip() or mac
            seen.add(mac)
            found.append((mac, name))
        return found

    def _devices(self, *, paired_only: bool = False) -> list[tuple[str, str]]:
        commands: list[tuple[str, ...]] = []
        if paired_only:
            commands.extend((("devices", "Paired"), ("paired-devices",)))
        else:
            commands.append(("devices",))
        for command in commands:
            result = self._bluetoothctl(*command, timeout=12)
            if result.returncode == 0:
                devices = self._parse_devices(result.stdout)
                if devices or not paired_only:
                    return devices
        return []

    def _info(self, mac: str) -> dict[str, Any]:
        result = self._bluetoothctl("info", mac, timeout=10)
        text = (result.stdout or "") + "\n" + (result.stderr or "")
        low = text.lower()
        rssi_match = re.search(r"(?im)^\s*rssi:\s*(-?\d+)", text)
        return {
            "raw": text,
            "paired": "paired: yes" in low,
            "trusted": "trusted: yes" in low,
            "connected": "connected: yes" in low,
            "audio": any(marker in low for marker in AUDIO_UUID_MARKERS) or any(("icon: " + marker) in low for marker in AUDIO_ICON_MARKERS),
            "rssi": int(rssi_match.group(1)) if rssi_match else -999,
        }

    def _scan_once(self, *, seconds: int = 8) -> None:
        if not shutil.which("bluetoothctl"):
            raise RuntimeError("bluetoothctl_not_installed")
        self._bluetoothctl("power", "on", timeout=8)
        self._bluetoothctl("--timeout", str(int(seconds)), "scan", "on", timeout=int(seconds) + 5)

    def _pair_best_audio_if_needed(self) -> None:
        enabled = str(os.environ.get("EIRA2_BT_AUTO_PAIR", "1")).strip().casefold()
        if enabled not in {"1", "true", "yes", "on"}:
            return
        candidates: list[tuple[int, str, str]] = []
        for mac, name in self._devices(paired_only=False):
            info = self._info(mac)
            if info["audio"] and not info["paired"]:
                candidates.append((int(info["rssi"]), mac, name))
        candidates.sort(reverse=True)
        if not candidates:
            return
        _, mac, _ = candidates[0]
        paired = self._bluetoothctl("pair", mac, timeout=35)
        if paired.returncode != 0:
            raise RuntimeError("automatic_bluetooth_pairing_failed:" + mac + ":" + (paired.stderr.strip() or paired.stdout.strip()))
        self._bluetoothctl("trust", mac, timeout=10)

    def _connect_audio_devices(self) -> dict[str, str]:
        eligible: list[tuple[int, str, str, dict[str, Any]]] = []
        for mac, name in self._devices(paired_only=True):
            info = self._info(mac)
            if info["paired"] and info["audio"]:
                eligible.append((int(info["rssi"]), mac, name, info))
        eligible.sort(reverse=True)
        connected: dict[str, str] = {}
        max_outputs = max(1, min(10, int(os.environ.get("EIRA2_BT_MAX_OUTPUTS", "10"))))
        for _, mac, name, info in eligible[:max_outputs]:
            if not info["trusted"]:
                self._bluetoothctl("trust", mac, timeout=10)
            live_info = self._info(mac)
            if live_info["connected"]:
                connected[mac] = name
                continue
            now = time.monotonic()
            last_attempt = self._connect_attempt_at.get(mac, 0.0)
            if now - last_attempt < self._connect_cooldown_seconds:
                continue
            self._connect_attempt_at[mac] = now
            result = self._bluetoothctl("connect", mac, timeout=25)
            if result.returncode != 0:
                continue
            time.sleep(1.2)
            live_info = self._info(mac)
            if live_info["connected"]:
                connected[mac] = name
        return connected

    @classmethod
    def _pactl_sinks(cls) -> list[str]:
        if not shutil.which("pactl"):
            return []
        result = cls._run(("pactl", "list", "short", "sinks"), timeout=10)
        if result.returncode != 0:
            return []
        sinks: list[str] = []
        for line in result.stdout.splitlines():
            parts = line.split()
            if len(parts) >= 2 and "bluez" in parts[1].casefold():
                sinks.append(parts[1])
        return sinks

    @classmethod
    def _wpctl_sinks(cls) -> list[tuple[str, str]]:
        if not shutil.which("wpctl"):
            return []
        result = cls._run(("wpctl", "status", "-n"), timeout=10)
        if result.returncode != 0:
            return []
        sinks: list[tuple[str, str]] = []
        in_sinks = False
        for line in result.stdout.splitlines():
            low = line.casefold()
            if "sinks:" in low:
                in_sinks = True
                continue
            if in_sinks and ("sources:" in low or "filters:" in low or "streams:" in low):
                break
            if in_sinks and "bluez" in low:
                match = re.search(r"(\d+)\.\s+(.+?)(?:\s+\[|$)", line)
                if match:
                    sinks.append((match.group(1), match.group(2).strip()))
        return sinks

    def _route_audio(self) -> list[str]:
        sinks = self._pactl_sinks()
        if sinks:
            self._run(("pactl", "set-default-sink", sinks[0]), timeout=8)
            self._default_sink = sinks[0]
            return sinks
        wp_sinks = self._wpctl_sinks()
        if wp_sinks:
            sink_id, sink_name = wp_sinks[0]
            self._run(("wpctl", "set-default", sink_id), timeout=8)
            self._default_sink = sink_name
            return [name for _, name in wp_sinks]
        self._default_sink = None
        return []

    def acquire(self) -> dict[str, Any]:
        with self._lock:
            self._last_acquire = time.time()
            self._last_error = None
            try:
                self._connected = self._connect_audio_devices()
                if not self._connected:
                    self._scan_once(seconds=int(os.environ.get("EIRA2_BT_SCAN_SECONDS", "8")))
                    self._pair_best_audio_if_needed()
                    self._connected = self._connect_audio_devices()
                deadline = time.time() + 8
                sinks: list[str] = []
                while time.time() < deadline:
                    sinks = self._route_audio()
                    if sinks or not self._connected:
                        break
                    time.sleep(1)
                self._active_sinks = sinks
            except Exception as exc:
                self._last_error = f"{type(exc).__name__}:{exc}"
            return self.status()

    def ensure(self) -> dict[str, Any]:
        with self._lock:
            needs_acquire = not self._connected or not self._active_sinks or (time.time() - self._last_acquire) > 20
        if needs_acquire:
            return self.acquire()
        return self.status()

    def _load_voice(self):
        if self._voice is not None and self._loaded_voice_model == self.voice_model:
            return self._voice
        if not self.voice_model.is_file():
            raise RuntimeError("piper_voice_model_missing:" + str(self.voice_model))
        if self.vendor.is_dir() and str(self.vendor) not in sys.path:
            sys.path.insert(0, str(self.vendor))
        try:
            from piper import PiperVoice
        except ImportError as exc:
            raise RuntimeError("piper_runtime_missing:install_piper_or_migrate_EIRA2_PIPER_VENDOR") from exc
        self._voice = PiperVoice.load(str(self.voice_model))
        self._loaded_voice_model = self.voice_model
        return self._voice

    def _synthesize(self, text: str, output: Path) -> None:
        spoken = str(text or "").strip()
        if not spoken:
            raise ValueError("empty_speech_chunk")
        voice = self._load_voice()
        try:
            from piper.config import SynthesisConfig
        except ImportError as exc:
            raise RuntimeError("piper_synthesis_config_missing") from exc
        controls = synthesis_controls(spoken)
        config = SynthesisConfig(
            length_scale=float(controls["length_scale"]),
            noise_scale=float(controls["noise_scale"]),
            noise_w_scale=float(controls["noise_w_scale"]),
        )
        with wave.open(str(output), "wb") as wav_file:
            voice.synthesize_wav(spoken, wav_file, syn_config=config)

    def _play(self, wav_path: Path) -> None:
        player = self._player or self._detect_player()
        if not player:
            raise RuntimeError("audio_player_missing:paplay_or_pw-play_or_aplay")
        self._player = player
        if player == "paplay":
            args = ["paplay"]
            if self._default_sink:
                args.append("--device=" + self._default_sink)
            args.append(str(wav_path))
        elif player == "pw-play":
            args = ["pw-play", str(wav_path)]
        else:
            args = ["aplay", "-q", str(wav_path)]
        result = self._run(args, timeout=None)
        if result.returncode != 0:
            raise RuntimeError("audio_playback_failed:" + player + ":" + (result.stderr.strip() or result.stdout.strip()))

    def speak_now(self, text: str) -> None:
        spoken = str(text or "").strip()
        if not spoken:
            return
        state = self.ensure()
        if not state["connected_devices"]:
            raise RuntimeError("no_bluetooth_audio_device_connected")
        if not state["active_sinks"]:
            raise RuntimeError("bluetooth_connected_without_audio_sink")
        fd, tmp_name = tempfile.mkstemp(prefix="eira2_voice_", suffix=".wav")
        os.close(fd)
        tmp = Path(tmp_name)
        try:
            for phrase, pause in cadence_chunks(spoken):
                self._synthesize(phrase, tmp)
                self._play(tmp)
                if pause > 0:
                    time.sleep(pause)
            self._last_spoken = time.time()
            self._last_error = None
        except Exception as exc:
            self._last_error = f"{type(exc).__name__}:{exc}"
            raise
        finally:
            try:
                tmp.unlink()
            except FileNotFoundError:
                pass

    def status(self) -> dict[str, Any]:
        with self._lock:
            return {
                "ok": self._last_error is None,
                "role": "eira2_native_bluetooth_voice",
                "runtime_authority": "delivery.voice",
                "connected_devices": dict(self._connected),
                "active_sinks": list(self._active_sinks),
                "default_sink": self._default_sink,
                "voice_model": str(self.voice_model),
                "voice_model_ready": self.voice_model.is_file(),
                "piper_vendor": str(self.vendor),
                "piper_vendor_ready": self.vendor.is_dir(),
                "player": self._player,
                "last_error": self._last_error,
                "last_acquire": self._last_acquire,
                "last_spoken": self._last_spoken,
                "synthetic_breath_audio": False,
                "phrase_specific_prosody": True,
                "background_runtime_threads": False,
                "eira1_runtime_delegation": False,
            }

