SearchProvider = Callable[[str, int], list[dict[str, str]]]
FetchProvider = Callable[[str], str]

_MAX_FETCH = 2_000_000
_MAX_SOURCE_TEXT = 12_000
_MAX_QUERY = 800
_MAX_CONTEXT = 24_000

_TRUSTED_NEWS = (
    "reuters.com", "apnews.com", "bbc.com", "bbc.co.uk", "npr.org", "pbs.org",
)
_TRUSTED_SPECIALISTS = (
    "weather.gov", "noaa.gov", "nasa.gov", "cdc.gov", "nih.gov", "nist.gov",
    "usgs.gov", "fda.gov", "epa.gov", "bls.gov", "census.gov",
)
_STOPWORDS = {
    "a", "an", "and", "are", "as", "at", "be", "been", "but", "by", "can", "could",
    "did", "do", "does", "for", "from", "had", "has", "have", "how", "i", "if", "in",
    "is", "it", "its", "me", "my", "of", "on", "or", "our", "please", "so", "that",
