    "what", "when", "where", "which", "who", "why", "will", "with", "would", "you", "your",
}

_FRESHNESS = re.compile(
    r"\b(?:today|tonight|yesterday|tomorrow|now|right now|currently|current|latest|newest|recent|recently|"
    r"this (?:week|month|year)|next (?:week|month|year)|upcoming|still|as of|just announced|just released)\b",
    re.I,
)
_MUTABLE_STATE = re.compile(
    r"\b(?:weather|forecast|temperature|price|cost|stock price|share price|crypto price|exchange rate|score|scores|"
    r"standings|schedule|availability|available now|open now|hours|current law|current rule|regulation|officeholder|"
    r"president|prime minister|governor|mayor|ceo|chair|grant deadline|grant status|release notes|version|firmware|"
    r"browser support|compatibility|outage|status page|election result|polling)\b",
    re.I,
)
_EVENT_CLAIM = re.compile(
    r"\b(?:announced|released|launched|acquired|merged|resigned|appointed|approved|banned|blocked|won|lost|"
    r"died|shut down|opened|closed|raised|cut|recalled|filed|sued|settled|signed|passed|vetoed|discovered|reported)\b",
    re.I,
)
_EXPLICIT_RESEARCH = re.compile(
    r"\b(?:search(?: the)? web|search(?: the)? internet|browse(?: the)? web|look (?:it|this|that) up|online|website|"
    r"web research|research this|fact[- ]?check|source|sources|citation|cite|according to|study|studies|dataset|news)\b",
    re.I,
)
_URL_RE = re.compile(r"https?://[^\s]+", re.I)
_SOCIAL = re.compile(
    r"^(?:hey|hi|hello|yo|good morning|good afternoon|good evening|how are you|how're you|"
    r"how is it going|how's it going|what's up|what is up|how have you been)\b",
    re.I,
)
_PERSONAL_OR_DISCOURSE = re.compile(
    r"^(?:i\b|i'm\b|im\b|i am\b|we\b|my\b|our\b|that\b|this\b|"
    r"now\s+(?:give|tell|show|explain|continue|go|let|help)\b)",
    re.I,
)
_EXTERNAL_QUESTION = re.compile(
    r"^(?:what|when|where|who|which|how|is|are|did|does|do|has|have|will|can|could)\b",
    re.I,
)


@dataclass(frozen=True, slots=True)
