import ast
import csv
import hashlib
from dataclasses import dataclass, field
from pathlib import Path, PurePosixPath
from typing import Iterable, Iterator


def _stable_id(prefix: str, value: str) -> str:
    digest = hashlib.sha256(value.encode("utf-8", errors="replace")).hexdigest()[:20]
    return f"{prefix}:{digest}"


@dataclass(frozen=True, slots=True)
class NeuralNode:
    id: str
    kind: str
    label: str
    source_path: str = ""
    sha256: str = ""
    size: int = 0
    disposition: str = ""
    parent_id: str | None = None


@dataclass(frozen=True, slots=True)
class NeuralEdge:
    source: str
    target: str
    kind: str
    conductive: bool


@dataclass(slots=True)
class NeuralGraph:
    nodes: dict[str, NeuralNode] = field(default_factory=dict)
    edges: set[NeuralEdge] = field(default_factory=set)
    path_to_node: dict[str, str] = field(default_factory=dict)

    def add_node(self, node: NeuralNode) -> None:
        current = self.nodes.get(node.id)
        if current is not None and current != node:
            raise ValueError(f"neural_node_collision:{node.id}")
        self.nodes[node.id] = node
        if node.source_path:
            self.path_to_node[node.source_path] = node.id

    def add_edge(self, edge: NeuralEdge) -> None:
        if edge.source == edge.target:
            return
        if edge.source not in self.nodes or edge.target not in self.nodes:
            raise ValueError(f"neural_edge_unknown_node:{edge.source}:{edge.target}")
        self.edges.add(edge)

    def summary(self) -> dict:
        file_nodes = sum(1 for node in self.nodes.values() if node.kind == "file_neuron")
        structural_nodes = len(self.nodes) - file_nodes
        conductive_edges = sum(1 for edge in self.edges if edge.conductive)
        return {
            "schema": "eira2_neural_graph_v1",
            "nodes": len(self.nodes),
            "file_neurons": file_nodes,
            "structural_nodes": structural_nodes,
            "edges": len(self.edges),
            "conductive_edges": conductive_edges,
            "structural_edges": len(self.edges) - conductive_edges,
            "all_file_neurons_addressable": True,
            "structural_membership_is_not_claimed_computation": True,
        }

    def page(self, *, offset: int = 0, limit: int = 2000, kind: str | None = None) -> dict:
        limit = max(1, min(5000, int(limit)))
        rows = sorted(self.nodes.values(), key=lambda node: node.id)
        if kind:
            rows = [node for node in rows if node.kind == kind]
        chunk = rows[max(0, int(offset)):max(0, int(offset)) + limit]
        ids = {node.id for node in chunk}
        edges = [edge for edge in self.edges if edge.source in ids or edge.target in ids]
        return {
            **self.summary(),
            "offset": max(0, int(offset)),
            "limit": limit,
            "returned_nodes": len(chunk),
            "has_more": max(0, int(offset)) + len(chunk) < len(rows),
            "node_rows": [node.__dict__ if hasattr(node, "__dict__") else {
                "id": node.id,
                "kind": node.kind,
                "label": node.label,
                "source_path": node.source_path,
                "sha256": node.sha256,
                "size": node.size,
                "disposition": node.disposition,
                "parent_id": node.parent_id,
            } for node in chunk],
            "edge_rows": [
                {"source": edge.source, "target": edge.target, "kind": edge.kind, "conductive": edge.conductive}
                for edge in sorted(edges, key=lambda row: (row.source, row.target, row.kind))
            ],
        }


def ledger_rows(path: Path) -> Iterator[dict[str, str]]:
    with path.open("r", encoding="utf-8", errors="replace", newline="") as handle:
        yield from csv.DictReader(handle)


def _normalize_source_path(raw: str) -> str:
    return str(raw or "").replace("\\", "/")


def graph_from_ledger(rows: Iterable[dict[str, str]]) -> NeuralGraph:
    graph = NeuralGraph()
    root = NeuralNode("system:eira2", "system", "EIRA 2.0")
    graph.add_node(root)
    group_ids: dict[tuple[str, ...], str] = {}

    for row in rows:
        source = _normalize_source_path(row.get("source_path") or "")
        if not source:
            continue
        entry_type = str(row.get("entry_type") or "file").casefold()
        parts = tuple(part for part in PurePosixPath(source).parts if part not in {"/", ""})
        parent_id = root.id
        lineage: list[str] = []
        for part in parts[:-1]:
            lineage.append(part)
            key = tuple(lineage)
            group_id = group_ids.get(key)
            if group_id is None:
                group_id = _stable_id("tract", "/".join(lineage))
                group_ids[key] = group_id
                graph.add_node(NeuralNode(group_id, "tract", part, parent_id=parent_id))
                graph.add_edge(NeuralEdge(parent_id, group_id, "structural_membership", False))
            parent_id = group_id

        if entry_type in {"file", "regular", "regular_file"}:
            node_kind = "file_neuron"
        elif entry_type in {"dir", "directory"}:
            node_kind = "tract_marker"
        elif entry_type in {"symlink", "link"}:
            node_kind = "synapse_reference"
        else:
            node_kind = "canonical_entry"
        neuron_id = _stable_id("neuron", source)
        try:
            size = int(row.get("size") or 0)
        except (TypeError, ValueError):
            size = 0
        graph.add_node(NeuralNode(
            neuron_id,
            node_kind,
            parts[-1] if parts else source,
            source_path=source,
            sha256=str(row.get("sha256") or ""),
            size=size,
            disposition=str(row.get("disposition") or ""),
            parent_id=parent_id,
        ))
        graph.add_edge(NeuralEdge(parent_id, neuron_id, "structural_membership", False))
    return graph


def _module_name(root: Path, path: Path) -> str | None:
    try:
        relative = path.resolve().relative_to(root.resolve())
    except ValueError:
        return None
    if relative.suffix != ".py":
        return None
    parts = list(relative.with_suffix("").parts)
    if parts and parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts) if parts else None


def add_python_import_fibers(graph: NeuralGraph, root: Path) -> int:
    module_to_node: dict[str, str] = {}
    path_by_node: dict[str, Path] = {}
    root = root.resolve()
    for source, node_id in graph.path_to_node.items():
        path = Path(source)
        if path.suffix != ".py" or not path.is_file():
            continue
        module = _module_name(root, path)
        if module:
            module_to_node[module] = node_id
            path_by_node[node_id] = path

    before = len(graph.edges)
    for source_id, path in path_by_node.items():
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="replace"), filename=str(path))
        except (OSError, SyntaxError):
            continue
        targets: set[str] = set()
        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                targets.update(alias.name for alias in node.names)
            elif isinstance(node, ast.ImportFrom) and node.module:
                targets.add(node.module)
        for module in targets:
            candidate = module
            while candidate:
                target_id = module_to_node.get(candidate)
                if target_id:
                    graph.add_edge(NeuralEdge(source_id, target_id, "python_import", True))
                    break
                candidate = candidate.rpartition(".")[0]
    return len(graph.edges) - before


def activity_overlay(graph: NeuralGraph, active_paths: Iterable[str]) -> dict:
    active = []
    for raw in active_paths:
        source = _normalize_source_path(raw)
        node_id = graph.path_to_node.get(source)
        if node_id and node_id not in active:
            active.append(node_id)
    conductive = [
        {"source": edge.source, "target": edge.target, "kind": edge.kind}
        for edge in graph.edges
        if edge.conductive and (edge.source in active or edge.target in active)
    ]
    return {
        "schema": "eira2_neural_activity_overlay_v1",
        "active_neurons": active,
        "active_conductive_fibers": conductive,
        "synthetic_activity": False,
    }

from __future__ import annotations

import argparse
import json
import sys
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any


def _live_receipt(root: Path) -> dict[str, Any]:
    path = root.expanduser().resolve() / "var" / "eira2-live-runtime.json"
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise RuntimeError(f"eira2_live_receipt_unavailable:{type(error).__name__}") from error
    if not isinstance(payload, dict):
        raise RuntimeError("eira2_live_receipt_invalid")
    if payload.get("active") is not True or payload.get("runtime_authority") != "eira2":
        raise RuntimeError("eira2_live_runtime_not_active")
    try:
        port = int(payload.get("neural_ui_port"))
    except (TypeError, ValueError) as error:
        raise RuntimeError("eira2_live_runtime_port_invalid") from error
    if not 1 <= port <= 65535:
        raise RuntimeError("eira2_live_runtime_port_invalid")
    return payload


def _submit(root: Path, text: str, *, timeout_seconds: float = 240.0) -> dict[str, Any]:
    clean = str(text or "").strip()
    if not clean:
        raise ValueError("terminal_message_empty")
    receipt = _live_receipt(root)
    port = int(receipt["neural_ui_port"])
    request = urllib.request.Request(
        f"http://127.0.0.1:{port}/v1/text",
        data=json.dumps({"text": clean}).encode("utf-8"),
        headers={"Content-Type": "application/json"},
        method="POST",
    )
    try:
        with urllib.request.urlopen(request, timeout=float(timeout_seconds)) as response:
            payload = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        try:
            body = error.read().decode("utf-8", errors="replace")
        except OSError:
            body = ""
        raise RuntimeError(f"eira2_terminal_http_error:{error.code}:{body[:300]}") from error
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise RuntimeError(f"eira2_terminal_runtime_unreachable:{type(error).__name__}:{error}") from error
    if not isinstance(payload, dict):
        raise RuntimeError("eira2_terminal_response_invalid")
    if payload.get("verified") is not True or payload.get("ok") is not True:
        raise RuntimeError("eira2_terminal_response_unverified:" + str(payload.get("error") or "unknown")[:300])
    return payload


def _print_response(payload: dict[str, Any]) -> None:
    sys.stdout.write(str(payload.get("response") or "") + "\n")
    sys.stdout.flush()


def _read_multiline() -> str:
    lines: list[str] = []
    sys.stdout.write("multiline> finish with a line containing only :send\n")
    sys.stdout.flush()
    while True:
        line = sys.stdin.readline()
        if line == "":
            break
        if line.rstrip("\r\n") == ":send":
            break
        lines.append(line.rstrip("\r\n"))
    return "\n".join(lines).strip()


def interactive(root: Path, *, timeout_seconds: float = 240.0) -> int:
    # Validate the daemon before presenting a prompt. A stale receipt or stopped
    # daemon fails closed rather than spawning a competing EIRA2 runtime.
    _live_receipt(root)
    sys.stdout.write("EIRA2 terminal connected. :multi for multiline, :quit to exit.\n")
    sys.stdout.flush()
    while True:
        try:
            line = input("you> ")
        except EOFError:
            return 0
        clean = line.strip()
        if not clean:
            continue
        if clean in {":quit", ":exit"}:
            return 0
        if clean == ":multi":
            clean = _read_multiline()
            if not clean:
                continue
        _print_response(_submit(root, clean, timeout_seconds=timeout_seconds))


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Talk to the one already-running EIRA2 daemon through canonical local text ingress."
    )
    parser.add_argument("--root", type=Path, required=True)
    parser.add_argument("--timeout", type=float, default=240.0)
    parser.add_argument("message", nargs="*")
    args = parser.parse_args()
    root = args.root.expanduser().resolve()
    try:
        if args.message:
            _print_response(_submit(root, " ".join(args.message), timeout_seconds=args.timeout))
            return 0
        if not sys.stdin.isatty():
            text = sys.stdin.read().strip()
            if not text:
                raise ValueError("terminal_message_empty")
            _print_response(_submit(root, text, timeout_seconds=args.timeout))
            return 0
        return interactive(root, timeout_seconds=args.timeout)
    except (RuntimeError, ValueError) as error:
        print(f"EIRA2 terminal error: {error}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

