ctor(b); d=b-a; L=d.length\n if L<1e-6:return\n bpy.ops.mesh.primitive_cylinder_add(vertices=16,radius=r,depth=L,location=(a+b)/2); o=bpy.context.object; o.name=name; o.rotation_mode="QUATERNION"; o.rotation_quaternion=d.to_track_quat("Z","Y")\nfor j,e in enumerate(S.get("links",[])):\n pts=e.get("path") or []; A=P.get(str(e.get("source"))); B=P.get(str(e.get("target")))\n if not pts and A and B: pts=[list(A.location),list(B.location)]\n elif pts and A and B: pts=[list(A.location)]+pts+[list(B.location)]\n for q in range(len(pts)-1): seg(pts[q],pts[q+1],f"link_{{j}}_{{q}}",float((e.get("attrs") or {{}}).get("radius",.02)))\nbpy.context.scene.render.engine="BLENDER_EEVEE_NEXT"\nobjs=[o for o in bpy.context.scene.objects if o.type=="MESH"]\nif objs:\n xs=[];ys=[];zs=[]\n for o in objs:\n  for c in o.bound_box:\n   w=o.matrix_world@Vector(c); xs.append(w.x);ys.append(w.y);zs.append(w.z)\n ctr=Vector(((min(xs)+max(xs))/2,(min(ys)+max(ys))/2,(min(zs)+max(zs))/2)); size=max(max(xs)-min(xs),max(ys)-min(ys),max(zs)-min(zs),1)\nelse: ctr=Vector((0,0,0)); size=5\nviews=[("front",(0,-1,0)),("rear",(0,1,0)),("left",(-1,0,0)),("right",(1,0,0)),("top",(0,0,1)),("iso1",(1,-1,.7)),("iso2",(-1,-1,.7)),("iso3",(1,1,.7))]\nfor n,d in views:\n bpy.ops.object.camera_add(location=ctr+Vector(d).normalized()*size*2.2); c=bpy.context.object; c.data.lens=52; c.rotation_euler=((ctr-c.location).to_track_quat("-Z","Y")).to_euler(); bpy.context.scene.camera=c; bpy.context.scene.render.resolution_x=768; bpy.context.scene.render.resolution_y=768; bpy.context.scene.render.filepath=os.path.join(RD,n+".png"); bpy.ops.render.render(write_still=True); bpy.data.objects.remove(c,do_unlink=True)\nbpy.ops.export_scene.gltf(filepath=OUT,export_format="GLB")\ntry: bpy.ops.wm.usd_export(filepath=os.path.splitext(OUT)[0]+".usdc")\nexcept Exception as e: print("USD_EXPORT_WARNING",e)\n'''


def _safe(value: Any) -> str:
    text = "".join(c if c.isalnum() or c == "_" else "_" for c in str(value))
    return ("p_" + text) if not text or text[0].isdigit() else text


def write_usda(spec: dict[str, Any], path: Path) -> Path:
    path = Path(path)
    lines = ['#usda 1.0', '(', '    defaultPrim = "Root"', '    metersPerUnit = 1', '    upAxis = "Z"', ')', '', 'def Xform "Root"', '{']
    materials: dict[str, dict[str, Any]] = {}
    for part in spec.get("parts", []):
        material = part.get("material") or {}
        materials.setdefault(str(material.get("name") or ("mat_" + _safe(part.get("id", "part")))), material)
    if materials:
        lines += ['    def Scope "Looks"', '    {']
        for name, material in materials.items():
            color = list(material.get("base_color", [.5, .5, .5, 1])); color += [1,1,1,1]
            r,g,b,a = [max(0.0,min(1.0,float(x))) for x in color[:4]]; n = _safe(name)
            rough=float(material.get("roughness",.45)); metal=float(material.get("metallic",0))
            lines += [f'        def Material "{n}"','        {',f'            token outputs:surface.connect = </Root/Looks/{n}/Preview.outputs:surface>','            def Shader "Preview"','            {','                uniform token info:id = "UsdPreviewSurface"',f'                color3f inputs:diffuseColor = ({r:.6f}, {g:.6f}, {b:.6f})',f'                float inputs:opacity = {a:.6f}',f'                float inputs:roughness = {rough:.6f}',f'                float inputs:metallic = {metal:.6f}','                token outputs:surface','            }','        }']
        lines += ['    }']
    for part in spec.get("parts", []):
        pid=_safe(part.get("id","part")); geom=part.get("geometry") or {}; kind=str(geom.get("kind") or geom.get("method") or "cube").lower(); prm=geom.get("params") or {}; transform=part.get("transform") or {}; mat=_safe((part.get("material") or {}).get("name") or ("mat_"+pid))
        tr=list(transform.get("translate",[0,0,0])); rot=list(transform.get("rotate_deg",[0,0,0])); scale=list(transform.get("scale",[1,1,1]))
        lines += [f'    def Xform "{pid}"','    {',f'        double3 xformOp:translate = ({float(tr[0])}, {float(tr[1])}, {float(tr[2])})',f'        float3 xformOp:rotateXYZ = ({float(rot[0])}, {float(rot[1])}, {float(rot[2])})',f'        float3 xformOp:scale = ({float(scale[0])}, {float(scale[1])}, {float(scale[2])})','        uniform token[] xformOpOrder = ["xformOp:translate", "xformOp:rotateXYZ", "xformOp:scale"]']
        if kind in ('cube','box','primitive'): lines += ['        def Cube "Geom"','        {','            double size = 2']
