def validate_usdz(path: Path) -> dict[str, Any]:
    path=Path(path)
    if not path.is_file() or path.stat().st_size<64: raise ValueError('usdz_missing_or_too_small')
    if path.read_bytes()[:4]!=b'PK\x03\x04': raise ValueError('usdz_bad_zip')
    with zipfile.ZipFile(path,'r') as archive:
        infos=archive.infolist()
        if not infos: raise ValueError('usdz_empty_archive')
        for info in infos:
            if info.compress_type!=zipfile.ZIP_STORED: raise ValueError('usdz_compression_forbidden')
            if info.file_size<=0: raise ValueError('usdz_empty_member')
            with path.open('rb') as handle: handle.seek(info.header_offset); header=handle.read(30)
            if len(header)!=30 or header[:4]!=b'PK\x03\x04': raise ValueError('usdz_bad_local_header')
            name_len,extra_len=struct.unpack_from('<HH',header,26); data_start=info.header_offset+30+name_len+extra_len
            if data_start%64!=0: raise ValueError('usdz_alignment_failed')
        bad=archive.testzip()
        if bad is not None: raise ValueError('usdz_crc_failed:'+bad)
    root=infos[0].filename.lower()
    if not root.endswith(('.usd','.usda','.usdc')): raise ValueError('usdz_root_layer_not_usd')
    return {'ok':True,'members':len(infos),'root_layer':infos[0].filename,'bytes':path.stat().st_size,'compression':'stored','alignment_bytes':64}


