def _num(value: Any, default: float | None = None) -> float | None:
    try:
        out = float(value)
    except (TypeError, ValueError):
        return default
    return out if math.isfinite(out) else default


def _positive(value: Any, default: float | None = None) -> float | None:
    out = _num(value, default)
    return out if out is not None and out > 0 else default


def _v3(value: Any, default=(0.0, 0.0, 0.0)) -> list[float]:
    row = list(value or default)
    return [float(row[i] if i < len(row) else default[i]) for i in range(3)]


def expand(spec: dict[str, Any], max_parts: int = 20_000) -> dict[str, Any]:
    out: list[dict[str, Any]] = []
    for part in spec.get("parts", []):
        if not isinstance(part, dict):
            continue
        pattern = part.get("pattern") or {}
        kind = str(pattern.get("kind") or "").lower()
        if kind == "linear":
            count = max(1, int(pattern.get("count", 1)))
            step = _v3(pattern.get("step"))
            for i in range(count):
                row = copy.deepcopy(part); row.pop("pattern", None)
                row["id"] = f"{part.get('id', 'part')}_{i:04d}"
                transform = row.setdefault("transform", {})
                transform["translate"] = [a + i * b for a, b in zip(_v3(transform.get("translate")), step)]
                out.append(row)
        elif kind == "grid":
            count = pattern.get("count", [1, 1, 1])
            steps = pattern.get("step", [[1, 0, 0], [0, 1, 0], [0, 0, 1]])
            for i in range(int(count[0])):
                for j in range(int(count[1])):
                    for k in range(int(count[2])):
                        row = copy.deepcopy(part); row.pop("pattern", None)
                        row["id"] = f"{part.get('id', 'part')}_{i}_{j}_{k}"
                        transform = row.setdefault("transform", {}); base = _v3(transform.get("translate"))
                        transform["translate"] = [base[a] + i*_v3(steps[0])[a] + j*_v3(steps[1])[a] + k*_v3(steps[2])[a] for a in range(3)]
                        out.append(row)
        elif kind == "radial":
            count = max(1, int(pattern.get("count", 1))); center = _v3(pattern.get("center"))
            radius = float(pattern.get("radius", 1)); axis = str(pattern.get("axis", "z")).lower()
            for i in range(count):
                angle = 2 * math.pi * i / count
                row = copy.deepcopy(part); row.pop("pattern", None); row["id"] = f"{part.get('id', 'part')}_{i:04d}"
                pos = [center[0]+radius*math.cos(angle), center[1]+radius*math.sin(angle), center[2]]
                if axis == "y": pos = [center[0]+radius*math.cos(angle), center[1], center[2]+radius*math.sin(angle)]
                if axis == "x": pos = [center[0], center[1]+radius*math.cos(angle), center[2]+radius*math.sin(angle)]
                row.setdefault("transform", {})["translate"] = pos; out.append(row)
        else:
            out.append(copy.deepcopy(part))
        if len(out) > max_parts:
            raise ValueError("expanded_part_limit")
    result = copy.deepcopy(spec); result["parts"] = out; return result


def _finite3(value: Any) -> bool:
    return isinstance(value, (list, tuple)) and len(value) == 3 and all(isinstance(x, (int, float)) and math.isfinite(float(x)) for x in value)


def validate(spec: dict[str, Any]) -> list[dict[str, Any]]:
    defects: list[dict[str, Any]] = []; ids: set[str] = set()
    parts = [row for row in spec.get("parts", []) if isinstance(row, dict)]
    links = [row for row in spec.get("links", []) if isinstance(row, dict)]
    for part in parts:
        pid = str(part.get("id", "")).strip()
        if not pid or pid in ids: defects.append({"kind": "identity", "part": pid, "issue": "missing_or_duplicate_id"})
        ids.add(pid); geometry = part.get("geometry") or {}; transform = part.get("transform") or {}
        if not (geometry.get("method") or geometry.get("kind")): defects.append({"kind": "geometry", "part": pid, "issue": "missing_geometry"})
        translate = transform.get("translate", [0,0,0]); scale = transform.get("scale", [1,1,1])
        if not _finite3(translate): defects.append({"kind": "transform", "part": pid, "issue": "bad_translate"})
        if not _finite3(scale) or any(float(x) <= 0 for x in scale): defects.append({"kind": "transform", "part": pid, "issue": "bad_scale"})
    for link in links:
        source, target = link.get("source"), link.get("target")
        if source not in ids or target not in ids: defects.append({"kind": "connectivity", "link": link, "issue": "missing_endpoint"})
        if source == target: defects.append({"kind": "connectivity", "link": link, "issue": "self_link"})
    for part in parts:
        tags = set(map(str, part.get("tags", []))); eng = part.get("engineering") or {}; pid = part.get("id")
        if ("rotating" in tags or part.get("kind") in ("turbine", "fan", "rotor")) and not (eng.get("axis") or eng.get("joint")):
            defects.append({"kind": "mechanical", "part": pid, "issue": "moving_part_missing_axis_or_joint"})
        supported = any(link.get("target") == pid and link.get("kind") in ("supports", "attached_to") for link in links)
        if "elevated" in tags and "self_supporting" not in tags and not supported:
            defects.append({"kind": "structural", "part": pid, "issue": "elevated_part_missing_support"})
    return defects


def _evidence(part: dict[str, Any]) -> str:
    eng = part.get("engineering") or {}; value = str(eng.get("evidence_class") or eng.get("basis") or "inferred").strip().lower()
    return value if value in EVIDENCE_UNCERTAINTY else "inferred"


def _uncertainty(part: dict[str, Any], key: str, evidence: str) -> float:
    eng = part.get("engineering") or {}; raw = eng.get("uncertainty") or {}
    if isinstance(raw, dict):
        direct = _num(raw.get(key))
        if direct is not None: return max(0.0, min(abs(direct), 0.95))
    direct = _num(eng.get("uncertainty_fraction"))
    if direct is not None: return max(0.0, min(abs(direct), 0.95))
    return EVIDENCE_UNCERTAINTY.get(evidence, 0.15)


def _material(part: dict[str, Any]) -> tuple[dict[str, float], str]:
    raw = part.get("material") or {}; name = str(raw.get("name") or "").strip().lower().replace(" ", "_")
    props: dict[str, float] = {}; source = "unspecified"
    if name in MATERIALS: props.update(MATERIALS[name]); source = "reference_material_library"
    for src, dst in {"density":"density_kg_m3","density_kg_m3":"density_kg_m3","yield_strength_pa":"yield_strength_pa","yield_pa":"yield_strength_pa","max_service_temp_k":"max_service_temp_k","max_temp_k":"max_service_temp_k"}.items():
        value = _positive(raw.get(src))
        if value is not None: props[dst] = value; source = "spec_material_properties"
    return props, source


def _geometry(part: dict[str, Any]) -> dict[str, float | str]:
    geom = part.get("geometry") or {}; kind = str(geom.get("kind") or geom.get("method") or "cube").lower(); prm = geom.get("params") or {}
    scale = _v3((part.get("transform") or {}).get("scale"), (1.0,1.0,1.0)); sx,sy,sz = [max(abs(v),1e-9) for v in scale]
    if kind in {"cube","box","primitive"}:
        dims = prm.get("dimensions") or prm.get("size")
        if isinstance(dims,(list,tuple)) and len(dims)>=3: dx,dy,dz=[max(abs(float(dims[i])),1e-9) for i in range(3)]
        else: dx=dy=dz=float(_positive(dims,2.0) or 2.0)
        dx,dy,dz=dx*sx,dy*sy,dz*sz
        return {"kind":kind,"volume_m3":dx*dy*dz,"cross_section_m2":max(min(dx*dy,dy*dz,dx*dz),1e-12),"radius_m":max(dx,dy)/2,"length_m":max(dx,dy,dz)}
    if kind == "cylinder":
        radius=(_positive(prm.get("radius"),0.5) or 0.5)*math.sqrt(sx*sy); depth=(_positive(prm.get("depth"),_positive(prm.get("height"),1.0)) or 1.0)*sz
        return {"kind":kind,"volume_m3":math.pi*radius*radius*depth,"cross_section_m2":math.pi*radius*radius,"radius_m":radius,"length_m":depth}
    if kind == "sphere":
        radius=(_positive(prm.get("radius"),0.5) or 0.5)*(sx*sy*sz)**(1/3)
        return {"kind":kind,"volume_m3":4*math.pi*radius**3/3,"cross_section_m2":math.pi*radius*radius,"radius_m":radius,"length_m":2*radius}
    if kind == "cone":
        r1=(_positive(prm.get("radius1"),_positive(prm.get("radius"),0.5)) or 0.5)*math.sqrt(sx*sy); r2=(_positive(prm.get("radius2"),0.0) or 0.0)*math.sqrt(sx*sy); height=(_positive(prm.get("depth"),_positive(prm.get("height"),1.0)) or 1.0)*sz
        return {"kind":kind,"volume_m3":math.pi*height*(r1*r1+r1*r2+r2*r2)/3,"cross_section_m2":math.pi*max(r1,r2,1e-9)**2,"radius_m":max(r1,r2),"length_m":height}
    if kind == "torus":
        major=(_positive(prm.get("major_radius"),0.5) or 0.5)*math.sqrt(sx*sy); minor=(_positive(prm.get("minor_radius"),0.1) or 0.1)*(sx*sy*sz)**(1/3)
        return {"kind":kind,"volume_m3":2*math.pi**2*major*minor**2,"cross_section_m2":math.pi*minor**2,"radius_m":major+minor,"length_m":2*(major+minor)}
    return {"kind":kind,"volume_m3":0.0,"cross_section_m2":0.0,"radius_m":0.0,"length_m":0.0}


def _monte_carlo(checks: list[dict[str, Any]], samples: int, seed: int) -> list[dict[str, Any]]:
    rng=random.Random(seed); n=max(200,min(int(samples),10000)); out=[]
    for check in checks:
        stress=_positive(check.get("stress_pa")); strength=_positive(check.get("strength_pa")); required=_positive(check.get("required_factor_of_safety"),1.5) or 1.5
        if stress is None or strength is None: continue
        lu=max(0,min(float(check.get("load_uncertainty",.10)),.95)); gu=max(0,min(float(check.get("geometry_uncertainty",.08)),.95)); su=max(0,min(float(check.get("strength_uncertainty",.10)),.95)); margins=[]; passes=0
        for _ in range(n):
            fos=strength*max(.05,rng.gauss(1,su))/max(stress*max(.05,rng.gauss(1,lu))/max(.05,rng.gauss(1,gu)),1e-12); margins.append(fos); passes += int(fos>=required)
        margins.sort(); out.append({"name":check.get("name"),"part":check.get("part"),"samples":n,"probability_meets_required_margin":round(passes/n,6),"factor_of_safety_p05":round(margins[max(0,int(.05*(n-1)))],6),"factor_of_safety_median":round(margins[max(0,int(.5*(n-1)))],6),"required_factor_of_safety":required,"method":"deterministic_seeded_monte_carlo_uncertainty_propagation"})
    return out


def evaluate(spec: dict[str, Any], *, samples: int = 2000) -> dict[str, Any]:
    parts_out=[]; blocking=[]; warnings=[]; checks=[]; equations=[]; total_mass=0.0; total_in=0.0; total_demand=0.0
    provenance=spec.get("provenance") or {}; experimental=bool(provenance.get("experimental_data") or provenance.get("measured_test_data"))
    for part in spec.get("parts",[]):
        if not isinstance(part,dict): continue
        pid=str(part.get("id") or "part"); eng=part.get("engineering") or {}; evidence=_evidence(part); geometry=_geometry(part); mat,mat_source=_material(part); calc={}
