from __future__ import annotations

import asyncio
from dataclasses import dataclass

from ..contracts import Event, Health, Service, ServiceState
from .events import EventService


@dataclass(slots=True)
class ServiceRecord:
    service: Service
    state: ServiceState = ServiceState.DECLARED
    detail: str = ""


class Supervisor:
    """Only authority permitted to start or stop EIRA services."""

    def __init__(self) -> None:
        self._records: dict[str, ServiceRecord] = {}
        self._start_order: list[str] = []
        self._running = False
        self._lifecycle_lock = asyncio.Lock()

    def register(self, service: Service) -> None:
        if self._running:
            raise RuntimeError("use_attach_service_after_supervisor_start")
        name = service.spec.name
        if name in self._records:
            raise ValueError(f"duplicate_service:{name}")
        self._records[name] = ServiceRecord(service)

    def get_service(self, name: str) -> Service:
        return self._records[name].service

    async def publish(self, event: Event) -> None:
        events = self.get_service("kernel.events")
        if not isinstance(events, EventService):
            raise RuntimeError("canonical_event_service_missing")
        errors = await events.publish_event(event)
        if errors and event.topic != "runtime.subscriber_errors":
            await events.publish_event(Event("runtime.subscriber_errors", {
                "source_topic": event.topic,
                "count": len(errors),
                "types": [type(error).__name__ for error in errors],
            }, event.correlation_id))

    def topological_order(self) -> list[str]:
        result: list[str] = []
        temporary: set[str] = set()
        permanent: set[str] = set()

        def visit(name: str) -> None:
            if name in permanent:
                return
            if name in temporary:
                raise ValueError(f"dependency_cycle:{name}")
            if name not in self._records:
                raise ValueError(f"unknown_dependency:{name}")
            temporary.add(name)
            for dependency in self._records[name].service.spec.dependencies:
                visit(dependency)
            temporary.remove(name)
            permanent.add(name)
            result.append(name)

        for name in self._records:
            visit(name)
        return result

    async def _start_record(self, name: str, record: ServiceRecord) -> None:
        record.state = ServiceState.STARTING
        record.detail = ""
        try:
            await asyncio.wait_for(
                record.service.start(self),
                timeout=record.service.spec.start_timeout_seconds,
            )
            record.state = ServiceState.READY
            if name not in self._start_order:
                self._start_order.append(name)
        except BaseException as error:
            record.state = ServiceState.FAILED
            record.detail = f"{type(error).__name__}:{error}"
            raise

    async def start(self) -> None:
        async with self._lifecycle_lock:
            if self._running:
                return
            try:
                for name in self.topological_order():
                    record = self._records[name]
                    try:
                        await self._start_record(name, record)
                    except BaseException as error:
                        if record.service.spec.required:
                            await self._stop_started_unlocked()
                            raise RuntimeError(f"required_service_failed:{name}") from error
                self._running = True
            except BaseException:
                self._running = False
                raise

    async def _stop_record(self, name: str, record: ServiceRecord) -> None:
        record.state = ServiceState.STOPPING
        try:
            await asyncio.wait_for(
                record.service.stop(),
                timeout=record.service.spec.stop_timeout_seconds,
            )
            record.state = ServiceState.STOPPED
            record.detail = ""
        except BaseException as error:
            record.state = ServiceState.FAILED
            record.detail = f"{type(error).__name__}:{error}"
            raise
        finally:
            if name in self._start_order:
                self._start_order.remove(name)

    async def _stop_started_unlocked(self) -> None:
        for name in list(reversed(self._start_order)):
            record = self._records[name]
            try:
                await self._stop_record(name, record)
            except BaseException:
                continue
        self._start_order.clear()

    async def stop(self) -> None:
        async with self._lifecycle_lock:
            await self._stop_started_unlocked()
            self._running = False

    async def attach_service(self, service: Service) -> None:
        """Attach and start one service without giving up lifecycle authority."""
        async with self._lifecycle_lock:
            if not self._running:
                raise RuntimeError("supervisor_not_running")
            name = str(service.spec.name or "").strip()
            if not name:
                raise ValueError("dynamic_service_name_missing")
            if name in self._records:
                raise ValueError(f"duplicate_service:{name}")
            for dependency in service.spec.dependencies:
                record = self._records.get(dependency)
                if record is None:
                    raise ValueError(f"unknown_dependency:{dependency}")
                if record.state != ServiceState.READY:
                    raise RuntimeError(f"dynamic_dependency_not_ready:{name}:{dependency}:{record.state.value}")
            record = ServiceRecord(service)
            self._records[name] = record
            try:
                self.topological_order()
                await self._start_record(name, record)
            except BaseException:
                self._records.pop(name, None)
                if name in self._start_order:
                    self._start_order.remove(name)
                raise
        await self.publish(Event("runtime.service_attached", {
            "name": name,
            "dependencies": list(service.spec.dependencies),
            "required": bool(service.spec.required),
        }))

    async def detach_service(self, name: str) -> None:
        """Stop and remove a dynamic service when no running dependent needs it."""
        clean = str(name or "").strip()
        async with self._lifecycle_lock:
            if not self._running:
                raise RuntimeError("supervisor_not_running")
            record = self._records.get(clean)
            if record is None:
                raise KeyError(clean)
            if record.service.spec.required:
                raise RuntimeError(f"required_service_detach_forbidden:{clean}")
            dependents = [
                other_name
                for other_name, other in self._records.items()
                if other_name != clean
                and clean in other.service.spec.dependencies
                and other.state in {ServiceState.STARTING, ServiceState.READY, ServiceState.DEGRADED}
            ]
            if dependents:
                raise RuntimeError(f"service_has_active_dependents:{clean}:{','.join(sorted(dependents))}")
            if record.state in {ServiceState.READY, ServiceState.DEGRADED, ServiceState.STARTING}:
                await self._stop_record(clean, record)
            self._records.pop(clean, None)
        await self.publish(Event("runtime.service_detached", {"name": clean}))

    async def status(self) -> dict[str, Health]:
        result: dict[str, Health] = {}
        for name, record in self._records.items():
            if record.state == ServiceState.FAILED:
                result[name] = Health(ServiceState.FAILED, record.detail)
                continue
            try:
                reported = await record.service.health()
            except BaseException as error:
                result[name] = Health(ServiceState.FAILED, f"{type(error).__name__}:{error}")
                continue
            if record.state in {ServiceState.STARTING, ServiceState.STOPPING, ServiceState.STOPPED}:
                result[name] = Health(record.state, record.detail or reported.detail)
            elif record.state == ServiceState.READY and reported.state == ServiceState.DECLARED:
                result[name] = Health(ServiceState.READY, reported.detail)
            else:
                result[name] = reported
        return result

from __future__ import annotations

from typing import Any, Iterable

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState
from ..state.store import StateStore


class MemoryService:
    spec = ServiceSpec("memory.service", required=True, dependencies=("state.store",))

    def __init__(self) -> None:
        self._store: StateStore | None = None
        self._state = ServiceState.DECLARED

    async def start(self, context: RuntimeContext) -> None:
        store = context.get_service("state.store")
        if not isinstance(store, StateStore):
            raise RuntimeError("canonical_state_store_missing")
        self._store = store
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._store = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        return Health(self._state)

    def remember(self, key: str, value: Any) -> None:
        self.remember_many(((key, value),))

    def remember_many(self, rows: Iterable[tuple[str, Any]]) -> None:
        if self._store is None:
            raise RuntimeError("memory_not_ready")
        self._store.put_many(("memory", key, value) for key, value in rows)

    def recall(self, key: str, default: Any = None) -> Any:
        if self._store is None:
            raise RuntimeError("memory_not_ready")
        return self._store.get("memory", key, default)

from __future__ import annotations

import csv
import json
from collections import Counter
from pathlib import Path, PurePosixPath
from typing import Any, Iterable


EVIDENCE_PARTS = {
    ".git", "backups", "backup", "deploy_backups", "snapshots", "snapshot",
    "archive", "archives", "logs", "receipts",
}
REGENERATE_SUFFIXES = {".pyc", ".pyo", ".tmp", ".cache"}
STATE_PARTS = {"memory", "checkpoints", "state", "databases", "database"}
ARTIFACT_PARTS = {
    "inventions", "renders", "models", "assets", "uploads", "documents",
    "worlds", "planets",
}
SENSITIVE_NAME_PARTS = {".env", "credential", "credentials"}


def _json_rows(value: Any) -> Iterable[dict[str, Any]]:
    if isinstance(value, list):
        yield from (row for row in value if isinstance(row, dict))
        return
    if isinstance(value, dict):
        for key in ("entries", "files", "manifest"):
            rows = value.get(key)
            if isinstance(rows, list):
                yield from (row for row in rows if isinstance(row, dict))
                return
        if any(key in value for key in ("path", "absolute_path", "source_path", "relative_path")):
            yield value
            return
    raise ValueError("manifest_json_shape_unsupported")


def records(path: Path) -> Iterable[dict[str, Any]]:
    text = path.read_text(encoding="utf-8", errors="replace")
    if not text.strip():
        return
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        for line_number, line in enumerate(text.splitlines(), 1):
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(
                    f"manifest_jsonl_invalid:{line_number}:{error.msg}"
                ) from error
            if not isinstance(row, dict):
                raise ValueError(f"manifest_row_not_object:{line_number}")
            yield row
        return
    yield from _json_rows(payload)


def source_path(item: dict[str, Any]) -> str:
    for key in ("path", "absolute_path", "source_path", "relative_path"):
        value = item.get(key)
        if value:
            return str(value)
    return ""


def classify(item: dict[str, Any]) -> tuple[str, str]:
    raw = source_path(item)
    if not raw:
        return "unresolved", "missing_path"
    normalized = raw.replace("\\", "/")
    low = normalized.lower()
    path = PurePosixPath(low)
    parts = set(path.parts)
    name = path.name

    if any(marker in low for marker in SENSITIVE_NAME_PARTS):
        return "secret_reference", "sensitive_configuration_reference"
    if "__pycache__" in parts or path.suffix in REGENERATE_SUFFIXES:
        return "regenerate", "derived_or_temporary"
    if parts & EVIDENCE_PARTS or ".bak" in name or ".before_" in name or ".pre_" in name:
        return "retain_evidence", "historical_or_operational_evidence"
    if normalized.startswith(("pi:/", "/boot/", "/etc/", "/usr/", "/var/", "/opt/")):
        return "external_dependency", "raspberry_pi_or_os_owned"
    if parts & ARTIFACT_PARTS:
        return "migrate_artifact", "user_created_artifact"
    if parts & STATE_PARTS:
        return "migrate_state", "durable_runtime_state"
    if "/eira/live/" in low or low.endswith("/eira/live"):
        if item.get("type", "file") in {"file", "regular"}:
            return "migrate_runtime", "active_live_tree"
        return "retain_evidence", "active_tree_non_file_record"
    return "unresolved", "requires_semantic_review"


def build(manifest: Path, output: Path) -> dict[str, Any]:
    output.parent.mkdir(parents=True, exist_ok=True)
    counts: Counter[str] = Counter()
    seen = 0
    with output.open("w", encoding="utf-8", newline="") as handle:
        fields = [
            "entry_id", "source_root", "source_path", "entry_type", "size",
            "sha256", "disposition", "reason",
        ]
        writer = csv.DictWriter(handle, fieldnames=fields)
        writer.writeheader()
        for index, item in enumerate(records(manifest), 1):
            disposition, reason = classify(item)
            counts[disposition] += 1
            seen += 1
            writer.writerow({
                "entry_id": index,
                "source_root": item.get("root") or item.get("source_root") or "",
                "source_path": source_path(item),
                "entry_type": item.get("type") or item.get("kind") or "",
                "size": item.get("size") or item.get("bytes") or 0,
                "sha256": item.get("sha256") or item.get("hash") or "",
                "disposition": disposition,
                "reason": reason,
            })
    summary = {
        "schema": "eira2_migration_ledger_v2",
        "manifest": str(manifest),
        "ledger": str(output),
        "entries": seen,
        "dispositions": dict(sorted(counts.items())),
        "cutover_blocked": counts["unresolved"] > 0,
        "unresolved": counts["unresolved"],
        "content_uploaded": False,
        "secret_values_copied": False,
        "sensitive_values_copied": False,
    }
    output.with_suffix(".summary.json").write_text(
        json.dumps(summary, indent=2, sort_keys=True) + "\n", encoding="utf-8"
    )
    return summary

from __future__ import annotations

import csv
import hashlib
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Iterable, Mapping


MIGRATABLE = {"migrate_state", "migrate_artifact"}


@dataclass(frozen=True, slots=True)
class MigrationItem:
    source: Path
    destination: Path
    disposition: str
    sha256: str
    size: int
    entry_id: str


def _value(row: Mapping[str, object], *keys: str) -> str:
    for key in keys:
        raw = row.get(key)
        if raw is not None and str(raw).strip():
            return str(raw).strip()
    return ""


def safe_destination(staging: Path, source: Path, disposition: str) -> Path:
    anchor = "state" if disposition == "migrate_state" else "artifacts"
    parts = [
        part
        for part in PurePosixPath(str(source).replace("\\", "/")).parts
        if part not in {"/", "", ".", ".."}
    ]
    if not parts:
        raise ValueError("migration_source_path_empty")
    destination = staging / anchor / Path(*parts)
    resolved_root = (staging / anchor).resolve()
    resolved_destination = destination.resolve()
    if resolved_root != resolved_destination and resolved_root not in resolved_destination.parents:
        raise ValueError("migration_destination_escape")
    return destination


def plan(ledger: Path, staging: Path) -> list[MigrationItem]:
    """Build the state/artifact migration plan from the canonical EIRA2 ledger.

    Canonical fields are source_path and entry_type.  path/kind remain accepted
    only for older forensic fixtures so qualification tooling can read historical
    evidence without changing the canonical writer.
    """
    items: list[MigrationItem] = []
    destinations: set[Path] = set()
    with ledger.open("r", encoding="utf-8", errors="replace", newline="") as handle:
        for row in csv.DictReader(handle):
            disposition = _value(row, "disposition").casefold()
            entry_type = _value(row, "entry_type", "kind", "type").casefold()
            if disposition not in MIGRATABLE or entry_type not in {"file", "regular"}:
                continue
            source_text = _value(row, "source_path", "path", "absolute_path")
            if not source_text:
                raise ValueError("migration_source_path_missing")
            source = Path(source_text)
            destination = safe_destination(staging, source, disposition)
            if destination in destinations:
                raise ValueError(f"migration_destination_collision:{destination}")
            destinations.add(destination)
            try:
                size = int(_value(row, "size", "bytes") or 0)
            except ValueError as exc:
                raise ValueError(f"migration_size_invalid:{source}") from exc
            items.append(
                MigrationItem(
                    source=source,
                    destination=destination,
                    disposition=disposition,
                    sha256=_value(row, "sha256", "hash").casefold(),
                    size=size,
                    entry_id=_value(row, "entry_id"),
                )
            )
    return items


def digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def verify_source(item: MigrationItem) -> None:
    stat = item.source.stat()
    if not item.source.is_file() or stat.st_size != item.size:
        raise RuntimeError(f"migration_source_changed:{item.source}")
    if not item.sha256 or digest(item.source) != item.sha256:
        raise RuntimeError(f"migration_hash_mismatch:{item.source}")

from __future__ import annotations

import re
from collections import Counter
from dataclasses import dataclass
from typing import Any, Iterable, Mapping

from ..preservation import load_contract


_SHA256 = re.compile(r"^[0-9a-f]{64}$", re.I)
_ALLOWED_DISPOSITIONS = {
    "external_dependency",
    "migrate_artifact",
    "migrate_runtime",
    "migrate_state",
    "regenerate",
    "retain_evidence",
    "secret_reference",
    "unresolved",
}
_FILE_TYPES = {"file", "regular"}


@dataclass(frozen=True, slots=True)
class MigrationExpectations:
    inventory_entries: int
    active_runtime_files: int
    state_entries: int
    artifact_entries: int

    @classmethod
    def from_preservation_contract(cls, contract: Mapping[str, Any] | None = None) -> "MigrationExpectations":
        value = dict(contract or load_contract())
        catalogs = {
            str(row.get("id")): row
            for row in value.get("dynamic_catalogs") or []
            if isinstance(row, dict)
        }

        def expected(catalog_id: str) -> int:
            row = catalogs.get(catalog_id) or {}
            return int(row.get("expected_count") or 0)

        return cls(
            inventory_entries=int(value.get("inventory_entries") or 0),
            active_runtime_files=expected("catalog.active_runtime_files"),
            state_entries=expected("catalog.state_files"),
            artifact_entries=expected("catalog.user_artifacts"),
        )

    def as_dict(self) -> dict[str, int]:
        return {
            "inventory_entries": self.inventory_entries,
            "active_runtime_files": self.active_runtime_files,
            "state_entries": self.state_entries,
            "artifact_entries": self.artifact_entries,
        }


def _value(row: Mapping[str, Any], *keys: str) -> str:
    for key in keys:
        raw = row.get(key)
        if raw is not None and str(raw).strip():
            return str(raw).strip()
    return ""


def _path(row: Mapping[str, Any]) -> str:
    return _value(row, "source_path", "path", "absolute_path", "relative_path")


def _type(row: Mapping[str, Any]) -> str:
    return _value(row, "entry_type", "type", "kind").casefold()


def _sha(row: Mapping[str, Any]) -> str:
    return _value(row, "sha256", "hash").casefold()


def _disposition(row: Mapping[str, Any]) -> str:
    return _value(row, "disposition").casefold()


def _size_ok(row: Mapping[str, Any]) -> bool:
    raw = row.get("size", row.get("bytes", 0))
    try:
        return int(raw or 0) >= 0
    except (TypeError, ValueError):
        return False


def grade_migration_inventory(
    rows: Iterable[Mapping[str, Any]],
    *,
    expectations: MigrationExpectations | None = None,
) -> dict[str, object]:
    expected = expectations or MigrationExpectations.from_preservation_contract()
    materialized = list(rows)
    path_counts: Counter[str] = Counter()
    id_counts: Counter[str] = Counter()
    dispositions: Counter[str] = Counter()
    invalid_rows: list[dict[str, object]] = []
    valid_file_hashes = 0
    regular_files = 0

    for index, row in enumerate(materialized, 1):
        violations: list[str] = []
        path = _path(row)
        entry_type = _type(row)
        sha = _sha(row)
        disposition = _disposition(row)
        entry_id = _value(row, "entry_id")

        if not path:
            violations.append("source_path_missing")
        else:
            path_counts[path] += 1
        if entry_id:
            id_counts[entry_id] += 1
        else:
            violations.append("entry_id_missing")
        if disposition not in _ALLOWED_DISPOSITIONS:
            violations.append("invalid_disposition:" + (disposition or "missing"))
        else:
            dispositions[disposition] += 1
        if disposition == "unresolved":
            violations.append("unresolved_disposition")
        if not _size_ok(row):
            violations.append("invalid_size")

        if entry_type in _FILE_TYPES:
            regular_files += 1
            if not _SHA256.fullmatch(sha):
                violations.append("regular_file_sha256_missing_or_invalid")
            else:
                valid_file_hashes += 1

        if violations:
            invalid_rows.append(
                {
                    "row": index,
                    "entry_id": entry_id,
                    "source_path": path,
                    "violations": violations,
                }
            )

    duplicate_paths = sorted(path for path, count in path_counts.items() if count > 1)
    duplicate_ids = sorted(entry_id for entry_id, count in id_counts.items() if count > 1)
    runtime_files = sum(
        1
        for row in materialized
        if _disposition(row) == "migrate_runtime" and _type(row) in _FILE_TYPES
    )
    state_entries = sum(1 for row in materialized if _disposition(row) == "migrate_state")
    artifact_entries = sum(1 for row in materialized if _disposition(row) == "migrate_artifact")

    count_failures: list[str] = []
    if len(materialized) != expected.inventory_entries:
        count_failures.append(f"inventory_entries:{len(materialized)}:{expected.inventory_entries}")
    if runtime_files != expected.active_runtime_files:
        count_failures.append(f"active_runtime_files:{runtime_files}:{expected.active_runtime_files}")
    if state_entries != expected.state_entries:
        count_failures.append(f"state_entries:{state_entries}:{expected.state_entries}")
    if artifact_entries != expected.artifact_entries:
        count_failures.append(f"artifact_entries:{artifact_entries}:{expected.artifact_entries}")

    ok = (
        not invalid_rows
        and not duplicate_paths
        and not duplicate_ids
        and not count_failures
        and dispositions.get("unresolved", 0) == 0
        and regular_files == valid_file_hashes
    )
    return {
        "schema": "eira2_migration_inventory_grade_v1",
        "ok": ok,
        "inventory_76056_complete": ok,
        "expected": expected.as_dict(),
        "observed": {
            "inventory_entries": len(materialized),
            "active_runtime_files": runtime_files,
            "state_entries": state_entries,
            "artifact_entries": artifact_entries,
            "regular_files": regular_files,
            "regular_files_with_valid_sha256": valid_file_hashes,
        },
        "dispositions": dict(sorted(dispositions.items())),
        "count_failures": count_failures,
        "duplicate_source_paths": duplicate_paths[:100],
        "duplicate_entry_ids": duplicate_ids[:100],
        "invalid_row_count": len(invalid_rows),
        "invalid_row_samples": invalid_rows[:100],
        "rules": {
            "every_inventory_entry_present_exactly_once": True,
            "every_regular_file_has_sha256": True,
            "unresolved_dispositions_allowed": 0,
            "active_runtime_file_count_exact": expected.active_runtime_files,
            "state_entry_count_exact": expected.state_entries,
            "artifact_entry_count_exact": expected.artifact_entries,
        },
    }


def grade_migration_rehearsal(
    ledger_rows: Iterable[Mapping[str, Any]],
    receipt_rows: Iterable[Mapping[str, Any]],
) -> dict[str, object]:
    ledger = list(ledger_rows)
    required = {
        _path(row): row
        for row in ledger
        if _disposition(row) in {"migrate_state", "migrate_artifact"} and _path(row)
    }
    supplied: dict[str, Mapping[str, Any]] = {}
    duplicate_paths: list[str] = []
    unexpected_paths: list[str] = []

    for raw in receipt_rows:
        path = _path(raw)
        if not path:
            continue
        if path not in required:
            unexpected_paths.append(path)
            continue
        if path in supplied:
            duplicate_paths.append(path)
            continue
        supplied[path] = raw

    missing_paths = sorted(set(required) - set(supplied))
    results: list[dict[str, object]] = []
    for path in sorted(set(required) & set(supplied)):
        source = required[path]
        receipt = supplied[path]
        disposition = _disposition(source)
        expected_sha = _sha(source)
        receipt_source_sha = _value(receipt, "source_sha256").casefold()
        staged_sha = _value(receipt, "staged_sha256", "destination_sha256").casefold()
        destination = _value(receipt, "destination_path", "staged_path")
        violations: list[str] = []

        if not _SHA256.fullmatch(expected_sha):
            violations.append("ledger_source_sha256_invalid")
        if receipt_source_sha != expected_sha:
            violations.append("receipt_source_sha256_mismatch")
        if staged_sha != expected_sha:
            violations.append("staged_sha256_mismatch")
        if receipt.get("verified") is not True:
            violations.append("staged_hash_not_verified")
        if receipt.get("source_unchanged") is not True:
            violations.append("source_unchanged_not_verified")
        if not destination:
            violations.append("destination_path_missing")
        if disposition == "migrate_artifact" and receipt.get("executable_by_default") is not False:
            violations.append("artifact_executable_by_default_not_proven_false")

        results.append(
            {
                "source_path": path,
                "disposition": disposition,
                "destination_path": destination,
                "ok": not violations,
                "violations": violations,
            }
        )

    failures = [row for row in results if not row["ok"]]
    ok = (
        not missing_paths
        and not duplicate_paths
        and not unexpected_paths
        and not failures
        and len(results) == len(required)
    )
    return {
        "schema": "eira2_migration_rehearsal_grade_v1",
        "ok": ok,
        "rehearsal_hash_preservation_complete": ok,
        "required_staged_entries": len(required),
        "verified_staged_entries": sum(1 for row in results if row["ok"]),
        "missing_source_paths": missing_paths[:200],
        "duplicate_source_paths": sorted(set(duplicate_paths))[:200],
        "unexpected_source_paths": sorted(set(unexpected_paths))[:200],
        "failure_count": len(failures),
        "failure_samples": failures[:100],
        "rules": {
            "state_and_artifacts_staged_before_cutover": True,
            "source_and_staged_sha256_must_match": True,
            "source_must_remain_unchanged": True,
            "user_artifacts_non_executable_by_default": True,
        },
    }


def grade_full_migration_qualification(
    ledger_rows: Iterable[Mapping[str, Any]],
    receipt_rows: Iterable[Mapping[str, Any]],
    *,
    expectations: MigrationExpectations | None = None,
) -> dict[str, object]:
    ledger = list(ledger_rows)
    inventory = grade_migration_inventory(ledger, expectations=expectations)
    rehearsal = grade_migration_rehearsal(ledger, receipt_rows)
    ok = bool(inventory["ok"] and rehearsal["ok"])
    return {
        "schema": "eira2_full_migration_qualification_v1",
        "ok": ok,
        "migration_cutover_evidence_complete": ok,
        "inventory": inventory,
        "rehearsal": rehearsal,
    }

from __future__ import annotations

import re
from typing import Any, Iterable, Mapping


_SHA256 = re.compile(r"^[0-9a-f]{64}$", re.I)
_FILE_TYPES = {"file", "regular"}
_ALLOWED = {"native_behavior", "duplicate_retirement", "evidence_only_retention"}
EXPECTED_ACTIVE_RUNTIME_FILES = 12262


def _value(row: Mapping[str, Any], *keys: str) -> str:
    for key in keys:
        value = row.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return ""


def _path(row: Mapping[str, Any]) -> str:
    return _value(row, "source_path", "path", "absolute_path", "relative_path")


def _sha(row: Mapping[str, Any]) -> str:
    return _value(row, "sha256", "hash").casefold()


def _type(row: Mapping[str, Any]) -> str:
    return _value(row, "entry_type", "type", "kind").casefold()


def _runtime_sources(
    ledger_rows: Iterable[Mapping[str, Any]],
    *,
    expected_count: int,
) -> tuple[dict[str, Mapping[str, Any]], list[str]]:
    sources: dict[str, Mapping[str, Any]] = {}
    errors: list[str] = []
    for row in ledger_rows:
        if _value(row, "disposition").casefold() != "migrate_runtime":
            continue
        if _type(row) not in _FILE_TYPES:
            continue
        path = _path(row)
        if not path:
            errors.append("runtime_source_path_missing")
            continue
        if path in sources:
            errors.append("duplicate_runtime_source_path:" + path)
            continue
        if not _SHA256.fullmatch(_sha(row)):
            errors.append("runtime_source_sha256_missing_or_invalid:" + path)
        sources[path] = row
    if len(sources) != expected_count:
        errors.append(f"runtime_source_count_mismatch:{len(sources)}:{expected_count}")
    return sources, errors


def build_runtime_file_disposition_manifest(
    ledger_rows: Iterable[Mapping[str, Any]],
    *,
    expected_count: int = EXPECTED_ACTIVE_RUNTIME_FILES,
) -> dict[str, object]:
    sources, errors = _runtime_sources(ledger_rows, expected_count=expected_count)
    rows = [
        {
            "source_path": path,
            "source_sha256": _sha(source),
            "disposition": "pending",
            "native_eira2_targets": [],
            "parity_verified": False,
            "parity_receipts": [],
            "duplicate_of": None,
            "disposition_reason": "",
            "disposition_evidence": [],
            "runtime_delegation_to_eira1": None,
            "legacy_source_executable_after_cutover": None,
        }
        for path, source in sorted(sources.items())
    ]
    return {
        "schema": "eira2_runtime_file_disposition_manifest_v1",
        "expected_active_runtime_files": expected_count,
        "observed_active_runtime_files": len(sources),
        "source_inventory_errors": errors,
        "qualification_complete": False,
        "rows": rows,
        "rules": {
            "allowed_dispositions": sorted(_ALLOWED),
            "runtime_delegation_to_eira1_must_be_false": True,
            "legacy_runtime_source_executable_after_cutover_must_be_false": True,
            "native_behavior_requires_parity_receipt": True,
        },
    }


def _strings(value: object) -> tuple[str, ...]:
    if not isinstance(value, (list, tuple)):
        return ()
    return tuple(str(item).strip() for item in value if str(item).strip())


def grade_runtime_file_dispositions(
    ledger_rows: Iterable[Mapping[str, Any]],
    receipt_rows: Iterable[Mapping[str, Any]],
    *,
    expected_count: int = EXPECTED_ACTIVE_RUNTIME_FILES,
) -> dict[str, object]:
    sources, source_errors = _runtime_sources(ledger_rows, expected_count=expected_count)
    supplied: dict[str, Mapping[str, Any]] = {}
    duplicates: list[str] = []
    unexpected: list[str] = []

    for row in receipt_rows:
        path = _path(row)
        if not path:
            continue
        if path not in sources:
            unexpected.append(path)
            continue
        if path in supplied:
            duplicates.append(path)
            continue
        supplied[path] = row

    missing = sorted(set(sources) - set(supplied))
    results: list[dict[str, object]] = []
    for path in sorted(set(sources) & set(supplied)):
        source = sources[path]
        receipt = supplied[path]
        disposition = _value(receipt, "disposition").casefold()
        violations: list[str] = []
        source_sha = _sha(source)
        receipt_sha = _value(receipt, "source_sha256").casefold()

        if disposition not in _ALLOWED:
            violations.append("invalid_runtime_file_disposition:" + (disposition or "missing"))
        if receipt_sha != source_sha:
            violations.append("source_sha256_binding_mismatch")
        if receipt.get("runtime_delegation_to_eira1") is not False:
            violations.append("runtime_delegation_to_eira1_not_proven_false")
        if receipt.get("legacy_source_executable_after_cutover") is not False:
            violations.append("legacy_source_execution_not_proven_disabled")

        targets = _strings(receipt.get("native_eira2_targets"))
        parity_receipts = _strings(receipt.get("parity_receipts"))
        evidence = _strings(receipt.get("disposition_evidence"))
        reason = _value(receipt, "disposition_reason")
        duplicate_of = _value(receipt, "duplicate_of")

        if disposition == "native_behavior":
            if not targets:
                violations.append("native_eira2_targets_missing")
            if receipt.get("parity_verified") is not True:
                violations.append("native_behavior_parity_not_verified")
            if not parity_receipts:
                violations.append("native_behavior_parity_receipts_missing")
        elif disposition == "duplicate_retirement":
            if not duplicate_of:
                violations.append("duplicate_retirement_target_missing")
            elif duplicate_of == path:
                violations.append("duplicate_retirement_self_reference")
            if not reason:
                violations.append("duplicate_retirement_reason_missing")
            if not evidence:
                violations.append("duplicate_retirement_evidence_missing")
        elif disposition == "evidence_only_retention":
            if not reason:
                violations.append("evidence_only_reason_missing")
            if not evidence:
                violations.append("evidence_only_retention_evidence_missing")

        results.append(
            {
                "source_path": path,
                "disposition": disposition,
                "ok": not violations,
                "violations": violations,
                "native_eira2_targets": list(targets),
            }
        )

    failures = [row for row in results if not row["ok"]]
    passed = sum(1 for row in results if row["ok"])
    ok = (
        not source_errors
        and not missing
        and not duplicates
        and not unexpected
        and not failures
        and len(sources) == expected_count
        and passed == expected_count
    )
    return {
        "schema": "eira2_runtime_file_parity_grade_v1",
        "ok": ok,
        "catalog_active_runtime_files_complete": ok,
        "expected_active_runtime_files": expected_count,
        "source_runtime_files": len(sources),
        "passed_runtime_files": passed,
        "coverage_percent": round((100.0 * passed / expected_count), 3) if expected_count else 0.0,
        "source_inventory_errors": source_errors[:100],
        "missing_source_paths": missing[:200],
        "duplicate_receipt_paths": sorted(set(duplicates))[:200],
        "unexpected_receipt_paths": sorted(set(unexpected))[:200],
        "failure_count": len(failures),
        "failure_samples": failures[:100],
        "rules": {
            "every_active_runtime_file_dispositioned": True,
            "legacy_runtime_execution_after_cutover_allowed": False,
            "runtime_delegation_to_eira1_allowed": False,
            "native_behavior_requires_target_and_parity_receipt": True,
        },
    }

from __future__ import annotations

import ast
import csv
import hashlib
import json
import os
from collections import Counter, defaultdict
from dataclasses import dataclass
from pathlib import Path, PurePosixPath
from typing import Any, Iterable, Iterator


_INVENTORY_ENV = "EIRA2_NEURAL_INVENTORY"
_EXCLUDED_SCAN_PARTS = {".git", "__pycache__", ".pytest_cache"}
_CODE_SUFFIXES = {".py", ".js", ".ts", ".tsx", ".jsx", ".html", ".css", ".json", ".yaml", ".yml", ".toml", ".sh"}
_CONDUCTIVE_KINDS = {"python_import", "declared_runtime_dependency", "runtime_call"}


def _normalize(value: Any) -> str:
    return str(value or "").replace("\\", "/").strip()


def stable_neuron_id(path: str) -> str:
    """Stable opaque neuron id; paths remain metadata, not identifiers."""
    clean = _normalize(path)
    digest = hashlib.blake2b(clean.encode("utf-8", errors="replace"), digest_size=12).hexdigest()
    return f"neuron:{digest}"


def _logical_path(raw: str, root: Path) -> str:
    value = _normalize(raw)
    if not value:
        return ""
    root_text = _normalize(root.resolve())
    if value == root_text:
        return "."
    if value.startswith(root_text.rstrip("/") + "/"):
        return value[len(root_text.rstrip("/")) + 1 :]
    marker = "/EIRA/LIVE/"
    pos = value.casefold().find(marker.casefold())
    if pos >= 0:
        return value[pos + len(marker) :]
    if value.startswith("pi:/"):
        return "external/pi/" + value[3:].lstrip("/")
    if value.startswith("/"):
        return "external/fs/" + value.lstrip("/")
    return value.lstrip("./")


def _entry_path(row: dict[str, Any]) -> str:
    for key in ("source_path", "path", "absolute_path", "relative_path"):
        if row.get(key):
            return _normalize(row[key])
    return ""


def _entry_kind(row: dict[str, Any]) -> str:
    raw = str(row.get("entry_type") or row.get("type") or row.get("kind") or "file").casefold()
    return "directory" if raw in {"dir", "directory", "folder"} else "file"


def _disposition(row: dict[str, Any]) -> str:
    return str(row.get("disposition") or row.get("classification") or "unclassified")


def _iter_json_payload(value: Any) -> Iterator[dict[str, Any]]:
    if isinstance(value, list):
        for row in value:
            if isinstance(row, dict):
                yield row
        return
    if isinstance(value, dict):
        for key in ("entries", "files", "manifest", "inventory"):
            rows = value.get(key)
            if isinstance(rows, list):
                for row in rows:
                    if isinstance(row, dict):
                        yield row
                return
        if _entry_path(value):
            yield value
            return
    raise ValueError("neural_inventory_json_shape_unsupported")


def inventory_rows(path: Path) -> Iterator[dict[str, Any]]:
    suffix = path.suffix.casefold()
    if suffix == ".csv":
        with path.open("r", encoding="utf-8", errors="replace", newline="") as handle:
            yield from csv.DictReader(handle)
        return
    text = path.read_text(encoding="utf-8", errors="replace")
    if not text.strip():
        return
    try:
        payload = json.loads(text)
    except json.JSONDecodeError:
        for number, line in enumerate(text.splitlines(), 1):
            if not line.strip():
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError as error:
                raise ValueError(f"neural_inventory_jsonl_invalid:{number}:{error.msg}") from error
            if not isinstance(row, dict):
                raise ValueError(f"neural_inventory_row_not_object:{number}")
            yield row
        return
    yield from _iter_json_payload(payload)


def inventory_candidates(root: Path) -> tuple[Path, ...]:
    env = os.getenv(_INVENTORY_ENV, "").strip()
    values = []
    if env:
        values.append(Path(env).expanduser())
    values.extend(
        [
            root / "migration_ledger.csv",
            root / "eira2" / "migration_ledger.csv",
            root / "var" / "migration_ledger.csv",
            root / "eira2" / "var" / "migration_ledger.csv",
            root / "eira2_organization.json",
            root / "eira2" / "eira2_organization.json",
            root / "var" / "eira2_organization.json",
        ]
    )
    out: list[Path] = []
    for value in values:
        resolved = value.resolve() if value.is_absolute() else (root / value).resolve()
        if resolved not in out:
            out.append(resolved)
    return tuple(out)


def _filesystem_rows(root: Path) -> Iterator[dict[str, Any]]:
    for path in root.rglob("*"):
        try:
            rel = path.relative_to(root)
        except ValueError:
            continue
        if any(part in _EXCLUDED_SCAN_PARTS for part in rel.parts):
            continue
        try:
            is_dir = path.is_dir()
            size = 0 if is_dir else path.stat().st_size
        except OSError:
            continue
        yield {
            "path": str(path),
            "type": "directory" if is_dir else "file",
            "size": size,
            "disposition": "runtime_scan_fallback",
        }


def _cluster_for(logical: str) -> str:
    parts = PurePosixPath(logical).parts
    if len(parts) >= 2 and parts[0] == "extensions":
        return f"extension:{parts[1]}"
    if len(parts) >= 3 and parts[:2] == ("eira2", "eira2"):
        return f"eira2:{parts[2]}"
    if parts:
        return f"root:{parts[0]}"
    return "root:."


def _anatomy_for(cluster: str) -> tuple[str, bool]:
    low = cluster.casefold()
    spine = any(token in low for token in ("conversation", "kernel", "state", "memory", "delivery", "evidence"))
    if spine:
        return "midline", True
    bit = int(hashlib.blake2b(cluster.encode(), digest_size=1).hexdigest(), 16) & 1
    return ("left" if bit == 0 else "right"), False


def _activity_class(disposition: str, logical: str) -> str:
    low = disposition.casefold()
    if low == "migrate_runtime" or logical.startswith(("eira2/", "extensions/")):
        return "runtime"
    if low == "migrate_state":
        return "state"
    if low == "migrate_artifact":
        return "artifact"
    if low in {"retain_evidence", "regenerate", "external_dependency", "secret_reference"}:
        return low
    return "other"


@dataclass(frozen=True, slots=True)
class Neuron:
    id: str
    path: str
    logical_path: str
    kind: str
    cluster: str
    hemisphere: str
    spine: bool
    disposition: str
    activity_class: str
    size: int
    suffix: str
    conductive_capable: bool
    synthetic: bool = False

    def as_dict(self, *, include_path: bool = True) -> dict[str, Any]:
        row = {
            "id": self.id,
            "logical_path": self.logical_path,
            "kind": self.kind,
            "cluster": self.cluster,
            "hemisphere": self.hemisphere,
            "spine": self.spine,
            "disposition": self.disposition,
            "activity_class": self.activity_class,
            "size": self.size,
            "suffix": self.suffix,
            "conductive_capable": self.conductive_capable,
            "synthetic": self.synthetic,
        }
        if include_path:
            row["path"] = self.path
        return row


