from __future__ import annotations

import argparse
import ast
import json
import shutil
import sqlite3
import subprocess
import sys
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path
from typing import Any, Iterable

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState
from ..registry.graph import NodeRegistryService
from ..registry.manifests import Manifest, discover


_EXCLUDED_PARTS = {".git", "__pycache__", ".pytest_cache", "var", "eira_probe"}


@dataclass(slots=True)
class DoctorReport:
    ok: bool
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    checks: dict[str, int | str | bool] = field(default_factory=dict)
    started_at_unix: float = 0.0
    finished_at_unix: float = 0.0

    def as_dict(self) -> dict[str, Any]:
        return asdict(self)


def _iter_files(root: Path, suffix: str) -> Iterable[Path]:
    for path in root.rglob(f"*{suffix}"):
        try:
            rel = path.relative_to(root)
        except ValueError:
            continue
        if any(part in _EXCLUDED_PARTS for part in rel.parts):
            continue
        if path.is_file():
            yield path


def _module_file(project_root: Path, module: str) -> Path | None:
    parts = module.split(".")
    direct = project_root.joinpath(*parts).with_suffix(".py")
    package = project_root.joinpath(*parts) / "__init__.py"
    if direct.is_file():
        return direct
    if package.is_file():
        return package
    return None


def _declared_symbols(path: Path) -> set[str]:
    tree = ast.parse(path.read_text(encoding="utf-8", errors="strict"), filename=str(path))
    return {
        node.name
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
    }


def _validate_manifest_graph(manifests: list[Manifest]) -> list[str]:
    errors: list[str] = []
    by_name = {manifest.name: manifest for manifest in manifests}
    for manifest in manifests:
        for dependency in manifest.dependencies:
            if dependency == manifest.name:
                errors.append(f"manifest_self_dependency:{manifest.name}")
            elif dependency not in by_name:
                errors.append(f"manifest_dependency_missing:{manifest.name}:{dependency}")

    visiting: set[str] = set()
    visited: set[str] = set()

    def visit(name: str) -> None:
        if name in visited:
            return
        if name in visiting:
            errors.append(f"manifest_dependency_cycle:{name}")
            return
        visiting.add(name)
        manifest = by_name.get(name)
        if manifest is not None:
            for dependency in manifest.dependencies:
                if dependency in by_name:
                    visit(dependency)
        visiting.remove(name)
        visited.add(name)

    for name in sorted(by_name):
        visit(name)
    return errors


def audit_project(
    project_root: Path,
    *,
    state_path: Path | None = None,
    registry_snapshot: dict[str, Any] | None = None,
    neural_overview: dict[str, Any] | None = None,
    neural_fibers: Iterable[dict[str, Any]] | None = None,
    run_external_checks: bool = False,
) -> DoctorReport:
    root = project_root.expanduser().resolve()
    report = DoctorReport(ok=False, started_at_unix=time.time())
    errors = report.errors
    warnings = report.warnings

    if not (root / "pyproject.toml").is_file():
        errors.append("project_pyproject_missing")

    python_files = sorted(_iter_files(root, ".py"))
    compiled = 0
    for path in python_files:
        try:
            source = path.read_text(encoding="utf-8", errors="strict")
            compile(source, str(path), "exec", dont_inherit=True)
            ast.parse(source, filename=str(path))
            compiled += 1
        except (OSError, UnicodeError, SyntaxError) as error:
            errors.append(f"python_syntax:{path.relative_to(root)}:{type(error).__name__}:{error}")
    report.checks["python_files"] = len(python_files)
    report.checks["python_compiled"] = compiled

    json_files = sorted(_iter_files(root, ".json"))
    parsed_json = 0
    for path in json_files:
        try:
            json.loads(path.read_text(encoding="utf-8", errors="strict"))
            parsed_json += 1
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            errors.append(f"json_invalid:{path.relative_to(root)}:{type(error).__name__}:{error}")
    report.checks["json_files"] = len(json_files)
    report.checks["json_parsed"] = parsed_json

    manifest_dir = root / "manifests"
    manifests: list[Manifest] = []
    if not manifest_dir.is_dir():
        errors.append("manifest_directory_missing")
    else:
        try:
            manifests = discover(manifest_dir)
        except Exception as error:
            errors.append(f"manifest_discovery_failed:{type(error).__name__}:{error}")
        else:
            errors.extend(_validate_manifest_graph(manifests))
            for manifest in manifests:
                module_path = _module_file(root, manifest.module)
                if module_path is None:
                    errors.append(f"manifest_module_missing:{manifest.name}:{manifest.module}")
                    continue
                try:
                    symbols = _declared_symbols(module_path)
                except Exception as error:
                    errors.append(f"manifest_module_unreadable:{manifest.name}:{type(error).__name__}:{error}")
                    continue
                if manifest.factory not in symbols:
                    errors.append(f"manifest_factory_missing:{manifest.name}:{manifest.module}:{manifest.factory}")
    report.checks["manifests"] = len(manifests)

    preservation = root / "preservation_contract.json"
    if not preservation.is_file():
        errors.append("preservation_contract_missing")
    else:
        try:
            contract = json.loads(preservation.read_text(encoding="utf-8"))
            if contract.get("schema") != "eira2_functional_preservation_contract_v1":
                errors.append("preservation_contract_schema_invalid")
            if int(contract.get("inventory_entries") or 0) != 76056:
                errors.append("preservation_inventory_baseline_invalid")
        except Exception as error:
            errors.append(f"preservation_contract_invalid:{type(error).__name__}:{error}")

    if state_path is not None:
        state = state_path.expanduser().resolve()
        if state.exists():
            try:
                db = sqlite3.connect(f"file:{state}?mode=ro", uri=True, timeout=3.0)
                try:
                    integrity = db.execute("PRAGMA integrity_check").fetchone()
                    if not integrity or str(integrity[0]).casefold() != "ok":
                        errors.append(f"sqlite_integrity_failed:{integrity}")
                    foreign = db.execute("PRAGMA foreign_key_check").fetchall()
                    if foreign:
                        errors.append(f"sqlite_foreign_key_failures:{len(foreign)}")
                    versions = db.execute("SELECT version FROM schema_version ORDER BY version").fetchall()
                    if not versions:
                        errors.append("sqlite_schema_version_missing")
                    report.checks["sqlite_schema_version"] = int(versions[-1][0]) if versions else 0
                finally:
                    db.close()
            except (sqlite3.Error, OSError) as error:
                errors.append(f"sqlite_check_failed:{type(error).__name__}:{error}")
        else:
            warnings.append("sqlite_state_not_created_yet")

    if registry_snapshot is not None:
        nodes = {str(row.get("name")) for row in registry_snapshot.get("nodes", []) if isinstance(row, dict)}
        bridges = [row for row in registry_snapshot.get("bridges", []) if isinstance(row, dict)]
        for bridge in bridges:
            source = str(bridge.get("source") or "")
            target = str(bridge.get("target") or "")
            if source not in nodes or target not in nodes:
                errors.append(f"registry_orphan_bridge:{source}:{target}")
            if bridge.get("kind") == "anatomical_membership" and bridge.get("conductive") is True:
                errors.append(f"registry_false_conductivity:{source}:{target}")
        report.checks["registry_nodes"] = len(nodes)
        report.checks["registry_bridges"] = len(bridges)

    if neural_overview is not None:
        if neural_overview.get("all_inventory_entries_have_neurons") is not True:
            errors.append("neural_inventory_coverage_false")
        if neural_overview.get("structural_fibers_are_conductive") is not False:
            errors.append("neural_structural_fiber_truth_violation")
        if neural_overview.get("conductive_fibers_require_evidence") is not True:
            errors.append("neural_conductive_evidence_rule_missing")
        count = int(neural_overview.get("inventory_neuron_count") or 0)
        source = str(neural_overview.get("inventory_source") or "")
        authoritative = bool(source and source != "filesystem_scan_fallback")
        # A filesystem fallback is a legitimate development/shadow visualization, not
        # a claim that the canonical 76,056-entry forensic inventory is loaded. Active
        # runtime enforces authoritative inventory separately before cutover authority.
        if authoritative and count < 76056:
            errors.append(f"neural_inventory_below_canonical_baseline:{count}")
        report.checks["neural_inventory_neurons"] = count
        report.checks["neural_inventory_source"] = source
        report.checks["neural_inventory_authoritative"] = authoritative

    if neural_fibers is not None:
        fiber_count = 0
        conductive = 0
        for fiber in neural_fibers:
            fiber_count += 1
            if fiber.get("conductive"):
                conductive += 1
                if not str(fiber.get("evidence") or "").strip():
                    errors.append("neural_conductive_fiber_without_evidence")
                if fiber.get("kind") == "anatomical_membership":
                    errors.append("neural_membership_fiber_conductive")
        report.checks["neural_fibers_checked"] = fiber_count
        report.checks["neural_conductive_fibers_checked"] = conductive

    if run_external_checks:
        node = shutil.which("node")
        js = root / "eira2" / "neural" / "web" / "app.js"
        if js.is_file():
            if node:
                completed = subprocess.run(
                    [node, "--check", str(js)],
                    cwd=root,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    timeout=30,
                    check=False,
                )
                if completed.returncode != 0:
                    errors.append("javascript_syntax_failed:" + completed.stdout[-1200:].replace("\n", " | "))
                report.checks["javascript_syntax"] = completed.returncode == 0
            else:
                warnings.append("node_not_available_for_javascript_syntax")
                report.checks["javascript_syntax"] = "not_available"

    report.finished_at_unix = time.time()
    report.ok = not errors
    report.checks["errors"] = len(errors)
    report.checks["warnings"] = len(warnings)
    return report


class DoctorService:
    spec = ServiceSpec(
        "operations.doctor",
        required=True,
        dependencies=("operations.health", "registry.graph"),
        start_timeout_seconds=90.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(self, project_root: Path, state_path: Path) -> None:
        self.project_root = project_root.expanduser().resolve()
        self.state_path = state_path.expanduser().resolve()
        self._state = ServiceState.DECLARED
        self._last: DoctorReport | None = None
        self._context: RuntimeContext | None = None

    async def start(self, context: RuntimeContext) -> None:
        self._context = context
        report = self.evaluate()
        self._last = report
        if not report.ok:
            self._state = ServiceState.FAILED
            raise RuntimeError("doctor_startup_failed:" + ";".join(report.errors[:8]))
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._context = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        detail = "not_run"
        if self._last is not None:
            detail = f"ok={self._last.ok} errors={len(self._last.errors)} warnings={len(self._last.warnings)}"
        return Health(self._state, detail)

    def evaluate(self, *, project_root: Path | None = None, state_path: Path | None = None) -> DoctorReport:
        registry_snapshot = None
        neural_overview = None
        neural_fibers = None
        if self._context is not None:
            try:
                registry = self._context.get_service("registry.graph")
                if isinstance(registry, NodeRegistryService):
                    registry_snapshot = registry.snapshot()
            except Exception:
                registry_snapshot = None
            try:
                neural = self._context.get_service("interfaces.neural_ui")
                surface = getattr(neural, "surface", None)
                atlas = getattr(surface, "atlas", None)
                if atlas is not None:
                    neural_overview = atlas.overview()
                    neural_fibers = [row.as_dict() for row in atlas.fibers]
            except Exception:
                neural_overview = None
                neural_fibers = None
        report = audit_project(
            project_root or self.project_root,
            state_path=state_path if state_path is not None else self.state_path,
            registry_snapshot=registry_snapshot,
            neural_overview=neural_overview,
            neural_fibers=neural_fibers,
            run_external_checks=False,
        )
        self._last = report
        return report

    def last_report(self) -> dict[str, Any]:
        return self._last.as_dict() if self._last is not None else {"ok": False, "error": "doctor_not_run"}


def main() -> int:
    parser = argparse.ArgumentParser(description="EIRA 2.0 structural Doctor")
    parser.add_argument("--project-root", type=Path, default=Path.cwd())
    parser.add_argument("--state", type=Path, default=None)
    parser.add_argument("--no-state", action="store_true")
    parser.add_argument("--external", action="store_true")
    parser.add_argument("--strict", action="store_true")
    args = parser.parse_args()
    state = None if args.no_state else args.state
    report = audit_project(
        args.project_root,
        state_path=state,
        run_external_checks=args.external,
    )
    print(json.dumps(report.as_dict(), indent=2, sort_keys=True))
    if not report.ok:
        return 1
    if args.strict and report.warnings:
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import re
from typing import Any, Mapping

from .replacement_boundary import grade_eira1_replacement_boundary


_SHA40 = re.compile(r"^[0-9a-f]{40}$", re.I)
_SHA256 = re.compile(r"^[0-9a-f]{64}$", re.I)

_GATE_SPECS: dict[str, tuple[str, str]] = {
    "package_identity": ("eira2_package_identity_v1", "ok"),
    "native_only_runtime": (
        "eira2_native_only_runtime_grade_v1",
        "eira2_native_only_runtime_complete",
    ),
    "private_models": (
        "eira2_private_model_containment_v1",
        "private_model_containment_complete",
    ),
    "functional_preservation": (
        "eira2_functional_capability_qualification_grade_v1",
        "functional_capability_preservation_complete",
    ),
    "extension_parity": ("eira2_extension_disposition_grade_v1", "ok"),
    "legacy_behavior_parity": (
        "eira2_legacy_behavior_disposition_grade_v1",
        "legacy_behavior_parity_complete",
    ),
    "migration_76056": (
        "eira2_full_migration_qualification_v1",
        "migration_cutover_evidence_complete",
    ),
    "runtime_file_parity": (
        "eira2_runtime_file_parity_grade_v1",
        "catalog_active_runtime_files_complete",
    ),
    "semantic_language": (
        "eira2_semantic_language_receipt_grade_v1",
        "semantic_quality_final",
    ),
    "multilingual_voice": (
        "eira2_multilingual_voice_hardware_grade_v1",
        "hardware_spoken_language_parity_final",
    ),
    "pi_hardware": ("eira2_pi_hardware_qualification_v2", "pi_runtime_verified"),
    "isolated_300": ("eira2_isolated_conversation_qualification_v2", "ok"),
    "persistent_fuzz": ("eira2_persistent_randomized_conversation_fuzz_v1", "ok"),
}


def _object(row: Mapping[str, Any], key: str) -> Mapping[str, Any]:
    value = row.get(key)
    return value if isinstance(value, Mapping) else {}


def _gate_result(name: str, value: object) -> dict[str, object]:
    expected_schema, final_field = _GATE_SPECS[name]
    row = value if isinstance(value, Mapping) else {}
    violations: list[str] = []
    schema = str(row.get("schema") or "")
    if schema != expected_schema:
        violations.append(f"schema_mismatch:{schema or 'missing'}:{expected_schema}")
    if row.get("ok") is not True:
        violations.append("gate_ok_not_true")
    if row.get(final_field) is not True:
        violations.append(final_field + "_not_true")

    if name == "package_identity":
        source = str(row.get("source_commit_sha") or "").strip().casefold()
        tree = str(row.get("package_tree_sha256") or "").strip().casefold()
        if not _SHA40.fullmatch(source):
            violations.append("package_identity_source_commit_invalid")
        if not _SHA256.fullmatch(tree):
            violations.append("package_identity_tree_sha256_invalid")
        if int(row.get("file_count") or 0) <= 0:
            violations.append("package_identity_file_count_not_proven")
        if row.get("runtime_authority") != "eira2":
            violations.append("package_identity_runtime_authority_not_eira2")
        if row.get("git_metadata_required_at_runtime") is not False:
            violations.append("package_identity_git_runtime_dependency_not_false")
        if row.get("eira1_runtime_files_required") is not False:
            violations.append("package_identity_eira1_runtime_files_required_not_false")
        if row.get("eira1_runtime_delegation") is not False:
            violations.append("package_identity_eira1_runtime_delegation_not_false")
        if row.get("legacy_executables_allowed") is not False:
            violations.append("package_identity_legacy_executables_not_false")
    elif name == "native_only_runtime":
        if row.get("eira1_runtime_delegation") is not False:
            violations.append("native_only_runtime_eira1_delegation_not_false")
        if row.get("legacy_executables_allowed_after_cutover") is not False:
            violations.append("native_only_runtime_legacy_executables_not_false")
        if row.get("legacy_evidence_adapter_runtime_authority") is not False:
            violations.append("native_only_runtime_evidence_adapter_has_authority")
        if int(row.get("runtime_modules_scanned") or 0) <= 0:
            violations.append("native_only_runtime_scan_not_proven")
    elif name == "private_models":
        required = tuple(str(item) for item in row.get("required_models") or ())
        if required != ("qwen2.5:3b", "qwen2.5-coder:3b", "gemma3:4b"):
            violations.append("private_models_required_set_not_exact")
        if row.get("required_models_complete") is not True:
            violations.append("private_models_not_complete")
        if row.get("all_manifest_referenced_blobs_hash_verified") is not True:
            violations.append("private_models_blob_hash_closure_not_proven")
        if row.get("model_store_under_eira2") is not True:
            violations.append("private_models_store_not_eira2_owned")
        if row.get("model_transport") != "unix_domain_socket":
            violations.append("private_models_transport_not_unix_socket")
        if row.get("ollama_private_network") is not True or row.get("proxy_private_network") is not True:
            violations.append("private_models_private_network_not_proven")
        if row.get("outbound_network_allowed") is not False:
            violations.append("private_models_outbound_network_not_denied")
        if row.get("internet_model_pull_allowed_at_runtime") is not False:
            violations.append("private_models_runtime_pull_not_denied")
        if row.get("legacy_ollama_service_disabled") is not True:
            violations.append("private_models_legacy_ollama_not_disabled")
        if row.get("eira1_runtime_delegation") is not False:
            violations.append("private_models_eira1_delegation_not_false")
        if row.get("candidate_only") is not True:
            violations.append("private_models_candidate_only_not_true")
        for field in (
            "direct_model_to_delivery_path",
            "direct_model_to_tools_path",
            "direct_model_to_identity_authority",
            "direct_model_to_memory_acceptance",
        ):
            if row.get(field) is not False:
                violations.append("private_models_authority_leak:" + field)
    elif name == "pi_hardware":
        target = str(row.get("target_commit_sha") or "").strip().casefold()
        feature_target = str(row.get("feature_commit_sha") or "").strip().casefold()
        feature_receipt = _object(row, "feature_receipt")
        if not _SHA40.fullmatch(target):
            violations.append("pi_hardware_target_commit_invalid")
        if row.get("target_commit_bound") is not True:
            violations.append("pi_hardware_target_commit_not_bound")
        if not _SHA40.fullmatch(feature_target):
            violations.append("pi_hardware_feature_commit_invalid")
        if row.get("feature_target_commit_bound") is not True:
            violations.append("pi_hardware_feature_commit_not_bound")
        if _SHA40.fullmatch(target) and _SHA40.fullmatch(feature_target) and feature_target != target:
            violations.append("pi_hardware_feature_commit_not_target_commit")
        if row.get("sensory_hardware_verified") is not True:
            violations.append("pi_hardware_sensory_hardware_not_verified")
        if str(feature_receipt.get("schema") or "") != "eira2_pi_feature_grade_v2":
            violations.append("pi_hardware_feature_receipt_schema_not_v2")
        if feature_receipt.get("ok") is not True or feature_receipt.get("pi_feature_parity_complete") is not True:
            violations.append("pi_hardware_feature_receipt_not_complete")
        requirements = _object(feature_receipt, "requirements")
        for requirement in (
            "usb_microphone_future_hotplug_compatibility",
            "usb_microphone_native_capture_adapter",
            "usb_camera_local_vision_and_nonretention",
            "silent_local_ambient_intelligence",
            "multisensory_fusion_single_authority",
        ):
            if requirements.get(requirement) is not True:
                violations.append("pi_hardware_missing_sensory_requirement:" + requirement)
    elif name == "isolated_300":
        if row.get("requested") != 300 or row.get("executed") != 300 or row.get("passed") != 300:
            violations.append("isolated_300_full_case_count_not_proven")
        if row.get("failed") != 0:
            violations.append("isolated_300_failures_not_zero")
        if row.get("shadow_outward_effects") != 0:
            violations.append("isolated_300_shadow_outward_effects_not_zero")
    elif name == "persistent_fuzz":
        if row.get("campaigns") != 3 or row.get("cases_per_campaign") != 100:
            violations.append("persistent_fuzz_3x100_not_proven")
        if row.get("expected") != 300 or row.get("executed") != 300 or row.get("passed") != 300:
            violations.append("persistent_fuzz_full_case_count_not_proven")
        if row.get("failed") != 0:
            violations.append("persistent_fuzz_failures_not_zero")
        if row.get("reused_historical_inputs_executed") != 0:
            violations.append("persistent_fuzz_historical_reuse_not_zero")
        if row.get("duplicate_inputs_inside_execution") != 0:
            violations.append("persistent_fuzz_duplicate_execution_not_zero")

    return {
        "gate": name,
        "schema": schema,
        "required_final_field": final_field,
        "ok": not violations,
        "violations": violations,
    }


def grade_final_cutover_bundle(bundle: Mapping[str, Any]) -> dict[str, object]:
    results = [_gate_result(name, bundle.get(name)) for name in _GATE_SPECS]
    violations: list[str] = []

    foundation = bundle.get("foundation_ci")
    ci = foundation if isinstance(foundation, Mapping) else {}
    ci_violations: list[str] = []
    if str(ci.get("schema") or "") != "eira2_foundation_ci_receipt_v1":
        ci_violations.append("foundation_ci_schema_invalid")
    if str(ci.get("conclusion") or "").casefold() != "success":
        ci_violations.append("foundation_ci_not_success")
    if ci.get("runner_steps_executed") is not True:
        ci_violations.append("foundation_ci_runner_steps_not_proven")
    if ci.get("source_commit_bound") is not True:
        ci_violations.append("foundation_ci_source_commit_not_bound")
    if ci.get("synthetic_merge_sha_used_as_identity") is not False:
        ci_violations.append("foundation_ci_synthetic_merge_identity_not_rejected")
    head_sha = str(ci.get("head_sha") or "").strip().casefold()
    if not _SHA40.fullmatch(head_sha):
        ci_violations.append("foundation_ci_head_sha_invalid")
    if ci.get("pytest_passed") is not True:
        ci_violations.append("foundation_ci_pytest_not_proven")
    if ci.get("compileall_passed") is not True:
        ci_violations.append("foundation_ci_compileall_not_proven")
    results.append({
        "gate": "foundation_ci",
        "schema": str(ci.get("schema") or ""),
        "required_final_field": "exact-source-ci-success",
        "ok": not ci_violations,
        "violations": ci_violations,
    })

    package = bundle.get("package_identity")
    package_row = package if isinstance(package, Mapping) else {}
    package_source = str(package_row.get("source_commit_sha") or "").strip().casefold()
    if _SHA40.fullmatch(head_sha) and package_source != head_sha:
        for result in results:
            if result.get("gate") == "package_identity":
                result["ok"] = False
                cast_violations = result.get("violations")
                if isinstance(cast_violations, list):
                    cast_violations.append("package_identity_not_bound_to_foundation_head")
                break

    pi = bundle.get("pi_hardware")
    pi_row = pi if isinstance(pi, Mapping) else {}
    pi_target = str(pi_row.get("target_commit_sha") or "").strip().casefold()
    if _SHA40.fullmatch(head_sha) and pi_target != head_sha:
        for result in results:
            if result.get("gate") == "pi_hardware":
                result["ok"] = False
                cast_violations = result.get("violations")
                if isinstance(cast_violations, list):
                    cast_violations.append("pi_hardware_not_bound_to_foundation_head")
                break

    preservation = bundle.get("eira1_preservation")
    preserved = preservation if isinstance(preservation, Mapping) else {}
    preservation_violations: list[str] = []
    if str(preserved.get("schema") or "") != "eira2_eira1_preservation_receipt_v1":
        preservation_violations.append("eira1_preservation_schema_invalid")
    before_sha = str(preserved.get("source_tree_sha256_before") or "").strip().casefold()
    after_sha = str(preserved.get("source_tree_sha256_after") or "").strip().casefold()
    if not _SHA256.fullmatch(before_sha) or not _SHA256.fullmatch(after_sha):
        preservation_violations.append("eira1_source_tree_hash_missing_or_invalid")
    elif before_sha != after_sha:
        preservation_violations.append("eira1_source_tree_changed")
    if preserved.get("source_unchanged") is not True:
        preservation_violations.append("eira1_source_unchanged_not_proven")
    if preserved.get("rollback_material_intact") is not True:
        preservation_violations.append("eira1_rollback_material_not_intact")
    if preserved.get("read_only_verification") is not True:
        preservation_violations.append("eira1_preservation_not_read_only")
    if preserved.get("legacy_files_executed") is not False:
        preservation_violations.append("eira1_preservation_executed_legacy_files")
    results.append({
        "gate": "eira1_preservation",
        "schema": str(preserved.get("schema") or ""),
        "required_final_field": "source_unchanged_read_only",
        "ok": not preservation_violations,
        "violations": preservation_violations,
    })

    rollback = bundle.get("rollback_rehearsal")
    rb = rollback if isinstance(rollback, Mapping) else {}
    rollback_violations: list[str] = []
    if str(rb.get("schema") or "") != "eira2_rollback_rehearsal_receipt_v1":
        rollback_violations.append("rollback_schema_invalid")
    for key in (
        "cutover_activation_ok",
        "rollback_activation_ok",
        "eira1_recovery_ok",
        "eira2_reactivation_ok",
    ):
        if rb.get(key) is not True:
            rollback_violations.append(key + "_not_proven")
    if rb.get("data_loss_detected") is not False:
        rollback_violations.append("data_loss_absence_not_proven")
    results.append({
        "gate": "rollback_rehearsal",
        "schema": str(rb.get("schema") or ""),
        "required_final_field": "zero_data_loss_round_trip",
        "ok": not rollback_violations,
        "violations": rollback_violations,
    })

    boundary = grade_eira1_replacement_boundary(bundle)
    results.append({
        "gate": "eira1_replacement_boundary",
        "schema": str(boundary.get("schema") or ""),
        "required_final_field": "eira1_fully_replaced",
        "ok": boundary.get("ok") is True and boundary.get("eira1_fully_replaced") is True,
        "violations": list(boundary.get("violations") or []),
    })

    failed = [result for result in results if not result["ok"]]
    if bundle.get("explicit_cutover_authorization") is not True:
        violations.append("explicit_cutover_authorization_missing")
    if failed:
        violations.append("one_or_more_cutover_gates_failed")

    ok = not violations
    return {
        "schema": "eira2_final_cutover_qualification_v4",
        "ok": ok,
        "final_cutover_authorized": ok,
        "eira1_replacement_boundary": boundary,
        "required_gate_count": len(results),
        "passed_gate_count": sum(1 for result in results if result["ok"]),
        "failed_gate_count": len(failed),
        "violations": violations,
        "failed_gates": [result["gate"] for result in failed],
        "gate_results": results,
        "rules": {
            "all_evidence_gates_must_pass": True,
            "eira1_preserve_value_replace_runtime_boundary_required": True,
            "standalone_package_identity_required": True,
            "git_metadata_required_at_runtime": False,
            "eira1_runtime_files_required": False,
            "native_only_runtime_required": True,
            "private_models_must_be_eira2_owned": True,
            "private_models_must_have_no_outbound_network": True,
            "private_models_must_use_unix_socket_transport": True,
            "private_models_candidate_only": True,
            "pi_hardware_must_bind_exact_source_commit": True,
            "pi_feature_receipt_must_bind_exact_source_commit": True,
            "pi_full_sensory_hardware_receipt_required": True,
            "usb_microphone_future_hotplug_compatibility_required": True,
            "usb_microphone_native_capture_adapter_required": True,
            "usb_microphone_hardware_capture_required_when_present": True,
            "usb_camera_local_vision_and_nonretention_required": True,
            "silent_local_ambient_intelligence_required": True,
            "multisensory_single_authority_fusion_required": True,
            "eira1_runtime_delegation_allowed": False,
            "legacy_executables_allowed_after_cutover": False,
            "foundation_ci_must_bind_real_source_commit": True,
            "synthetic_merge_identity_allowed": False,
            "full_300_isolated_cases_required": True,
            "full_3x100_persistent_fuzz_required": True,
            "foundation_ci_must_execute_real_runner_steps": True,
            "eira1_source_must_be_hash_unchanged": True,
            "eira1_preservation_verification_must_be_read_only": True,
            "rollback_round_trip_required": True,
            "explicit_cutover_authorization_required": True,
            "partial_success_cannot_authorize_cutover": True,
        },
    }

from __future__ import annotations

import argparse
import ast
import json
from pathlib import Path
from typing import Any

from ..registry.extensions import ExtensionManagerService, validate_import_safety
from ..registry.manifests import discover
from .doctor import DoctorReport, DoctorService, audit_project


def audit_dynamic_extensions(project_root: Path, report: DoctorReport) -> DoctorReport:
    root = project_root.expanduser().resolve()
    manager = ExtensionManagerService(root)
    manifests = []
    try:
        manifests = list(manager.discover())
    except Exception as error:
        report.errors.append(f"dynamic_extension_discovery_failed:{type(error).__name__}:{error}")
        report.ok = False
        report.checks["dynamic_extension_manifests"] = 0
        return report

    static_names = {manifest.name for manifest in discover(root / "manifests")}
    dynamic_names = {manifest.name for manifest in manifests}
    for manifest in manifests:
        try:
            path = manager._module_path(manifest)
        except Exception as error:
            report.errors.append(f"dynamic_extension_module_missing:{manifest.name}:{error}")
            continue
        try:
            safety = validate_import_safety(path)
        except Exception as error:
            report.errors.append(f"dynamic_extension_source_invalid:{manifest.name}:{type(error).__name__}:{error}")
            continue
        if safety:
            report.errors.append(
                f"dynamic_extension_import_safety:{manifest.name}:{','.join(safety[:8])}"
            )
        try:
            tree = ast.parse(path.read_text(encoding="utf-8", errors="strict"), filename=str(path))
            symbols = {
                node.name
                for node in tree.body
                if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef))
            }
        except Exception as error:
            report.errors.append(f"dynamic_extension_parse_failed:{manifest.name}:{type(error).__name__}:{error}")
            continue
        if manifest.factory not in symbols:
            report.errors.append(
                f"dynamic_extension_factory_missing:{manifest.name}:{manifest.factory}"
            )
        for dependency in manifest.dependencies:
            if dependency not in static_names and dependency not in dynamic_names:
                report.errors.append(
                    f"dynamic_extension_dependency_unknown:{manifest.name}:{dependency}"
                )

    report.checks["dynamic_extension_manifests"] = len(manifests)
    report.checks["dynamic_extension_errors"] = sum(
        1 for error in report.errors if error.startswith("dynamic_extension_")
    )
    report.ok = not report.errors
    report.checks["errors"] = len(report.errors)
    report.checks["warnings"] = len(report.warnings)
    return report


def full_audit_project(
    project_root: Path,
    *,
    state_path: Path | None = None,
    registry_snapshot: dict[str, Any] | None = None,
    neural_overview: dict[str, Any] | None = None,
    neural_fibers=None,
    run_external_checks: bool = False,
) -> DoctorReport:
    report = audit_project(
        project_root,
        state_path=state_path,
        registry_snapshot=registry_snapshot,
        neural_overview=neural_overview,
        neural_fibers=neural_fibers,
        run_external_checks=run_external_checks,
    )
    return audit_dynamic_extensions(project_root, report)


class FullDoctorService(DoctorService):
    def evaluate(self, *, project_root: Path | None = None, state_path: Path | None = None) -> DoctorReport:
        registry_snapshot = None
        neural_overview = None
        neural_fibers = None
        if self._context is not None:
            try:
                registry = self._context.get_service("registry.graph")
                snapshot = getattr(registry, "snapshot", None)
                if callable(snapshot):
                    registry_snapshot = snapshot()
            except Exception:
                registry_snapshot = None
            try:
                neural = self._context.get_service("interfaces.neural_ui")
                surface = getattr(neural, "surface", None)
                atlas = getattr(surface, "atlas", None)
                if atlas is not None:
                    neural_overview = atlas.overview()
                    neural_fibers = [row.as_dict() for row in atlas.fibers]
            except Exception:
                neural_overview = None
                neural_fibers = None
        report = full_audit_project(
            project_root or self.project_root,
            state_path=state_path if state_path is not None else self.state_path,
            registry_snapshot=registry_snapshot,
            neural_overview=neural_overview,
            neural_fibers=neural_fibers,
            run_external_checks=False,
        )
        self._last = report
        return report


def main() -> int:
    parser = argparse.ArgumentParser(description="EIRA 2.0 full structural Doctor")
    parser.add_argument("--project-root", type=Path, default=Path.cwd())
    parser.add_argument("--state", type=Path, default=None)
    parser.add_argument("--no-state", action="store_true")
    parser.add_argument("--external", action="store_true")
    parser.add_argument("--strict", action="store_true")
    args = parser.parse_args()
    report = full_audit_project(
        args.project_root,
        state_path=None if args.no_state else args.state,
        run_external_checks=args.external,
    )
    print(json.dumps(report.as_dict(), indent=2, sort_keys=True))
    if not report.ok:
        return 1
    if args.strict and report.warnings:
        return 2
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import re
from typing import Any, Iterable, Mapping


_COMMIT_SHA = re.compile(r"^[0-9a-f]{40}$", re.I)
EXPECTED_BOOT_CYCLES = 100


def _object(row: Mapping[str, Any], key: str) -> Mapping[str, Any]:
    value = row.get(key)
    return value if isinstance(value, Mapping) else {}


def _truth(row: Mapping[str, Any], key: str) -> bool:
    return row.get(key) is True


def grade_pi_boot_series(
    rows: Iterable[Mapping[str, Any]],
    *,
    expected_cycles: int = EXPECTED_BOOT_CYCLES,
) -> dict[str, object]:
    sessions = list(rows)
    results: list[dict[str, object]] = []
    boot_ids: set[str] = set()
    duplicate_boot_ids: list[str] = []
    commit_shas: set[str] = set()

    for index, row in enumerate(sessions, 1):
        violations: list[str] = []
        boot_id = str(row.get("boot_id") or "").strip()
        commit = str(row.get("eira2_commit_sha") or "").strip().casefold()
        platform = str(row.get("platform_model") or "").strip()
        easystore = _object(row, "easystore")
        flash = _object(row, "flash_cube")
        tailscale = _object(row, "tailscale")

        if not boot_id:
            violations.append("boot_id_missing")
        elif boot_id in boot_ids:
            duplicate_boot_ids.append(boot_id)
            violations.append("duplicate_boot_id")
        else:
            boot_ids.add(boot_id)
        if not _COMMIT_SHA.fullmatch(commit):
            violations.append("eira2_commit_sha_missing_or_invalid")
        else:
            commit_shas.add(commit)
        if "raspberry pi 5" not in platform.casefold():
            violations.append("platform_not_raspberry_pi_5")
        if row.get("shadow_mode") is not True:
            violations.append("qualification_not_in_shadow_mode")
        if row.get("startup_complete") is not True:
            violations.append("startup_not_complete")
        if row.get("required_services_healthy") is not True:
            violations.append("required_services_not_healthy")
        if row.get("doctor_ok") is not True:
            violations.append("doctor_not_green")
        if row.get("sqlite_integrity_ok") is not True:
            violations.append("sqlite_integrity_not_green")
        if row.get("clean_shutdown_observed") is not True:
            violations.append("clean_shutdown_not_observed")
        if row.get("eira1_source_unchanged") is not True:
            violations.append("eira1_preservation_not_verified")

        for key in ("ok", "dedicated_mount", "source_matches", "writable"):
            if easystore.get(key) is not True:
                violations.append("easystore_" + key + "_not_verified")
        mountpoint = str(easystore.get("mountpoint") or "").strip()
        if not mountpoint or mountpoint == "/":
            violations.append("easystore_mountpoint_not_dedicated")

        if str(flash.get("device_name") or "").strip().casefold() != "flash cube":
            violations.append("flash_cube_exact_device_not_verified")
        if flash.get("connected") is not True:
            violations.append("flash_cube_not_connected")
        if flash.get("reconnected_after_boot") is not True:
            violations.append("flash_cube_reconnect_not_verified")
        if flash.get("playback_ok") is not True:
            violations.append("flash_cube_playback_not_verified")

        if tailscale.get("connected") is not True:
            violations.append("tailscale_not_connected")
        if tailscale.get("peer_reachable") is not True:
            violations.append("tailscale_peer_not_reachable")

        results.append(
            {
                "index": index,
                "boot_id": boot_id,
                "eira2_commit_sha": commit,
                "ok": not violations,
                "violations": violations,
            }
        )

    failures = [row for row in results if not row["ok"]]
    same_commit = len(commit_shas) == 1 and bool(commit_shas)
    target_commit_sha = next(iter(commit_shas)) if same_commit else ""
    ok = (
        len(sessions) == expected_cycles
        and len(boot_ids) == expected_cycles
        and not duplicate_boot_ids
        and same_commit
        and not failures
    )
    return {
        "schema": "eira2_pi_boot_series_grade_v1",
        "ok": ok,
        "clean_boot_series_complete": ok,
        "expected_boot_cycles": expected_cycles,
        "observed_boot_cycles": len(sessions),
        "unique_boot_ids": len(boot_ids),
        "single_commit_across_series": same_commit,
        "target_commit_sha": target_commit_sha,
        "commit_shas": sorted(commit_shas),
        "duplicate_boot_ids": sorted(set(duplicate_boot_ids)),
        "failure_count": len(failures),
        "failure_samples": failures[:40],
        "rules": {
            "same_eira2_commit_for_full_series": True,
            "exact_target_commit_must_be_exported": True,
            "eira1_source_must_remain_unchanged": True,
            "easystore_verified_every_boot": True,
            "flash_cube_reconnected_every_boot": True,
            "tailscale_reachable_every_boot": True,
            "doctor_and_sqlite_green_every_boot": True,
            "clean_shutdown_observed_every_cycle": True,
        },
    }


def grade_pi_feature_receipt(row: Mapping[str, Any]) -> dict[str, object]:
    violations: list[str] = []
    commit = str(row.get("eira2_commit_sha") or "").strip().casefold()
    microphone = _object(row, "microphone")
    usb_microphone = _object(row, "usb_microphone")
    wake = _object(row, "wake_word")
    asr = _object(row, "asr")
    camera = _object(row, "camera")
    ambient = _object(row, "ambient")
    sensory_fusion = _object(row, "sensory_fusion")
    model = _object(row, "local_model")
    blender = _object(row, "blender")
    invention = _object(row, "invention_lab")
    ar = _object(row, "neural_ar")
    flash = _object(row, "flash_cube")

    if not _COMMIT_SHA.fullmatch(commit):
        violations.append("feature_eira2_commit_sha_missing_or_invalid")

    if microphone.get("capture_ok") is not True:
        violations.append("microphone_capture_not_verified")
    try:
        sample_rate = int(microphone.get("sample_rate_hz") or 0)
        channels = int(microphone.get("channels") or 0)
    except (TypeError, ValueError):
        sample_rate = 0
        channels = 0
    if sample_rate <= 0:
        violations.append("microphone_sample_rate_missing")
    if channels <= 0:
        violations.append("microphone_channels_missing")

    for key in (
        "alsa_discovery_supported",
        "capture_adapter_supported",
        "hotplug_supported",
        "canonical_local_voice_ingress",
    ):
        if usb_microphone.get(key) is not True:
            violations.append("usb_microphone_" + key + "_not_verified")
    usb_present = usb_microphone.get("device_present") is True
    if usb_present:
        if usb_microphone.get("capture_ok") is not True:
            violations.append("usb_microphone_capture_not_verified_when_present")
        if usb_microphone.get("hotplug_reconnect_ok") is not True:
            violations.append("usb_microphone_hotplug_reconnect_not_verified_when_present")

    if wake.get("hey_eira_detected") is not True:
        violations.append("hey_eira_wake_not_verified")
    if wake.get("eira_detected") is not True:
        violations.append("eira_wake_not_verified")

    for field in ("clean_cases", "noisy_cases", "pronunciation_confusion_cases"):
        try:
            count = int(asr.get(field) or 0)
        except (TypeError, ValueError):
            count = 0
        if count <= 0:
            violations.append(field + "_missing")
    try:
        asr_failures = int(asr.get("failed_cases") or 0)
    except (TypeError, ValueError):
        asr_failures = -1
    if asr_failures != 0:
        violations.append("asr_failures_not_zero")

    for key in ("device_present", "capture_ok", "local_vision_ok", "hotplug_reconnect_ok"):
        if camera.get(key) is not True:
            violations.append("camera_" + key + "_not_verified")
    if camera.get("raw_frames_retained") is not False:
        violations.append("camera_raw_frame_nonretention_not_verified")
    if camera.get("local_only") is not True:
        violations.append("camera_local_only_not_verified")

    for key in ("enabled", "local_only", "silent_observation_ok", "mute_unmute_ok", "no_outward_answer_without_invocation"):
        if ambient.get(key) is not True:
            violations.append("ambient_" + key + "_not_verified")
    if ambient.get("raw_audio_retained") is not False:
        violations.append("ambient_raw_audio_nonretention_not_verified")

    for key in (
        "audio_and_vision_available_together",
        "provenance_preserved",
        "conflicts_preserved",
        "single_generation_path_verified",
        "single_identity_authority_verified",
        "single_delivery_authority_verified",
    ):
        if sensory_fusion.get(key) is not True:
            violations.append("sensory_fusion_" + key + "_not_verified")

    if model.get("available") is not True:
        violations.append("local_model_not_available")
    if model.get("single_generation_path_verified") is not True:
        violations.append("local_model_single_generation_path_not_verified")
    if model.get("unauthorized_outbound_network_calls") != 0:
        violations.append("local_model_unauthorized_network_calls_not_zero")

    if str(flash.get("device_name") or "").strip().casefold() != "flash cube":
        violations.append("feature_flash_cube_exact_device_not_verified")
    if flash.get("playback_ok") is not True:
        violations.append("feature_flash_cube_playback_not_verified")
    if flash.get("spoken_text_matches_accepted_text") is not True:
        violations.append("feature_voice_text_binding_not_verified")

    if blender.get("executable_found") is not True:
        violations.append("blender_executable_not_verified")
    if blender.get("headless_render_ok") is not True:
        violations.append("blender_headless_render_not_verified")

    for key in ("render_ok", "visual_repair_loop_ok", "glb_ok", "usdz_ok"):
        if invention.get(key) is not True:
            violations.append("invention_lab_" + key + "_not_verified")

    for key in ("server_reachable", "neural_graph_loaded", "all_nodes_visible", "device_ar_walkthrough_ok"):
        if ar.get(key) is not True:
            violations.append("neural_ar_" + key + "_not_verified")

    if row.get("required_services_healthy") is not True:
        violations.append("feature_required_services_not_healthy")
    if row.get("doctor_ok") is not True:
        violations.append("feature_doctor_not_green")
    if row.get("eira1_source_unchanged") is not True:
        violations.append("feature_eira1_preservation_not_verified")

    ok = not violations
    return {
        "schema": "eira2_pi_feature_grade_v2",
        "ok": ok,
        "pi_feature_parity_complete": ok,
        "eira2_commit_sha": commit,
        "violations": violations,
        "requirements": {
            "exact_eira2_commit_required": True,
            "real_microphone_capture": True,
            "usb_microphone_future_hotplug_compatibility": True,
            "usb_microphone_native_capture_adapter": True,
            "usb_microphone_hardware_capture_required_when_present": True,
            "both_wake_phrases": True,
            "clean_noisy_and_pronunciation_asr": True,
            "usb_camera_local_vision_and_nonretention": True,
            "silent_local_ambient_intelligence": True,
            "multisensory_fusion_single_authority": True,
            "local_model_boundary": True,
            "flash_cube_exact_voice_path": True,
            "blender_headless_render": True,
            "invention_lab_glb_and_usdz": True,
            "neural_ar_device_walkthrough": True,
        },
        "usb_microphone_hardware_present": usb_present,
    }


def grade_pi_hardware_qualification(
    boot_rows: Iterable[Mapping[str, Any]],
    feature_receipt: Mapping[str, Any],
    *,
    expected_cycles: int = EXPECTED_BOOT_CYCLES,
) -> dict[str, object]:
    boots = grade_pi_boot_series(boot_rows, expected_cycles=expected_cycles)
    features = grade_pi_feature_receipt(feature_receipt)
    target_commit_sha = str(boots.get("target_commit_sha") or "").strip().casefold()
    target_bound = bool(_COMMIT_SHA.fullmatch(target_commit_sha))
    feature_commit_sha = str(features.get("eira2_commit_sha") or "").strip().casefold()
    feature_target_bound = bool(
        target_bound
        and _COMMIT_SHA.fullmatch(feature_commit_sha)
        and feature_commit_sha == target_commit_sha
    )
    ok = bool(boots["ok"] and features["ok"] and target_bound and feature_target_bound)
    return {
        "schema": "eira2_pi_hardware_qualification_v2",
        "ok": ok,
        "pi_runtime_verified": ok,
        "target_commit_sha": target_commit_sha,
        "target_commit_bound": target_bound,
        "feature_commit_sha": feature_commit_sha,
        "feature_target_commit_bound": feature_target_bound,
        "easystore_verified": bool(boots["ok"]),
        "flash_cube_verified": bool(boots["ok"] and features["ok"] and feature_target_bound),
        "tailscale_verified": bool(boots["ok"]),
        "sensory_hardware_verified": bool(boots["ok"] and features["ok"] and feature_target_bound),
        "clean_boot_cycles": int(boots["observed_boot_cycles"]),
        "boot_series": boots,
        "feature_receipt": features,
    }

from __future__ import annotations

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState
from ..registry.graph import NodeRegistryService


class HealthCoordinator:
    spec = ServiceSpec(
        "operations.health",
        required=True,
        dependencies=("interfaces.ingress", "registry.graph"),
    )

    def __init__(self) -> None:
        self._context: RuntimeContext | None = None
        self._state = ServiceState.DECLARED

    async def start(self, context: RuntimeContext) -> None:
        self._context = context
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._state = ServiceState.STOPPED
        self._context = None

    async def health(self) -> Health:
        return Health(self._state)

    async def snapshot(self) -> dict:
        if self._context is None:
            raise RuntimeError("health_coordinator_not_ready")
        statuses = await self._context.status()  # type: ignore[attr-defined]
        required: set[str] = set()
        try:
            registry = self._context.get_service("registry.graph")
            if isinstance(registry, NodeRegistryService):
                required = {
                    str(row.get("name"))
                    for row in registry.snapshot().get("nodes", [])
                    if isinstance(row, dict) and row.get("required") is True
                }
        except Exception:
            required = set()
        failed = sorted(
            name for name, health in statuses.items()
            if health.state == ServiceState.FAILED
        )
        degraded = sorted(
            name for name, health in statuses.items()
            if health.state == ServiceState.DEGRADED
        )
        required_failures = sorted(name for name in failed if name in required)
        return {
            "ok": not required_failures,
            "services": {
                name: {"state": health.state.value, "detail": health.detail}
                for name, health in sorted(statuses.items())
            },
            "failed_services": failed,
            "degraded_services": degraded,
            "required_failures": required_failures,
            "required_service_count": len(required),
        }

from __future__ import annotations

import csv
import hashlib
import json
import os
import re
import shutil
from pathlib import Path
from typing import Any, Mapping

from ..migration.qualification import grade_migration_inventory, grade_migration_rehearsal
from ..migration.runtime_parity import grade_runtime_file_dispositions
from ..repair.cutover import verify_cutover_authorization
from .easystore_cutover import _atomic_json, _read_json
from .package_identity import verify_package_manifest


EXPECTED_RUNTIME_FILES = 12262
EXPECTED_INVENTORY_ENTRIES = 76056
_SHA256 = re.compile(r"^[0-9a-f]{64}$", re.I)
_FILE_TYPES = {"file", "regular"}
_SYMLINK_TYPES = {"symlink", "link"}
_LOCAL_RETIRE_DISPOSITIONS = {
    "migrate_runtime",
    "migrate_state",
    "migrate_artifact",
    "retain_evidence",
    "secret_reference",
    "regenerate",
}
_LOCAL_RETAIN_DISPOSITIONS = {"external_dependency"}
_LOCAL_ACCOUNTED_DISPOSITIONS = _LOCAL_RETIRE_DISPOSITIONS | _LOCAL_RETAIN_DISPOSITIONS


def _sha256_file(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def _absolute_lexical(path: Path | str) -> Path:
    return Path(os.path.abspath(os.path.expanduser(str(path))))


def _inside(path: Path, root: Path) -> bool:
    return path != root and root in path.parents


def _load_ledger_rows(ledger: Path) -> list[dict[str, str]]:
    try:
        with ledger.open("r", encoding="utf-8", newline="") as handle:
            return [dict(row) for row in csv.DictReader(handle)]
    except (OSError, UnicodeError, csv.Error) as error:
        raise RuntimeError("legacy_retirement_migration_ledger_unreadable") from error


def _load_receipt_rows(path: Path, *, error_prefix: str) -> list[dict[str, object]]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise RuntimeError(error_prefix + "_unreadable") from error
    if isinstance(payload, list):
        rows = payload
    elif isinstance(payload, dict):
        rows = payload.get("rows", payload.get("receipts", []))
    else:
        raise RuntimeError(error_prefix + "_invalid")
    if not isinstance(rows, list) or not all(isinstance(row, dict) for row in rows):
        raise RuntimeError(error_prefix + "_rows_invalid")
    return list(rows)


def _load_runtime_rows(
    raw_rows: list[dict[str, str]],
    *,
    live_root: Path,
    project_root: Path,
    expected_runtime_files: int,
) -> list[dict[str, Any]]:
    runtime_rows: list[dict[str, Any]] = []
    seen: set[Path] = set()
    for row in raw_rows:
        if str(row.get("disposition") or "").strip().casefold() != "migrate_runtime":
            continue
        if str(row.get("entry_type") or "").strip().casefold() not in _FILE_TYPES:
            continue
        raw_path = str(row.get("source_path") or "").strip()
        if not raw_path:
            raise RuntimeError("legacy_retirement_runtime_source_path_missing")
        source = _absolute_lexical(raw_path)
        if not Path(raw_path).expanduser().is_absolute():
            raise RuntimeError("legacy_retirement_runtime_source_path_not_absolute:" + raw_path)
        if source == project_root or _inside(source, project_root):
            raise RuntimeError("legacy_retirement_ledger_targets_eira2:" + str(source))
        if source == live_root or not _inside(source, live_root):
            raise RuntimeError("legacy_retirement_ledger_path_outside_live_root:" + str(source))
        if source in seen:
            raise RuntimeError("legacy_retirement_duplicate_runtime_path:" + str(source))
        seen.add(source)
        expected_sha = str(row.get("sha256") or "").strip().casefold()
        if not _SHA256.fullmatch(expected_sha):
            raise RuntimeError("legacy_retirement_runtime_sha256_invalid:" + str(source))
        runtime_rows.append(
            {
                "entry_id": str(row.get("entry_id") or ""),
                "source_path": source,
                "sha256": expected_sha,
                "size": int(row.get("size") or 0),
            }
        )

    if len(runtime_rows) != expected_runtime_files:
        raise RuntimeError(
            f"legacy_retirement_runtime_file_count_mismatch:{len(runtime_rows)}:{expected_runtime_files}"
        )
    return runtime_rows


def _local_inventory_rows(
    raw_rows: list[dict[str, str]],
    *,
    live_root: Path,
    project_root: Path,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Materialize every ledger-accounted local file/symlink in the LIVE universe.

    Local entries are not presumed to be EIRA1 merely because they live outside the
    EIRA2 subtree.  Their canonical disposition determines whether they are retired
    or retained.  In particular, ``external_dependency`` may remain in place and is
    re-verified unchanged after EIRA1-owned material is removed.
    """
    files: list[dict[str, Any]] = []
    symlinks: list[dict[str, Any]] = []
    seen: set[Path] = set()
    for row in raw_rows:
        raw_path = str(row.get("source_path") or "").strip()
        if not raw_path:
            continue
        source_raw = Path(raw_path).expanduser()
        if not source_raw.is_absolute():
            continue
        source = _absolute_lexical(source_raw)
        if source == project_root or _inside(source, project_root):
            raise RuntimeError("legacy_retirement_inventory_targets_eira2:" + str(source))
        if source == live_root or not _inside(source, live_root):
            continue

        entry_type = str(row.get("entry_type") or "").strip().casefold()
        if entry_type not in _FILE_TYPES | _SYMLINK_TYPES:
            continue
        if source in seen:
            raise RuntimeError("legacy_retirement_duplicate_local_path:" + str(source))
        seen.add(source)

        disposition = str(row.get("disposition") or "").strip().casefold()
        if disposition not in _LOCAL_ACCOUNTED_DISPOSITIONS:
            raise RuntimeError(
                "legacy_retirement_local_path_has_unhandled_disposition:"
                + disposition
                + ":"
                + str(source)
            )
        materialized = {
            "entry_id": str(row.get("entry_id") or ""),
            "source_path": source,
            "entry_type": entry_type,
            "disposition": disposition,
            "sha256": str(row.get("sha256") or "").strip().casefold(),
            "size": int(row.get("size") or 0),
        }
        if entry_type in _FILE_TYPES:
            if not _SHA256.fullmatch(materialized["sha256"]):
                raise RuntimeError("legacy_retirement_local_sha256_invalid:" + str(source))
            files.append(materialized)
        else:
            symlinks.append(materialized)
    return files, symlinks


def _receipt_index(rows: list[dict[str, object]]) -> dict[Path, dict[str, object]]:
    indexed: dict[Path, dict[str, object]] = {}
    for row in rows:
        raw = str(row.get("source_path") or row.get("path") or "").strip()
        if not raw:
            continue
        source = _absolute_lexical(raw)
        if source in indexed:
            raise RuntimeError("legacy_retirement_duplicate_migration_receipt:" + str(source))
        indexed[source] = row
    return indexed


def _retained_destination(project_root: Path, row: Mapping[str, Any], bucket: str) -> Path:
    source = row["source_path"]
    assert isinstance(source, Path)
    entry_id = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(row.get("entry_id") or "entry"))[:80]
    fingerprint = hashlib.sha256(str(source).encode("utf-8")).hexdigest()[:16]
    name = source.name or "entry"
    return project_root / "var" / "eira1-retained" / bucket / f"{entry_id}-{fingerprint}-{name}"


def _copy_retained_file(source: Path, destination: Path, expected_sha: str) -> None:
    destination.parent.mkdir(parents=True, exist_ok=True)
    os.chmod(destination.parent, 0o700)
    if destination.exists() or destination.is_symlink():
        if destination.is_symlink() or not destination.is_file() or _sha256_file(destination) != expected_sha:
            raise RuntimeError("legacy_retirement_retained_destination_conflict:" + str(destination))
    else:
        shutil.copy2(source, destination)
    os.chmod(destination, 0o600)
    if destination.stat().st_mode & 0o111:
        raise RuntimeError("legacy_retirement_retained_file_executable:" + str(destination))
    if _sha256_file(destination) != expected_sha:
        raise RuntimeError("legacy_retirement_retained_file_hash_mismatch:" + str(destination))


def _scan_non_eira2_entries(live_root: Path, project_root: Path) -> list[Path]:
    """Inventory paths outside EIRA2 without asserting ownership."""
    entries: list[Path] = []
    for path in live_root.rglob("*"):
        absolute = _absolute_lexical(path)
        if absolute == project_root or _inside(absolute, project_root):
            continue
        entries.append(absolute)
    return entries


def _remove_empty_non_eira2_directories(live_root: Path, project_root: Path) -> None:
    directories = [
        path
        for path in _scan_non_eira2_entries(live_root, project_root)
        if path.is_dir() and not path.is_symlink()
    ]
    for directory in sorted(directories, key=lambda value: len(value.parts), reverse=True):
        try:
            directory.rmdir()
        except OSError:
            continue


def _require_evidence_outside_retirement_surface(path: Path, *, live_root: Path, project_root: Path) -> None:
    absolute = _absolute_lexical(path)
    if _inside(absolute, live_root) and not (absolute == project_root or _inside(absolute, project_root)):
        raise RuntimeError("legacy_retirement_evidence_input_inside_retirement_surface:" + str(absolute))


def retire_legacy_runtime(
    *,
    live_root: Path,
    project_root: Path,
    authorization: Path,
    handoff_receipt: Path,
    migration_ledger: Path,
    migration_rehearsal_receipt: Path,
    runtime_parity_receipt: Path,
    evidence_output: Path | None = None,
    expected_runtime_files: int = EXPECTED_RUNTIME_FILES,
) -> dict[str, Any]:
    """Retire the ledger-selected EIRA1-owned LIVE footprint after EIRA2 takeover.

    The 76,056-entry ledger is an accounting universe, not a deletion list. Runtime,
    migrated state/artifacts, evidence, secrets references, and regenerable EIRA1
    material are retired only according to their canonical disposition. Explicit
    ``external_dependency`` entries may remain in LIVE and are hash/target-verified
    before and after retirement. This proves zero remaining EIRA1-owned selected
    footprint without pretending every non-EIRA2 path belongs to EIRA1.
    """
    live_root = live_root.expanduser().resolve()
    project_root = project_root.expanduser().resolve()
    authorization=<REDACTED>
    handoff_receipt = handoff_receipt.expanduser().resolve()
    migration_ledger = migration_ledger.expanduser().resolve()
    migration_rehearsal_receipt = migration_rehearsal_receipt.expanduser().resolve()
    runtime_parity_receipt = runtime_parity_receipt.expanduser().resolve()

    if not _inside(project_root, live_root):
        raise RuntimeError("legacy_retirement_eira2_project_not_inside_live_root")
    for evidence_path in (
        authorization,
        handoff_receipt,
        migration_ledger,
        migration_rehearsal_receipt,
        runtime_parity_receipt,
    ):
        _require_evidence_outside_retirement_surface(
            evidence_path,
            live_root=live_root,
            project_root=project_root,
        )
    if evidence_output is not None:
        _require_evidence_outside_retirement_surface(
            evidence_output.expanduser().resolve(),
            live_root=live_root,
            project_root=project_root,
        )

    handoff = _read_json(handoff_receipt, "legacy_retirement_handoff_receipt_unreadable")
    if handoff.get("schema") != "eira2_runtime_handoff_v2" or handoff.get("ok") is not True:
        raise RuntimeError("legacy_retirement_eira2_handoff_not_verified")
    if handoff.get("runtime_authority") != "eira2":
        raise RuntimeError("legacy_retirement_eira2_not_runtime_authority")
    if handoff.get("eira1_runtime_delegation") is not False:
        raise RuntimeError("legacy_retirement_eira1_delegation_not_false")
    if handoff.get("legacy_executables_allowed") is not False:
        raise RuntimeError("legacy_retirement_legacy_execution_not_disabled")
    if handoff.get("legacy_process_stopped_cleanly") is not True:
        raise RuntimeError("legacy_retirement_legacy_process_not_stopped_cleanly")
    if handoff.get("eira2_required_services_healthy") is not True:
        raise RuntimeError("legacy_retirement_eira2_services_not_healthy")

    target_sha = str(handoff.get("target_eira2_sha") or "").strip().casefold()
    package_tree = str(handoff.get("package_tree_sha256") or "").strip().casefold()
    auth = verify_cutover_authorization(authorization, expected_target_sha=target_sha)
    if str(auth.get("package_tree_sha256") or "").strip().casefold() != package_tree:
        raise RuntimeError("legacy_retirement_package_tree_not_authorized")
    manifest_name = str(auth.get("package_manifest_file") or "").strip()
    verify_package_manifest(
        project_root,
        project_root / manifest_name,
        expected_source_commit_sha=target_sha,
        expected_tree_sha256=package_tree,
    )

    bundle_file = str(auth.get("qualification_bundle_file") or "").strip()
    bundle = _read_json(
        authorization.with_name(bundle_file),
        "legacy_retirement_qualification_bundle_unreadable",
    )
    migration = bundle.get("migration_76056")
    migration_row = migration if isinstance(migration, Mapping) else {}
    rehearsal = migration_row.get("rehearsal")
    rehearsal_row = rehearsal if isinstance(rehearsal, Mapping) else {}
    runtime_grade = bundle.get("runtime_file_parity")
    runtime_row = runtime_grade if isinstance(runtime_grade, Mapping) else {}
    if (
        migration_row.get("schema") != "eira2_full_migration_qualification_v1"
        or migration_row.get("ok") is not True
        or migration_row.get("migration_cutover_evidence_complete") is not True
        or rehearsal_row.get("rehearsal_hash_preservation_complete") is not True
    ):
        raise RuntimeError("legacy_retirement_preserved_value_migration_not_complete")
    if (
        runtime_row.get("schema") != "eira2_runtime_file_parity_grade_v1"
        or runtime_row.get("ok") is not True
        or runtime_row.get("catalog_active_runtime_files_complete") is not True
        or int(runtime_row.get("expected_active_runtime_files") or -1) != expected_runtime_files
        or int(runtime_row.get("source_runtime_files") or -1) != expected_runtime_files
        or int(runtime_row.get("passed_runtime_files") or -1) != expected_runtime_files
    ):
        raise RuntimeError("legacy_retirement_runtime_parity_not_complete")

    ledger_rows = _load_ledger_rows(migration_ledger)
    inventory_regrade = grade_migration_inventory(ledger_rows)
    if inventory_regrade.get("ok") is not True:
        raise RuntimeError("legacy_retirement_exact_migration_ledger_regrade_failed")

    migration_receipts = _load_receipt_rows(
        migration_rehearsal_receipt,
        error_prefix="legacy_retirement_migration_rehearsal_receipts",
    )
    rehearsal_regrade = grade_migration_rehearsal(ledger_rows, migration_receipts)
    if rehearsal_regrade.get("ok") is not True:
        raise RuntimeError("legacy_retirement_exact_migration_rehearsal_regrade_failed")

    runtime_receipts = _load_receipt_rows(
        runtime_parity_receipt,
        error_prefix="legacy_retirement_runtime_receipts",
    )
    runtime_regrade = grade_runtime_file_dispositions(
        ledger_rows,
        runtime_receipts,
        expected_count=expected_runtime_files,
    )
    if runtime_regrade.get("ok") is not True:
        raise RuntimeError("legacy_retirement_exact_runtime_parity_regrade_failed")

    runtime_rows = _load_runtime_rows(
        ledger_rows,
        live_root=live_root,
        project_root=project_root,
        expected_runtime_files=expected_runtime_files,
    )
    local_files, local_symlinks = _local_inventory_rows(
        ledger_rows,
        live_root=live_root,
        project_root=project_root,
    )
    retire_files = [row for row in local_files if row["disposition"] in _LOCAL_RETIRE_DISPOSITIONS]
    retained_files = [row for row in local_files if row["disposition"] in _LOCAL_RETAIN_DISPOSITIONS]
    retire_symlinks = [row for row in local_symlinks if row["disposition"] in _LOCAL_RETIRE_DISPOSITIONS]
    retained_symlinks = [row for row in local_symlinks if row["disposition"] in _LOCAL_RETAIN_DISPOSITIONS]

    runtime_paths = {row["source_path"] for row in runtime_rows}
    local_runtime_paths = {
        row["source_path"] for row in retire_files if row["disposition"] == "migrate_runtime"
    }
    if runtime_paths != local_runtime_paths:
        raise RuntimeError("legacy_retirement_runtime_set_not_equal_local_inventory_runtime_set")

    migration_index = _receipt_index(migration_receipts)
    var_root = project_root / "var"
    evidence_rows: list[dict[str, Any]] = []
    relocation_plan: list[tuple[Path, Path, str]] = []
    migrated_source_count = 0
    evidence_relocation_count = 0
    secret_relocation_count = 0
    retained_dependency_file_count = 0
    retained_dependency_symlink_count = 0
    retained_symlink_targets: dict[Path, str] = {}

    # Full preflight: validate every ledger-accounted local file before changing any
    # EIRA1-owned byte, including dependencies that must remain untouched.
    for row in local_files:
        source = row["source_path"]
        assert isinstance(source, Path)
        if not source.exists():
            raise RuntimeError("legacy_retirement_local_file_missing_before_retirement:" + str(source))
        if source.is_symlink() or not source.is_file():
            raise RuntimeError("legacy_retirement_local_entry_not_regular_file:" + str(source))
        observed_sha = _sha256_file(source)
        if observed_sha != row["sha256"]:
            raise RuntimeError("legacy_retirement_local_sha256_changed:" + str(source))
        if source.stat().st_size != int(row["size"]):
            raise RuntimeError("legacy_retirement_local_size_changed:" + str(source))

        disposition = str(row["disposition"])
        destination: Path | None = None
        retained_in_place = False
        if disposition in {"migrate_state", "migrate_artifact"}:
            receipt = migration_index.get(source)
            if receipt is None:
                raise RuntimeError("legacy_retirement_migration_receipt_missing:" + str(source))
            raw_destination = str(receipt.get("destination_path") or receipt.get("staged_path") or "").strip()
            if not raw_destination or not Path(raw_destination).expanduser().is_absolute():
                raise RuntimeError("legacy_retirement_migration_destination_invalid:" + str(source))
            destination = _absolute_lexical(raw_destination)
            if not _inside(destination, var_root):
                raise RuntimeError("legacy_retirement_migration_destination_not_in_eira2_var:" + str(destination))
            if destination.is_symlink() or not destination.is_file():
                raise RuntimeError("legacy_retirement_migration_destination_missing:" + str(destination))
            if _sha256_file(destination) != observed_sha:
                raise RuntimeError("legacy_retirement_migration_destination_hash_mismatch:" + str(destination))
            if disposition == "migrate_artifact" and destination.stat().st_mode & 0o111:
                raise RuntimeError("legacy_retirement_migrated_artifact_is_executable:" + str(destination))
            migrated_source_count += 1
        elif disposition == "retain_evidence":
            destination = _retained_destination(project_root, row, "evidence")
            relocation_plan.append((source, destination, observed_sha))
            evidence_relocation_count += 1
        elif disposition == "secret_reference":
            destination = _retained_destination(project_root, row, "secrets")
            relocation_plan.append((source, destination, observed_sha))
            secret_relocation_count += 1
        elif disposition == "external_dependency":
            destination = source
            retained_in_place = True
            retained_dependency_file_count += 1
        elif disposition not in {"migrate_runtime", "regenerate"}:
            raise RuntimeError("legacy_retirement_unhandled_local_disposition:" + disposition)

        evidence_rows.append(
            {
                "entry_id": row["entry_id"],
                "source_path": str(source),
                "size": row["size"],
                "sha256": observed_sha,
                "source_disposition": disposition,
                "retained_destination": str(destination) if destination is not None else "",
                "retained_in_place": retained_in_place,
                "executable_content_in_receipt": False,
            }
        )

    for row in local_symlinks:
        source = row["source_path"]
        assert isinstance(source, Path)
        if not source.is_symlink():
            raise RuntimeError("legacy_retirement_symlink_changed_or_missing:" + str(source))
        target = os.readlink(source)
        retained_in_place = row["disposition"] == "external_dependency"
        if retained_in_place:
            retained_dependency_symlink_count += 1
            retained_symlink_targets[source] = target
        evidence_rows.append(
            {
                "entry_id": row["entry_id"],
                "source_path": str(source),
                "source_disposition": row["disposition"],
                "symlink_target": target,
                "retained_destination": str(source) if retained_in_place else "",
                "retained_in_place": retained_in_place,
                "executable_content_in_receipt": False,
            }
        )

    accounted_paths = {row["source_path"] for row in local_files} | {
        row["source_path"] for row in local_symlinks
    }
    actual_filelike = {
        path
        for path in _scan_non_eira2_entries(live_root, project_root)
        if path.is_file() or path.is_symlink()
    }
    untracked = sorted(actual_filelike - accounted_paths, key=str)
    if untracked:
        raise RuntimeError(
            "legacy_retirement_untracked_non_eira2_filelike_present:"
            + ";".join(str(path) for path in untracked[:20])
        )
    missing_accounted = sorted(accounted_paths - actual_filelike, key=str)
    if missing_accounted:
        raise RuntimeError(
            "legacy_retirement_inventory_files_missing_from_live_tree:"
            + ";".join(str(path) for path in missing_accounted[:20])
        )

    # Preserve evidence/secrets inside EIRA2 var before destructive work. These are
    # data-only, mode 0600, and are never imported/executed by the runtime package.
    for source, destination, expected_sha in relocation_plan:
        _copy_retained_file(source, destination, expected_sha)

    verify_package_manifest(
        project_root,
        project_root / manifest_name,
        expected_source_commit_sha=target_sha,
        expected_tree_sha256=package_tree,
    )

    for row in retire_files:
        source = row["source_path"]
        assert isinstance(source, Path)
        source.unlink()
    for row in retire_symlinks:
        source = row["source_path"]
        assert isinstance(source, Path)
        source.unlink()
    _remove_empty_non_eira2_directories(live_root, project_root)

    retire_paths = {row["source_path"] for row in retire_files} | {
        row["source_path"] for row in retire_symlinks
    }
    retained_paths = {row["source_path"] for row in retained_files} | {
        row["source_path"] for row in retained_symlinks
    }
    remaining_filelike = {
        path
        for path in _scan_non_eira2_entries(live_root, project_root)
        if path.is_file() or path.is_symlink()
    }
    retired_still_present = sorted(retire_paths & remaining_filelike, key=str)
    if retired_still_present:
        raise RuntimeError(
            "legacy_retirement_eira1_owned_entries_still_present:"
            + ";".join(str(path) for path in retired_still_present[:20])
        )
    unexpected_remaining = sorted(remaining_filelike - retained_paths, key=str)
    if unexpected_remaining:
        raise RuntimeError(
            "legacy_retirement_unaccounted_filelike_remains_after_retirement:"
            + ";".join(str(path) for path in unexpected_remaining[:20])
        )
    missing_retained = sorted(retained_paths - remaining_filelike, key=str)
    if missing_retained:
        raise RuntimeError(
            "legacy_retirement_retained_dependency_missing_after_retirement:"
            + ";".join(str(path) for path in missing_retained[:20])
        )

    for row in retained_files:
        source = row["source_path"]
        assert isinstance(source, Path)
        if source.is_symlink() or not source.is_file():
            raise RuntimeError("legacy_retirement_retained_dependency_type_changed:" + str(source))
        if _sha256_file(source) != row["sha256"] or source.stat().st_size != int(row["size"]):
            raise RuntimeError("legacy_retirement_retained_dependency_changed:" + str(source))
    for row in retained_symlinks:
        source = row["source_path"]
        assert isinstance(source, Path)
        if not source.is_symlink() or os.readlink(source) != retained_symlink_targets[source]:
            raise RuntimeError("legacy_retirement_retained_dependency_symlink_changed:" + str(source))

    # Removing EIRA1-owned material must not alter a single sealed EIRA2 package byte.
    # var/ is intentionally excluded from package identity and carries state/evidence.
    verify_package_manifest(
        project_root,
        project_root / manifest_name,
        expected_source_commit_sha=target_sha,
        expected_tree_sha256=package_tree,
    )

    local_runtime_count = sum(1 for row in retire_files if row["disposition"] == "migrate_runtime")
    receipt = {
        "schema": "eira2_legacy_runtime_retirement_v3",
        "ok": True,
        "target_eira2_sha": target_sha,
        "package_tree_sha256": package_tree,
        "runtime_authority": "eira2",
        "eira2_live_verified_before_retirement": True,
        "eira2_package_verified_before_and_after_retirement": True,
        "preserved_value_migration_verified_before_retirement": True,
        "migration_inventory_regraded_before_retirement": True,
        "migration_rehearsal_regraded_before_retirement": True,
        "runtime_file_parity_verified_before_retirement": True,
        "runtime_parity_regraded_before_retirement": True,
        "retirement_bound_to_migration_ledger": True,
        "retirement_bound_to_migration_rehearsal_receipts": True,
        "retirement_bound_to_runtime_parity_receipts": True,
        "retirement_is_disposition_and_ownership_scoped": True,
        "entire_76056_inventory_treated_as_deletion_target": False,
        "arbitrary_retirement_paths_allowed": False,
        "eira1_runtime_delegation": False,
        "legacy_executables_allowed": False,
        "legacy_runtime_required_after_retirement": False,
        "eira1_installed_runtime_required": False,
        "inventory_entries_accounted": len(ledger_rows),
        "inventory_76056_accounted": len(ledger_rows) == EXPECTED_INVENTORY_ENTRIES,
        "migration_rehearsal_entries_verified": int(rehearsal_regrade.get("verified_staged_entries") or 0),
        "legacy_runtime_files_expected": expected_runtime_files,
        "legacy_runtime_files_removed": local_runtime_count,
        "legacy_runtime_files_remaining": 0,
        "legacy_local_files_removed": len(retire_files),
        "legacy_local_symlinks_removed": len(retire_symlinks),
        "legacy_local_installation_entries_remaining": 0,
        "eira1_owned_local_entries_remaining": 0,
        "legacy_installation_footprint_retired": True,
        "preserved_state_or_artifact_files_selected": migrated_source_count,
        "preserved_state_or_artifact_sources_retired_after_verified_migration": migrated_source_count,
        "retained_evidence_files_relocated_non_executable": evidence_relocation_count,
        "secret_reference_files_relocated_securely": secret_relocation_count,
        "retained_local_external_dependency_files": retained_dependency_file_count,
        "retained_local_external_dependency_symlinks": retained_dependency_symlink_count,
        "retained_local_external_dependencies": retained_dependency_file_count + retained_dependency_symlink_count,
        "retained_local_external_dependencies_verified_unchanged": True,
        "external_dependencies_removed": False,
        "secret_values_logged_in_receipt": False,
        "evidence_only_manifest": evidence_rows,
        "evidence_manifest_contains_executable_bytes": False,
        "retained_archive_executable_files": 0,
    }
    target = evidence_output or (project_root / "var" / "eira2-legacy-retirement.json")
    _atomic_json(target.expanduser().resolve(), receipt)
    return receipt

from __future__ import annotations

import ast
from pathlib import Path
from typing import Any


_RUNTIME_CRITICAL_PREFIXES = (
    "__main__.py",
    "live.py",
    "runtime.py",
    "adapters/ollama.py",
    "capabilities/",
    "commands/",
    "config/",
    "conversation/",
    "delivery/",
    "evidence/",
    "extensions/",
    "interfaces/",
    "kernel/",
    "learning/",
    "memory/",
    "neural/",
    "operations/",
    "reasoning/",
    "registry/",
    "repair/",
    "security/",
    "state/",
)

_FORBIDDEN_EIRA1_COMPATIBILITY_PREFIX = "adapters/eira1/"
_AUDIT_SELF = "operations/native_only_audit.py"


def _is_runtime_critical(relative: str) -> bool:
    return any(relative == prefix or relative.startswith(prefix) for prefix in _RUNTIME_CRITICAL_PREFIXES)


def _module_names(node: ast.AST) -> tuple[str, ...]:
    if isinstance(node, ast.ImportFrom):
        return (str(node.module or ""),)
    if isinstance(node, ast.Import):
        return tuple(alias.name for alias in node.names)
    return ()


def _string_literals(tree: ast.AST) -> tuple[str, ...]:
    values: list[str] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            values.append(node.value)
    return tuple(values)


def _is_legacy_root_extension_module(module: str) -> bool:
    lowered = str(module or "").casefold()
    return lowered == "extensions" or lowered.startswith("extensions.")


def grade_native_only_runtime(project_root: Path) -> dict[str, Any]:
    """Prove the active EIRA2 source surface cannot execute or delegate to EIRA1.

    Historical EIRA1 material may remain only as inert evidence/data governed by
    migration and retirement tooling. Runtime-critical EIRA2 modules may not import
    EIRA1 adapters, the legacy root ``extensions`` package, root ``main.py``, or
    dynamically name those executable surfaces. EIRA2's own package namespaces such
    as ``eira2.registry.extensions`` remain valid because they are native EIRA2 code.

    The v1 receipt schema is intentionally retained because it is a frozen cutover
    interface; the rules beneath that schema are strengthened without breaking the
    final qualification contract.
    """
    root = project_root.expanduser().resolve()
    package = root / "eira2"
    violations: list[str] = []
    scanned = 0
    compatibility_python_files: list[str] = []

    if not package.is_dir():
        violations.append("eira2_package_missing")
    else:
        compatibility_dir = package / "adapters" / "eira1"
        if compatibility_dir.is_dir():
            compatibility_python_files = sorted(
                path.relative_to(package).as_posix()
                for path in compatibility_dir.rglob("*.py")
                if path.is_file()
            )
            for relative in compatibility_python_files:
                violations.append(f"legacy_compatibility_python_present:{relative}")

        for path in sorted(package.rglob("*.py")):
            relative = path.relative_to(package).as_posix()
            if not _is_runtime_critical(relative):
                continue
            scanned += 1
            try:
                text = path.read_text(encoding="utf-8")
                tree = ast.parse(text, filename=str(path))
            except (OSError, UnicodeError, SyntaxError) as error:
                violations.append(f"unscannable_runtime_module:{relative}:{type(error).__name__}")
                continue

            for node in ast.walk(tree):
                if not isinstance(node, (ast.Import, ast.ImportFrom)):
                    continue
                for module in _module_names(node):
                    lowered = module.casefold()
                    if "adapters.eira1" in lowered or lowered == "eira1" or lowered.startswith("eira1."):
                        violations.append(f"legacy_adapter_import:{relative}:{lowered}")
                    if _is_legacy_root_extension_module(lowered):
                        violations.append(f"legacy_root_extension_import:{relative}:{lowered}")
                    if lowered == "main" or lowered.startswith("main."):
                        violations.append(f"legacy_main_import:{relative}:{lowered}")

            if relative != _AUDIT_SELF:
                for value in _string_literals(tree):
                    lowered = value.casefold()
                    if "adapters.eira1" in lowered:
                        violations.append(f"legacy_adapter_dynamic_reference:{relative}")
                    if "extensions." in lowered or lowered.strip() == "extensions":
                        violations.append(f"legacy_root_extension_dynamic_reference:{relative}")
                    if "python3 main.py" in lowered or "python main.py" in lowered:
                        violations.append(f"legacy_main_launch_reference:{relative}")

    launcher = root / "tools" / "install_local_entrypoints.py"
    if not launcher.is_file():
        violations.append("eira2_launcher_installer_missing")
    else:
        try:
            launcher_text = launcher.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as error:
            violations.append(f"eira2_launcher_unreadable:{type(error).__name__}")
        else:
            if "-m eira2.interfaces.terminal" not in launcher_text:
                violations.append("launcher_missing_eira2_terminal_client")
            if "python3 -m eira2 --live" not in launcher_text:
                violations.append("daemon_entrypoint_not_declared")
            if 'exec "${EIRA_PYTHON:-python3}" -m eira2 --live' in launcher_text:
                violations.append("local_launcher_spawns_second_eira2_runtime")
            if 'exec "${EIRA_PYTHON:-python3}" main.py' in launcher_text:
                violations.append("launcher_executes_legacy_main")
            if 'runtime_authority\": \"eira2\"' not in launcher_text:
                violations.append("launcher_eira2_authority_marker_missing")
            if 'eira1_runtime_delegation\": False' not in launcher_text:
                violations.append("launcher_no_delegation_marker_missing")
            if 'single_resident_runtime\": True' not in launcher_text:
                violations.append("launcher_single_resident_runtime_marker_missing")
            if 'local_entrypoints_are_clients\": True' not in launcher_text:
                violations.append("launcher_client_only_marker_missing")

    ok = not violations and scanned > 0
    return {
        "schema": "eira2_native_only_runtime_grade_v1",
        "ok": ok,
        "eira2_native_only_runtime_complete": ok,
        "runtime_modules_scanned": scanned,
        "legacy_evidence_adapter_files": compatibility_python_files,
        "legacy_evidence_adapter_runtime_authority": False,
        "legacy_compatibility_python_files": compatibility_python_files,
        "eira1_runtime_delegation": False if ok else None,
        "legacy_executables_allowed_after_cutover": False if ok else None,
        "single_resident_eira2_runtime": True if ok else None,
        "local_entrypoints_are_clients": True if ok else None,
        "violations": violations,
        "rules": {
            "eira1_adapter_contracts_may_exist_as_evidence_only": False,
            "importable_eira1_compatibility_python_allowed": False,
            "active_runtime_import_of_eira1_adapter_allowed": False,
            "active_runtime_import_of_legacy_root_extensions_allowed": False,
            "dynamic_eira1_adapter_reference_allowed": False,
            "dynamic_legacy_root_extension_reference_allowed": False,
            "legacy_main_runtime_launch_allowed": False,
            "local_entrypoint_may_spawn_second_resident_eira2": False,
            "historical_eira1_evidence_must_be_inert_data_or_docs": True,
            "canonical_live_entrypoint": "python -m eira2 --live",
            "canonical_terminal_client": "python -m eira2.interfaces.terminal",
        },
    }

from __future__ import annotations

import hashlib
import json
import os
import re
from pathlib import Path
from typing import Any, Mapping


_SHA40 = re.compile(r"^[0-9a-f]{40}$", re.I)
_SHA256 = re.compile(r"^[0-9a-f]{64}$", re.I)
_MANIFEST_NAME = "eira2-package-manifest.json"
_EXCLUDED_PARTS = {".git", "var", "__pycache__", ".pytest_cache", ".mypy_cache", "build", "dist",
    "eira_probe",}
_EXCLUDED_SUFFIXES = {".pyc", ".pyo"}
_IMMUTABLE_SUFFIXES = {
    ".py", ".pyi", ".toml", ".json", ".yaml", ".yml", ".ini", ".cfg",
    ".md", ".js", ".mjs", ".cjs", ".html", ".css", ".sh", ".service",
}
_IMMUTABLE_NAMES = {"main.py", "pyproject.toml"}


def _canonical_bytes(value: object) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False).encode("utf-8")


def _included(relative: Path) -> bool:
    if relative.name == _MANIFEST_NAME:
        return False
    if any(part in _EXCLUDED_PARTS for part in relative.parts):
        return False
    if relative.suffix.casefold() in _EXCLUDED_SUFFIXES:
        return False
    return True


def _file_rows(project_root: Path) -> list[dict[str, object]]:
    root = project_root.expanduser().resolve()
    rows: list[dict[str, object]] = []
    for path in sorted(root.rglob("*"), key=lambda item: item.as_posix()):
        relative = path.relative_to(root)
        if not _included(relative):
            continue
        if path.is_symlink():
            raise RuntimeError("eira2_package_symlink_not_allowed:" + relative.as_posix())
        if not path.is_file():
            continue
        data = path.read_bytes()
        rows.append({
            "path": relative.as_posix(),
            "size": len(data),
            "sha256": hashlib.sha256(data).hexdigest(),
        })
    if not rows:
        raise RuntimeError("eira2_package_contains_no_files")
    return rows


def _manifest_rows(payload: Mapping[str, Any]) -> list[dict[str, object]]:
    raw = payload.get("files")
    if not isinstance(raw, list) or not raw:
        raise RuntimeError("eira2_package_file_manifest_invalid")
    rows: list[dict[str, object]] = []
    seen: set[str] = set()
    for row in raw:
        if not isinstance(row, Mapping):
            raise RuntimeError("eira2_package_file_manifest_invalid")
        rel = str(row.get("path") or "").strip()
        size = row.get("size")
        digest = str(row.get("sha256") or "").strip().casefold()
        relative = Path(rel)
        if (
            not rel
            or relative.is_absolute()
            or any(part in {"", ".", ".."} for part in relative.parts)
            or rel in seen
            or not isinstance(size, int)
            or size < 0
            or not _SHA256.fullmatch(digest)
            or not _included(relative)
        ):
            raise RuntimeError("eira2_package_file_manifest_invalid")
        seen.add(rel)
        rows.append({"path": rel, "size": size, "sha256": digest})
    return rows


def _verify_manifest_files(root: Path, rows: list[dict[str, object]]) -> None:
    for row in rows:
        relative = Path(str(row["path"]))
        path = root / relative
        if path.is_symlink() or not path.is_file():
            raise RuntimeError("eira2_package_manifest_file_missing:" + relative.as_posix())
        data = path.read_bytes()
        if len(data) != int(row["size"]):
            raise RuntimeError("eira2_package_manifest_file_size_mismatch:" + relative.as_posix())
        if hashlib.sha256(data).hexdigest() != str(row["sha256"]):
            raise RuntimeError("eira2_package_manifest_file_hash_mismatch:" + relative.as_posix())


def _reject_unsealed_immutable_files(root: Path, sealed: set[str]) -> None:
    for path in sorted(root.rglob("*"), key=lambda item: item.as_posix()):
        relative = path.relative_to(root)
        if not _included(relative) or not path.is_file():
            continue
        rel = relative.as_posix()
        if rel in sealed:
            continue
        if path.is_symlink():
            raise RuntimeError("eira2_package_unsealed_symlink:" + rel)
        if relative.name in _IMMUTABLE_NAMES or relative.suffix.casefold() in _IMMUTABLE_SUFFIXES:
            raise RuntimeError("eira2_package_unsealed_immutable_file:" + rel)


def package_tree_sha256(project_root: Path) -> tuple[str, list[dict[str, object]]]:
    rows = _file_rows(project_root)
    return hashlib.sha256(_canonical_bytes(rows)).hexdigest(), rows


def build_package_manifest(project_root: Path, *, source_commit_sha: str) -> dict[str, object]:
    root = project_root.expanduser().resolve()
    source = str(source_commit_sha or "").strip().casefold()
    if not _SHA40.fullmatch(source):
        raise RuntimeError("eira2_package_source_commit_invalid")
    if not (root / "eira2" / "__main__.py").is_file():
        raise RuntimeError("eira2_package_native_entrypoint_missing")
    tree_sha, rows = package_tree_sha256(root)
    return {
        "schema": "eira2_package_identity_v2",
        "ok": True,
        "runtime_authority": "eira2",
        "source_commit_sha": source,
        "package_tree_sha256": tree_sha,
        "file_count": len(rows),
        "git_metadata_required_at_runtime": False,
        "eira1_runtime_files_required": False,
        "eira1_runtime_delegation": False,
        "legacy_executables_allowed": False,
        "runtime_generated_unsealed_data_allowed": True,
        "unsealed_immutable_files_allowed": False,
        "files": rows,
    }


def write_package_manifest(
    project_root: Path,
    *,
    source_commit_sha: str,
    output: Path | None = None,
) -> dict[str, object]:
    root = project_root.expanduser().resolve()
    manifest = build_package_manifest(root, source_commit_sha=source_commit_sha)
    destination = (output or (root / _MANIFEST_NAME)).expanduser().resolve()
    if destination.parent != root:
        raise RuntimeError("eira2_package_manifest_must_be_project_root")
    temporary = destination.with_name(destination.name + ".new")
    temporary.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.chmod(temporary, 0o600)
    os.replace(temporary, destination)
    return manifest


def verify_package_manifest(
    project_root: Path,
    manifest_path: Path | None = None,
    *,
    expected_source_commit_sha: str = "",
    expected_tree_sha256: str = "",
) -> dict[str, Any]:
    root = project_root.expanduser().resolve()
    path = (manifest_path or (root / _MANIFEST_NAME)).expanduser().resolve()
    if path.parent != root or path.name != _MANIFEST_NAME:
        raise RuntimeError("eira2_package_manifest_location_invalid")
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise RuntimeError("eira2_package_manifest_unreadable") from error
    if not isinstance(payload, Mapping):
        raise RuntimeError("eira2_package_manifest_invalid")

    source = str(payload.get("source_commit_sha") or "").strip().casefold()
    tree = str(payload.get("package_tree_sha256") or "").strip().casefold()
    expected_source = str(expected_source_commit_sha or "").strip().casefold()
    expected_tree = str(expected_tree_sha256 or "").strip().casefold()
    if (
        payload.get("schema") != "eira2_package_identity_v2"
        or payload.get("ok") is not True
        or payload.get("runtime_authority") != "eira2"
        or not _SHA40.fullmatch(source)
        or not _SHA256.fullmatch(tree)
        or payload.get("git_metadata_required_at_runtime") is not False
        or payload.get("eira1_runtime_files_required") is not False
        or payload.get("eira1_runtime_delegation") is not False
        or payload.get("legacy_executables_allowed") is not False
        or payload.get("runtime_generated_unsealed_data_allowed") is not True
        or payload.get("unsealed_immutable_files_allowed") is not False
        or (expected_source and source != expected_source)
        or (expected_tree and tree != expected_tree)
    ):
        raise RuntimeError("eira2_package_manifest_invalid")

    rows = _manifest_rows(payload)
    if int(payload.get("file_count") or -1) != len(rows):
        raise RuntimeError("eira2_package_file_count_mismatch")
    if hashlib.sha256(_canonical_bytes(rows)).hexdigest() != tree:
        raise RuntimeError("eira2_package_manifest_tree_hash_invalid")

    _verify_manifest_files(root, rows)
    _reject_unsealed_immutable_files(root, {str(row["path"]) for row in rows})
    return dict(payload)

from __future__ import annotations

import re
from typing import Any, Mapping


_SHA40 = re.compile(r"^[0-9a-f]{40}$", re.I)
_SHA256 = re.compile(r"^[0-9a-f]{64}$", re.I)


def _row(value: object) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def grade_post_replacement_boot(
    observation: Mapping[str, Any],
    *,
    boot_install: Mapping[str, Any],
    boot_inspection: Mapping[str, Any],
) -> dict[str, object]:
    """Prove EIRA2 owns startup after EIRA1 runtime retirement and a real reboot."""
    violations: list[str] = []

    if boot_install.get("schema") != "eira2_boot_authority_install_v1" or boot_install.get("ok") is not True:
        violations.append("eira2_boot_authority_install_not_verified")
    if boot_install.get("runtime_authority") != "eira2":
        violations.append("boot_install_runtime_authority_not_eira2")
    if boot_install.get("boot_authority_enabled") is not True:
        violations.append("eira2_boot_authority_not_enabled")
    if boot_install.get("legacy_unit_guessed_or_modified") is not False:
        violations.append("boot_install_guessed_or_modified_legacy_unit")
    if boot_install.get("unknown_unit_modified") is not False:
        violations.append("boot_install_modified_unknown_unit")

    target_sha = str(boot_install.get("target_eira2_sha") or "").strip().casefold()
    package_tree = str(boot_install.get("package_tree_sha256") or "").strip().casefold()
    unit_sha = str(boot_install.get("unit_sha256") or "").strip().casefold()
    if not _SHA40.fullmatch(target_sha):
        violations.append("boot_install_target_sha_invalid")
    if not _SHA256.fullmatch(package_tree):
        violations.append("boot_install_package_tree_invalid")
    if not _SHA256.fullmatch(unit_sha):
        violations.append("boot_install_unit_sha_invalid")

    if boot_inspection.get("schema") != "eira2_boot_authority_inspection_v1" or boot_inspection.get("ok") is not True:
        violations.append("post_retirement_boot_inspection_not_verified")
    if boot_inspection.get("read_only") is not True or boot_inspection.get("mutation_performed") is not False:
        violations.append("post_retirement_boot_inspection_not_read_only")
    if int(boot_inspection.get("legacy_boot_unit_count") or -1) != 0:
        violations.append("legacy_boot_unit_still_present")
    if int(boot_inspection.get("exact_native_eira2_boot_unit_count") or -1) != 1:
        violations.append("exact_eira2_boot_unit_count_not_one")
    if str(boot_inspection.get("expected_unit_sha256") or "").strip().casefold() != unit_sha:
        violations.append("boot_inspection_unit_sha_not_install_sha")

    if observation.get("schema") != "eira2_post_replacement_boot_observation_v1":
        violations.append("post_replacement_boot_observation_schema_invalid")
    if int(observation.get("manual_truth_fields") or -1) != 0:
        violations.append("post_replacement_boot_observation_not_collector_derived")
    boot_id = str(observation.get("boot_id") or "").strip()
    prior_boot_id = str(observation.get("prior_boot_id") or "").strip()
    if not boot_id:
        violations.append("post_replacement_boot_id_missing")
    if not prior_boot_id:
        violations.append("pre_reboot_boot_id_missing")
    if boot_id and prior_boot_id and boot_id == prior_boot_id:
        violations.append("actual_reboot_not_proven_by_boot_id")
    if observation.get("reboot_observed") is not True:
        violations.append("reboot_observed_not_true")
    if observation.get("runtime_started_without_manual_launch") is not True:
        violations.append("eira2_autostart_not_proven")
    if observation.get("systemd_unit_enabled") is not True:
        violations.append("post_boot_systemd_unit_not_enabled")
    if observation.get("systemd_owns_live_receipt_pid") is not True:
        violations.append("post_boot_systemd_does_not_own_live_pid")
    try:
        systemd_pid = int(observation.get("systemd_main_pid") or 0)
        live_pid = int(observation.get("live_receipt_pid") or 0)
    except (TypeError, ValueError):
        systemd_pid = live_pid = 0
    if systemd_pid <= 1 or systemd_pid != live_pid:
        violations.append("post_boot_systemd_main_pid_not_live_receipt_pid")

    observed_target = str(observation.get("target_eira2_sha") or "").strip().casefold()
    observed_tree = str(observation.get("package_tree_sha256") or "").strip().casefold()
    if observed_target != target_sha:
        violations.append("post_boot_target_sha_mismatch")
    if observed_tree != package_tree:
        violations.append("post_boot_package_tree_mismatch")
    if observation.get("package_identity_verified") is not True:
        violations.append("post_boot_package_identity_not_verified")
    if observation.get("live_receipt_verified") is not True:
        violations.append("post_boot_live_receipt_not_verified")
    if observation.get("runtime_authority") != "eira2":
        violations.append("post_boot_runtime_authority_not_eira2")
    if observation.get("eira1_runtime_delegation") is not False:
        violations.append("post_boot_eira1_delegation_not_false")
    if observation.get("legacy_executables_allowed") is not False:
        violations.append("post_boot_legacy_execution_not_false")
    if observation.get("required_services_healthy") is not True:
        violations.append("post_boot_required_services_not_healthy")
    if observation.get("doctor_ok") is not True:
        violations.append("post_boot_doctor_not_green")

    easystore = _row(observation.get("easystore"))
    for key in ("ok", "dedicated_mount", "source_matches", "writable"):
        if easystore.get(key) is not True:
            violations.append("post_boot_easystore_" + key + "_not_verified")

    process = _row(observation.get("process_probe"))
    if process.get("schema") != "eira2_post_replacement_process_probe_v1" or process.get("ok") is not True:
        violations.append("post_boot_process_probe_not_verified")
    if process.get("read_only") is not True or process.get("mutation_performed") is not False:
        violations.append("post_boot_process_probe_not_read_only")
    if int(process.get("legacy_process_count") or -1) != 0:
        violations.append("post_boot_legacy_process_present")
    if int(process.get("native_eira2_process_count") or -1) != 1:
        violations.append("post_boot_exact_single_eira2_process_not_present")
    if process.get("eira2_sole_runtime_process_observed") is not True:
        violations.append("post_boot_eira2_not_sole_runtime")

    ok = not violations
    return {
        "schema": "eira2_post_replacement_boot_grade_v2",
        "ok": ok,
        "post_replacement_reboot_verified": ok,
        "eira2_boot_authority_verified": ok,
        "eira1_boot_authority_remaining": False if ok else None,
        "eira1_process_after_reboot": False if ok else None,
        "eira2_autostart_verified": ok,
        "systemd_ownership_verified": ok,
        "target_eira2_sha": target_sha if ok else "",
        "package_tree_sha256": package_tree if ok else "",
        "boot_id": boot_id if ok else "",
        "violations": violations,
        "rules": {
            "collector_derived_observation_required": True,
            "manual_truth_fields_allowed": 0,
            "actual_new_boot_id_required": True,
            "systemd_main_pid_must_equal_live_receipt_pid": True,
            "eira2_autostart_without_manual_launch_required": True,
            "legacy_boot_unit_count_required": 0,
            "exact_native_eira2_boot_unit_count_required": 1,
            "legacy_process_count_required": 0,
            "native_eira2_process_count_required": 1,
            "easystore_required_after_reboot": True,
            "doctor_required_after_reboot": True,
        },
    }

from __future__ import annotations

from typing import Any, Mapping


EXPECTED_RUNTIME_FILES = 12262
EXPECTED_INVENTORY_ENTRIES = 76056
EXPECTED_PRESERVED_ENTRIES = 3244


def _row(value: object) -> Mapping[str, Any]:
    return value if isinstance(value, Mapping) else {}


def grade_replacement_completion(bundle: Mapping[str, Any]) -> dict[str, object]:
    """Final proof that EIRA2 fully replaced installed EIRA1, including reboot authority."""
    violations: list[str] = []

    cutover = _row(bundle.get("final_cutover_grade"))
    if (
        cutover.get("schema") != "eira2_final_cutover_qualification_v4"
        or cutover.get("ok") is not True
        or cutover.get("final_cutover_authorized") is not True
    ):
        violations.append("final_cutover_not_qualified")
    boundary = _row(cutover.get("eira1_replacement_boundary"))
    if boundary.get("eira1_fully_replaced") is not True or boundary.get("preserved_value_only") is not True:
        violations.append("preserve_value_replace_runtime_boundary_not_proven")
    if boundary.get("eira1_install_required_after_replacement") is not False:
        violations.append("replacement_boundary_still_requires_eira1_install")
    if boundary.get("legacy_code_executed_during_inventory") is not False:
        violations.append("replacement_boundary_legacy_inventory_execution_not_false")

    handoff = _row(bundle.get("runtime_handoff"))
    if handoff.get("schema") != "eira2_runtime_handoff_v2" or handoff.get("ok") is not True:
        violations.append("runtime_handoff_not_verified")
    if handoff.get("runtime_authority") != "eira2":
        violations.append("runtime_authority_not_eira2")
    if handoff.get("eira1_runtime_delegation") is not False:
        violations.append("eira1_runtime_delegation_not_false")
    if handoff.get("legacy_executables_allowed") is not False:
        violations.append("legacy_execution_not_disabled")
    if handoff.get("legacy_process_stopped_cleanly") is not True:
        violations.append("legacy_process_not_stopped_cleanly")
    if handoff.get("eira2_required_services_healthy") is not True:
        violations.append("eira2_required_services_not_healthy")

    retirement = _row(bundle.get("legacy_retirement"))
    if retirement.get("schema") != "eira2_legacy_runtime_retirement_v2" or retirement.get("ok") is not True:
        violations.append("legacy_runtime_retirement_not_verified")
    required_retirement_truths = {
        "eira2_live_verified_before_retirement": "eira2_live_not_verified_before_legacy_removal",
        "eira2_package_verified_before_and_after_retirement": "eira2_package_not_verified_before_and_after_retirement",
        "preserved_value_migration_verified_before_retirement": "preserved_value_not_verified_before_legacy_removal",
        "migration_inventory_regraded_before_retirement": "migration_inventory_not_regraded_before_legacy_removal",
        "migration_rehearsal_regraded_before_retirement": "migration_rehearsal_not_regraded_before_legacy_removal",
        "runtime_file_parity_verified_before_retirement": "runtime_parity_not_verified_before_legacy_removal",
        "runtime_parity_regraded_before_retirement": "runtime_parity_not_regraded_before_legacy_removal",
        "retirement_bound_to_migration_ledger": "legacy_retirement_not_bound_to_migration_ledger",
        "retirement_bound_to_migration_rehearsal_receipts": "legacy_retirement_not_bound_to_migration_rehearsal_receipts",
        "retirement_bound_to_runtime_parity_receipts": "legacy_retirement_not_bound_to_runtime_parity_receipts",
        "legacy_installation_footprint_retired": "legacy_installation_footprint_not_retired",
    }
    for key, violation in required_retirement_truths.items():
        if retirement.get(key) is not True:
            violations.append(violation)
    if retirement.get("runtime_authority") != "eira2":
        violations.append("retirement_runtime_authority_not_eira2")
    if retirement.get("arbitrary_retirement_paths_allowed") is not False:
        violations.append("arbitrary_legacy_retirement_paths_not_forbidden")
    if retirement.get("eira1_runtime_delegation") is not False:
        violations.append("retirement_eira1_delegation_not_false")
    if retirement.get("legacy_executables_allowed") is not False:
        violations.append("retirement_legacy_execution_not_disabled")
    if retirement.get("legacy_runtime_required_after_retirement") is not False:
        violations.append("legacy_runtime_still_required")
    if retirement.get("eira1_installed_runtime_required") is not False:
        violations.append("eira1_install_still_required")
    if int(retirement.get("inventory_entries_accounted") or -1) != EXPECTED_INVENTORY_ENTRIES:
        violations.append("legacy_inventory_76056_not_fully_accounted")
    if retirement.get("inventory_76056_accounted") is not True:
        violations.append("legacy_inventory_accounting_not_verified")
    if int(retirement.get("migration_rehearsal_entries_verified") or -1) != EXPECTED_PRESERVED_ENTRIES:
        violations.append("preserved_3244_migration_entries_not_reverified")
    if int(retirement.get("legacy_runtime_files_expected") or -1) != EXPECTED_RUNTIME_FILES:
        violations.append("legacy_runtime_expected_count_mismatch")
    if int(retirement.get("legacy_runtime_files_removed") or -1) != EXPECTED_RUNTIME_FILES:
        violations.append("legacy_runtime_full_removal_not_proven")
    if int(retirement.get("legacy_runtime_files_remaining") or -1) != 0:
        violations.append("legacy_runtime_files_still_present")
    if int(retirement.get("legacy_local_installation_entries_remaining") or -1) != 0:
        violations.append("legacy_installation_entries_still_present")
    migrated_source_files = int(
        retirement.get("preserved_state_or_artifact_sources_retired_after_verified_migration") or 0
    )
    selected_preserved_sources = int(retirement.get("preserved_state_or_artifact_files_selected") or 0)
    if selected_preserved_sources != migrated_source_files:
        violations.append("preserved_source_retirement_not_bound_to_verified_migration")
    if retirement.get("external_dependencies_removed") is not False:
        violations.append("external_dependencies_were_selected_for_retirement")
    if retirement.get("secret_values_logged_in_receipt") is not False:
        violations.append("secret_values_logged_during_retirement")
    if int(retirement.get("retained_archive_executable_files") or -1) != 0:
        violations.append("retained_legacy_archive_contains_executable_files")
    if retirement.get("evidence_manifest_contains_executable_bytes") is not False:
        violations.append("retirement_evidence_contains_executable_bytes")

    post = _row(bundle.get("post_replacement_process_probe"))
    if post.get("schema") != "eira2_post_replacement_process_probe_v1" or post.get("ok") is not True:
        violations.append("post_replacement_process_probe_not_verified")
    if post.get("read_only") is not True or post.get("mutation_performed") is not False:
        violations.append("post_replacement_probe_not_read_only")
    if int(post.get("legacy_process_count") or -1) != 0:
        violations.append("legacy_process_still_observed")
    if int(post.get("native_eira2_process_count") or -1) != 1:
        violations.append("exact_single_eira2_process_not_observed")
    if post.get("eira2_sole_runtime_process_observed") is not True:
        violations.append("eira2_not_proven_sole_runtime_process")
    if post.get("eira1_process_observed") is not False:
        violations.append("eira1_process_observed_after_retirement")

    reboot = _row(bundle.get("post_replacement_boot"))
    if reboot.get("schema") != "eira2_post_replacement_boot_grade_v2" or reboot.get("ok") is not True:
        violations.append("post_replacement_reboot_not_verified")
    if reboot.get("post_replacement_reboot_verified") is not True:
        violations.append("actual_post_replacement_reboot_not_proven")
    if reboot.get("eira2_boot_authority_verified") is not True:
        violations.append("eira2_boot_authority_not_verified")
    if reboot.get("systemd_ownership_verified") is not True:
        violations.append("eira2_systemd_ownership_not_verified")
    if reboot.get("eira1_boot_authority_remaining") is not False:
        violations.append("eira1_boot_authority_remaining_not_false")
    if reboot.get("eira1_process_after_reboot") is not False:
        violations.append("eira1_process_after_reboot_not_false")
    if reboot.get("eira2_autostart_verified") is not True:
        violations.append("eira2_autostart_not_verified")

    target = str(handoff.get("target_eira2_sha") or "").strip().casefold()
    if target and str(retirement.get("target_eira2_sha") or "").strip().casefold() != target:
        violations.append("retirement_target_sha_not_handoff_target")
    if target and str(reboot.get("target_eira2_sha") or "").strip().casefold() != target:
        violations.append("post_reboot_target_sha_not_handoff_target")
    package_tree = str(handoff.get("package_tree_sha256") or "").strip().casefold()
    if package_tree and str(retirement.get("package_tree_sha256") or "").strip().casefold() != package_tree:
        violations.append("retirement_package_tree_not_handoff_package")
    if package_tree and str(reboot.get("package_tree_sha256") or "").strip().casefold() != package_tree:
        violations.append("post_reboot_package_tree_not_handoff_package")

    ok = not violations
    return {
        "schema": "eira2_full_replacement_completion_v5",
        "ok": ok,
        "eira2_full_replacement_complete": ok,
        "eira2_runtime_authority_only": ok,
        "eira1_runtime_installed": False if ok else None,
        "eira1_installation_footprint_remaining": 0 if ok else None,
        "eira1_runtime_required": False if ok else None,
        "eira1_runtime_delegation": False if ok else None,
        "eira1_process_running": False if ok else None,
        "eira1_boot_authority_remaining": False if ok else None,
        "legacy_executables_active": False if ok else None,
        "legacy_runtime_files_remaining": 0 if ok else None,
        "eira2_autostart_after_reboot": True if ok else None,
        "preserved_value_migrated_into_eira2": True if ok else None,
        "inventory_76056_accounted": True if ok else None,
        "target_eira2_sha": target if ok else "",
        "package_tree_sha256": package_tree if ok else "",
        "violations": violations,
        "rules": {
            "eira2_live_before_legacy_removal": True,
            "eira2_package_verified_before_and_after_legacy_removal": True,
            "preserved_value_migrated_before_legacy_source_removal": True,
            "migration_inventory_regraded_before_legacy_removal": True,
            "migration_rehearsal_regraded_before_legacy_source_removal": True,
            "runtime_parity_regraded_before_legacy_removal": True,
            "retirement_must_be_bound_to_migration_ledger": True,
            "retirement_must_be_bound_to_raw_migration_receipts": True,
            "retirement_must_be_bound_to_runtime_parity_receipts": True,
            "arbitrary_retirement_paths_allowed": False,
            "legacy_inventory_entries_required_accounted": EXPECTED_INVENTORY_ENTRIES,
            "legacy_runtime_files_required_removed": EXPECTED_RUNTIME_FILES,
            "preserved_entries_required_reverified": EXPECTED_PRESERVED_ENTRIES,
            "preserved_sources_may_be_removed_only_after_verified_migration": True,
            "external_dependencies_may_be_removed": False,
            "legacy_installation_footprint_must_be_zero": True,
            "post_retirement_process_probe_required": True,
