from __future__ import annotations

import hashlib
import os
from pathlib import Path
from typing import Any


def _read_bytes(path: Path) -> bytes:
    try:
        return path.read_bytes()
    except OSError:
        return b""


def _read_text(path: Path) -> str:
    try:
        return path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""


def _process_row(proc: Path) -> dict[str, Any] | None:
    try:
        pid = int(proc.name)
    except ValueError:
        return None
    raw = _read_bytes(proc / "cmdline")
    if not raw:
        return None
    argv = [part.decode("utf-8", errors="replace") for part in raw.split(b"\0") if part]
    if not argv:
        return None
    try:
        uid = (proc / "status").stat().st_uid
    except OSError:
        uid = -1
    try:
        cwd = str((proc / "cwd").resolve())
    except OSError:
        cwd = ""
    stat_text = _read_text(proc / "stat")
    start_ticks = ""
    if stat_text:
        close = stat_text.rfind(")")
        tail = stat_text[close + 2 :].split() if close >= 0 else []
        if len(tail) >= 20:
            start_ticks = tail[19]
    return {
        "pid": pid,
        "uid": uid,
        "argv": argv,
        "cwd": cwd,
        "start_ticks": start_ticks,
        "cmdline_sha256": hashlib.sha256(raw).hexdigest(),
    }


def _under(path_text: str, root: Path) -> bool:
    if not path_text:
        return False
    try:
        path = Path(path_text).expanduser().resolve()
        path.relative_to(root)
        return True
    except (OSError, RuntimeError, ValueError):
        return False


def _python_command(argv: list[str]) -> bool:
    if not argv:
        return False
    executable = Path(str(argv[0])).name.casefold()
    return executable.startswith("python") or executable in {"pypy", "pypy3"}


def _legacy_python_surface(row: dict[str, Any], live: Path, eira2: Path) -> bool:
    argv = [str(value) for value in row.get("argv") or []]
    cwd_text = str(row.get("cwd") or "")
    cwd_in_live = _under(cwd_text, live)
    cwd_in_eira2 = _under(cwd_text, eira2)

    for raw in argv[1:]:
        if not raw or raw.startswith("-"):
            continue
        candidate = Path(raw).expanduser()
        if candidate.is_absolute() and _under(str(candidate), live) and not _under(str(candidate), eira2):
            return True
        if cwd_in_live and not cwd_in_eira2 and raw.endswith((".py", ".pyw")):
            return True

    if _python_command(argv) and cwd_in_live and not cwd_in_eira2:
        joined = " ".join(argv[1:])
        if "-m eira2" not in joined:
            if any(token in argv[1:] for token in ("-m", "-c")) or len(argv) > 1:
                return True
    return False


def _classify_processes(
    live_root: Path,
    *,
    proc_root: Path,
    current_pid: int | None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    live = live_root.expanduser().resolve()
    eira2_path = (live / "eira2").resolve()
    legacy_main = str(live / "main.py")
    eira2_root = str(eira2_path)
    own_pid = int(current_pid if current_pid is not None else os.getpid())
    legacy: list[dict[str, Any]] = []
    native: list[dict[str, Any]] = []

    try:
        entries = sorted(proc_root.iterdir(), key=lambda p: p.name)
    except OSError as error:
        raise RuntimeError("runtime_handoff_proc_unavailable") from error

    for proc in entries:
        if not proc.name.isdigit() or int(proc.name) == own_pid:
            continue
        row = _process_row(proc)
        if row is None:
            continue
        joined = "\0".join(str(v) for v in row["argv"])
        cwd = str(row.get("cwd") or "")
        is_native = (
            "-m\0eira2\0--live" in joined
            or ("-m eira2 --live" in joined.replace("\0", " "))
            or (cwd == eira2_root and "eira2" in joined and "--live" in joined)
        )
        is_legacy = not is_native and (
            legacy_main in joined
            or (cwd == str(live) and any(str(arg).endswith("main.py") for arg in row["argv"]))
            or _legacy_python_surface(row, live, eira2_path)
        )
        if is_legacy:
            legacy.append(row)
        if is_native:
            native.append(row)
    return legacy, native


def probe_runtime_handoff(
    live_root: Path,
    *,
    proc_root: Path = Path("/proc"),
    current_pid: int | None = None,
) -> dict[str, Any]:
    """Read-only discovery of current EIRA1/EIRA2 process authority before handoff."""
    live = live_root.expanduser().resolve()
    legacy, native = _classify_processes(live, proc_root=proc_root, current_pid=current_pid)
    exact_single_legacy = len(legacy) == 1
    no_native = len(native) == 0
    ready = exact_single_legacy and no_native
    return {
        "schema": "eira2_runtime_handoff_probe_v1",
        "ok": True,
        "read_only": True,
        "live_root": str(live),
        "legacy_process_count": len(legacy),
        "native_eira2_process_count": len(native),
        "legacy_processes": legacy,
        "native_eira2_processes": native,
        "exact_single_legacy_authority_observed": exact_single_legacy,
        "no_native_eira2_process_observed": no_native,
        "safe_automatic_handoff_identity_available": ready,
        "mutation_performed": False,
        "rules": {
            "no_guessing_systemd_unit": True,
            "process_identity_bound_by_pid_uid_cmdline_hash_start_ticks": True,
            "multiple_legacy_processes_block_automatic_handoff": True,
            "existing_native_eira2_process_blocks_duplicate_start": True,
            "legacy_python_children_and_extension_processes_detected": True,
            "eira2_subtree_excluded_from_legacy_process_detection": True,
        },
    }


def probe_post_replacement(
    live_root: Path,
    *,
    proc_root: Path = Path("/proc"),
    current_pid: int | None = None,
) -> dict[str, Any]:
    """Read-only proof that EIRA2 is the sole observed EIRA runtime after retirement."""
    live = live_root.expanduser().resolve()
    legacy, native = _classify_processes(live, proc_root=proc_root, current_pid=current_pid)
    sole_native = len(legacy) == 0 and len(native) == 1
    return {
        "schema": "eira2_post_replacement_process_probe_v1",
        "ok": sole_native,
        "read_only": True,
        "live_root": str(live),
        "legacy_process_count": len(legacy),
        "native_eira2_process_count": len(native),
        "legacy_processes": legacy,
        "native_eira2_processes": native,
        "eira2_sole_runtime_process_observed": sole_native,
        "eira1_process_observed": bool(legacy),
        "mutation_performed": False,
        "rules": {
            "legacy_process_count_required": 0,
            "native_eira2_process_count_required": 1,
            "post_replacement_probe_read_only": True,
            "legacy_python_children_and_extension_processes_detected": True,
        },
    }

from __future__ import annotations

import ast
import json
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from ..contracts import ServiceState
from ..registry.extensions import ExtensionManagerService
from ..registry.manifests import discover


_EXCLUDED_DIRS = {"__pycache__", ".pytest_cache", ".git", "var"}


@dataclass(slots=True)
class SystemAuditReport:
    ok: bool = False
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    checks: dict[str, Any] = field(default_factory=dict)

    def as_dict(self) -> dict[str, Any]:
        return {
            "schema": "eira2_system_audit_v2",
            "ok": self.ok,
            "errors": list(self.errors),
            "warnings": list(self.warnings),
            "checks": dict(self.checks),
        }


def _python_files(project_root: Path) -> list[Path]:
    package = project_root / "eira2"
    rows: list[Path] = []
    for path in package.rglob("*.py"):
        rel = path.relative_to(project_root)
        if any(part in _EXCLUDED_DIRS for part in rel.parts):
            continue
        rows.append(path)
    return sorted(rows)


def _module_for(project_root: Path, path: Path) -> str:
    rel = path.relative_to(project_root).with_suffix("")
    parts = list(rel.parts)
    if parts[-1] == "__init__":
        parts.pop()
    return ".".join(parts)


def _imports(path: Path) -> tuple[str, ...]:
    source = path.read_text(encoding="utf-8", errors="strict")
    tree = ast.parse(source, filename=str(path))
    found: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                found.add(alias.name)
        elif isinstance(node, ast.ImportFrom) and node.module:
            found.add(node.module)
    return tuple(sorted(found))


def _service_spec_names(path: Path) -> set[str]:
    source = path.read_text(encoding="utf-8", errors="strict")
    tree = ast.parse(source, filename=str(path))
    service_names: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        func_name = func.id if isinstance(func, ast.Name) else func.attr if isinstance(func, ast.Attribute) else ""
        if func_name != "ServiceSpec" or not node.args:
            continue
        first = node.args[0]
        if isinstance(first, ast.Constant) and isinstance(first.value, str):
            service_names.add(first.value)
    return service_names


def static_whole_tree_audit(project_root: Path) -> SystemAuditReport:
    root = project_root.expanduser().resolve()
    report = SystemAuditReport()
    errors = report.errors
    warnings = report.warnings

    static_manifests = discover(root / "manifests")
    static_by_name = {manifest.name: manifest for manifest in static_manifests}
    static_names = set(static_by_name)
    if len(static_names) != len(static_manifests):
        errors.append("duplicate_static_service_name")

    manager = ExtensionManagerService(root)
    dynamic_manifests = manager.discover()
    dynamic_by_name = {manifest.name: manifest for manifest in dynamic_manifests}
    dynamic_names = set(dynamic_by_name)
    if static_names & dynamic_names:
        errors.append("static_dynamic_service_name_collision:" + ",".join(sorted(static_names & dynamic_names)))

    all_manifests = {**static_by_name, **dynamic_by_name}
    total_names = set(all_manifests)
    manifested_modules = {manifest.module for manifest in all_manifests.values()}

    package_files = _python_files(root)
    modules = {_module_for(root, path): path for path in package_files}

    # A ServiceSpec is a service-contract claim, but canonical authority is granted
    # only by exactly one manifest name. Base classes may share/inherit that contract;
    # runtime tests separately prove every claimant belongs to the canonical owner's
    # inheritance family. A spec whose name has no manifest is always an orphan.
    claims: dict[str, set[str]] = {}
    for module, path in modules.items():
        for name in _service_spec_names(path):
            claims.setdefault(name, set()).add(module)

    orphan_claims: list[tuple[str, str]] = []
    helper_claims: list[tuple[str, str]] = []
    for name, claim_modules in sorted(claims.items()):
        manifest = all_manifests.get(name)
        if manifest is None:
            for module in sorted(claim_modules):
                orphan_claims.append((name, module))
            continue
        for module in sorted(claim_modules):
            if module != manifest.module:
                helper_claims.append((name, module))

    if orphan_claims:
        errors.extend(
            f"orphan_service_module:{name}:{module}"
            for name, module in orphan_claims
        )

    # Every canonical manifest module must exist in the package. Factory/symbol and
    # runtime spec parity are enforced by FullDoctor and Eira2Runtime construction.
    for name, manifest in sorted(all_manifests.items()):
        if manifest.module not in modules:
            errors.append(f"canonical_manifest_module_missing:{name}:{manifest.module}")

    # Superseded/versioned extension implementations may remain only if explicitly
    # referenced by a manifest. This prevents old executable authorities from quietly
    # coexisting in the live package namespace.
    extension_root = root / "eira2" / "extensions"
    dynamic_modules = {manifest.module for manifest in dynamic_manifests}
    versioned_orphans: list[str] = []
    for path in sorted(extension_root.glob("*.py")):
        if path.name == "__init__.py":
            continue
        module = _module_for(root, path)
        stem = path.stem
        if any(token in stem.casefold() for token in ("_v2", "_v3", "_v4", "_old", "_legacy", "_bak")):
            if module not in dynamic_modules:
                versioned_orphans.append(module)
    for module in sorted(dynamic_modules):
        stem = module.rsplit(".", 1)[-1]
        for suffix in ("_v2", "_v3", "_v4"):
            if stem.endswith(suffix):
                predecessor = module[: -len(suffix)]
                if predecessor in modules and predecessor not in dynamic_modules:
                    versioned_orphans.append(predecessor)
    if versioned_orphans:
        errors.extend(f"superseded_executable_extension:{module}" for module in sorted(set(versioned_orphans)))

    # Every manifest dependency must resolve in the total service namespace.
    for manifest in all_manifests.values():
        for dependency in manifest.dependencies:
            if dependency not in total_names:
                errors.append(f"unresolved_manifest_dependency:{manifest.name}:{dependency}")

    # Sanity-check explicit absolute EIRA2 imports. The full import-every-module test
    # covers relative imports and import-time behavior as a separate executable gate.
    missing_local_imports: set[str] = set()
    for module, path in modules.items():
        try:
            imports = _imports(path)
        except Exception as error:
            errors.append(f"import_parse_failed:{module}:{type(error).__name__}:{error}")
            continue
        for imported in imports:
            if not imported.startswith("eira2"):
                continue
            candidate = imported
            while candidate and candidate not in modules:
                if "." not in candidate:
                    break
                candidate = candidate.rsplit(".", 1)[0]
            if candidate == "eira2" or candidate in modules:
                continue
            if imported not in modules:
                missing_local_imports.add(f"{module}->{imported}")
    if missing_local_imports:
        errors.extend(f"missing_local_import:{item}" for item in sorted(missing_local_imports))

    if helper_claims:
        warnings.append(
            "inherited_or_base_service_contracts_present:" + str(len(helper_claims))
        )

    report.checks.update({
        "python_package_files": len(package_files),
        "static_service_manifests": len(static_manifests),
        "dynamic_extension_manifests": len(dynamic_manifests),
        "manifest_backed_modules": len(manifested_modules),
        "service_contract_names": len(claims),
        "base_or_inherited_service_claims": len(helper_claims),
        "orphan_service_modules": len(orphan_claims),
        "superseded_executable_extensions": len(set(versioned_orphans)),
        "missing_local_imports": len(missing_local_imports),
    })
    report.ok = not errors
    return report


async def runtime_gauntlet(runtime: Any) -> SystemAuditReport:
    report = SystemAuditReport()
    errors = report.errors
    await runtime.start()
    try:
        status = await runtime.supervisor.status()
        required_failures = [
            name for name, health in status.items()
            if getattr(runtime.supervisor.get_service(name), "spec").required
            and health.state not in {ServiceState.READY, ServiceState.DEGRADED}
        ]
        if required_failures:
            errors.append("required_runtime_services_unhealthy:" + ",".join(sorted(required_failures)))

        extension_snapshot = runtime.extensions.snapshot()
        if not extension_snapshot.get("ok"):
            errors.append("dynamic_extension_reconcile_failed")

        registry = runtime.registry.snapshot()
        nodes = {str(row.get("name")) for row in registry.get("nodes", []) if isinstance(row, dict)}
        bridges = [row for row in registry.get("bridges", []) if isinstance(row, dict)]
        for name in status:
            if name not in nodes:
                errors.append(f"runtime_service_missing_registry_node:{name}")
        for bridge in bridges:
            source = str(bridge.get("source") or "")
            target = str(bridge.get("target") or "")
            if source not in nodes or target not in nodes:
                errors.append(f"runtime_orphan_bridge:{source}:{target}")
            if bridge.get("kind") == "service_dependency" and bridge.get("conductive") is not True:
                errors.append(f"runtime_dependency_bridge_not_conductive:{source}:{target}")

        first = await runtime.process("Audit continuity seed: blue comet")
        second = await runtime.process("Continue what I just said about that marker")
        if not first.verified or not second.verified:
            errors.append("conversation_transaction_not_verified")
        history = runtime.history.recent()
        if len(history) < 2:
            errors.append("accepted_history_not_committed")

        doctor = runtime.evaluate_self()
        if not doctor.get("ok"):
            errors.append("post_runtime_doctor_failed")

        report.checks.update({
            "runtime_services": len(status),
            "registry_nodes": len(nodes),
            "registry_bridges": len(bridges),
            "dynamic_extensions_attached": len(extension_snapshot.get("attached", [])),
            "accepted_history_turns": len(history),
        })
    finally:
        await runtime.stop()

    stopped = await runtime.supervisor.status()
    still_live = [
        name for name, health in stopped.items()
        if health.state not in {ServiceState.STOPPED, ServiceState.FAILED}
    ]
    if still_live:
        errors.append("reverse_shutdown_incomplete:" + ",".join(sorted(still_live)))
    report.checks["reverse_shutdown_complete"] = not still_live
    report.ok = not errors
    return report


def main() -> int:
    import argparse
    parser = argparse.ArgumentParser(description="EIRA 2.0 whole-tree structural audit")
    parser.add_argument("--project-root", type=Path, default=Path.cwd())
    args = parser.parse_args()
    report = static_whole_tree_audit(args.project_root)
    print(json.dumps(report.as_dict(), indent=2, sort_keys=True))
    return 0 if report.ok else 1


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import hashlib
import json
import os
import shutil
from pathlib import Path
from typing import Any, Mapping


_RECEIPT_SCHEMA = "eira2_native_voice_asset_takeover_v1"
_DEFAULT_MODEL_NAME = "en_US-hfc_female-medium.onnx"


def _sha256(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for block in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(block)
    return value.hexdigest()


def _atomic_json(path: Path, payload: Mapping[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name + ".new")
    temporary.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    os.chmod(temporary, 0o600)
    os.replace(temporary, path)


def _reject_symlinked_relative_path(root: Path, path: Path, code: str) -> None:
    """Reject symlink components below an already-resolved EIRA2 runtime root."""
    try:
        relative = path.relative_to(root)
    except ValueError as error:
        raise RuntimeError(code) from error
    cursor = root
    for part in relative.parts:
        cursor = cursor / part
        if cursor.is_symlink():
            raise RuntimeError(code)


def canonical_native_voice_model(runtime_root: Path) -> Path:
    root = runtime_root.expanduser().resolve()
    return root / "var" / "voice" / "voices" / _DEFAULT_MODEL_NAME


def canonical_native_voice_config(runtime_root: Path) -> Path:
    return Path(str(canonical_native_voice_model(runtime_root)) + ".json")


def native_voice_asset_receipt_path(runtime_root: Path) -> Path:
    root = runtime_root.expanduser().resolve()
    return root / "var" / "voice" / "voice-asset-takeover.json"


def _source_config_for(source: Path, source_config: Path | None) -> Path:
    selected = source_config.expanduser() if source_config is not None else Path(str(source) + ".json")
    if selected.is_symlink():
        raise RuntimeError("voice_asset_config_source_symlink_forbidden")
    return selected.resolve()


def _validate_source(path: Path, *, missing_code: str, empty_code: str) -> tuple[str, int]:
    if not path.is_file():
        raise RuntimeError(missing_code)
    size = path.stat().st_size
    if size <= 0:
        raise RuntimeError(empty_code)
    return _sha256(path), size


def _copy_hash_identical(source: Path, destination: Path, expected_sha: str, *, prefix: str) -> None:
    if destination.exists():
        if not destination.is_file():
            raise RuntimeError(prefix + "_destination_not_regular_file")
        if _sha256(destination) != expected_sha:
            raise RuntimeError(prefix + "_destination_conflict")
        os.chmod(destination, destination.stat().st_mode & ~0o111)
        return

    temporary = destination.with_name(destination.name + ".new")
    if temporary.exists() or temporary.is_symlink():
        temporary.unlink()
    try:
        shutil.copyfile(source, temporary)
        os.chmod(temporary, 0o600)
        if _sha256(temporary) != expected_sha:
            raise RuntimeError(prefix + "_staged_hash_mismatch")
        os.replace(temporary, destination)
    finally:
        if temporary.exists() or temporary.is_symlink():
            temporary.unlink()

    os.chmod(destination, destination.stat().st_mode & ~0o111)


def provision_native_voice_asset(
    *,
    runtime_root: Path,
    source: Path,
    source_config: Path | None = None,
    receipt_path: Path | None = None,
) -> dict[str, Any]:
    """Copy a complete Piper voice pair into EIRA2-owned runtime data with hash proof.

    PiperVoice.load(model.onnx) resolves its configuration from model.onnx.json.
    The takeover therefore treats those two files as one required runtime asset set.
    No EIRA1 code is imported or executed, and both source files remain unchanged.
    """
    root_input = runtime_root.expanduser()
    source_input = source.expanduser()
    receipt_input = receipt_path.expanduser() if receipt_path is not None else None

    if root_input.is_symlink():
        raise RuntimeError("voice_asset_runtime_root_symlink_forbidden")
    if source_input.is_symlink():
        raise RuntimeError("voice_asset_source_symlink_forbidden")
    if receipt_input is not None and receipt_input.is_symlink():
        raise RuntimeError("voice_asset_receipt_symlink_forbidden")

    root = root_input.resolve()
    source = source_input.resolve()
    config_source = _source_config_for(source_input, source_config)
    destination = canonical_native_voice_model(root)
    config_destination = canonical_native_voice_config(root)
    receipt_file = (
        receipt_input.resolve()
        if receipt_input is not None
        else native_voice_asset_receipt_path(root)
    )

    if not root.is_dir():
        raise RuntimeError("voice_asset_runtime_root_missing")
    if source == destination or root in source.parents:
        raise RuntimeError("voice_asset_source_must_be_external_to_eira2")
    if config_source == config_destination or root in config_source.parents:
        raise RuntimeError("voice_asset_config_source_must_be_external_to_eira2")
    if receipt_file != native_voice_asset_receipt_path(root):
        if root != receipt_file and root not in receipt_file.parents:
            raise RuntimeError("voice_asset_receipt_must_be_under_eira2")

    _reject_symlinked_relative_path(root, destination, "voice_asset_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, config_destination, "voice_asset_config_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, receipt_file, "voice_asset_receipt_symlink_forbidden")

    source_sha_before, source_size = _validate_source(
        source,
        missing_code="voice_asset_source_must_be_regular_file",
        empty_code="voice_asset_source_empty",
    )
    config_sha_before, config_size = _validate_source(
        config_source,
        missing_code="voice_asset_config_source_must_be_regular_file",
        empty_code="voice_asset_config_source_empty",
    )

    destination.parent.mkdir(parents=True, exist_ok=True)
    _reject_symlinked_relative_path(root, destination, "voice_asset_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, config_destination, "voice_asset_config_destination_symlink_forbidden")

    # Validate any existing pair before writing either member, then stage/copy each.
    if destination.exists() and (
        not destination.is_file() or _sha256(destination) != source_sha_before
    ):
        raise RuntimeError("voice_asset_destination_conflict")
    if config_destination.exists() and (
        not config_destination.is_file() or _sha256(config_destination) != config_sha_before
    ):
        raise RuntimeError("voice_asset_config_destination_conflict")

    _copy_hash_identical(
        source,
        destination,
        source_sha_before,
        prefix="voice_asset",
    )
    _copy_hash_identical(
        config_source,
        config_destination,
        config_sha_before,
        prefix="voice_asset_config",
    )

    destination_sha = _sha256(destination)
    config_destination_sha = _sha256(config_destination)
    source_sha_after = _sha256(source)
    config_sha_after = _sha256(config_source)
    if source_sha_after != source_sha_before:
        raise RuntimeError("voice_asset_source_changed_during_takeover")
    if config_sha_after != config_sha_before:
        raise RuntimeError("voice_asset_config_source_changed_during_takeover")
    if destination_sha != source_sha_before:
        raise RuntimeError("voice_asset_destination_hash_mismatch")
    if config_destination_sha != config_sha_before:
        raise RuntimeError("voice_asset_config_destination_hash_mismatch")
    if destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_destination_executable")
    if config_destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_config_destination_executable")

    receipt: dict[str, Any] = {
        "schema": _RECEIPT_SCHEMA,
        "ok": True,
        "source_path": str(source),
        "source_size": source_size,
        "source_sha256": source_sha_before,
        "source_unchanged": True,
        "config_source_path": str(config_source),
        "config_source_size": config_size,
        "config_source_sha256": config_sha_before,
        "config_source_unchanged": True,
        "destination_path": str(destination),
        "destination_sha256": destination_sha,
        "destination_under_eira2": True,
        "destination_executable": False,
        "config_destination_path": str(config_destination),
        "config_destination_sha256": config_destination_sha,
        "config_destination_under_eira2": True,
        "config_destination_executable": False,
        "complete_piper_voice_pair": True,
        "eira1_code_imported": False,
        "eira1_runtime_delegation": False,
        "model_role": "eira2_owned_runtime_dependency",
    }
    _atomic_json(receipt_file, receipt)
    return receipt


def verify_native_voice_asset(
    *,
    runtime_root: Path,
    receipt_path: Path | None = None,
) -> dict[str, Any]:
    """Fail closed unless the complete canonical EIRA2 Piper voice pair is attested."""
    root_input = runtime_root.expanduser()
    receipt_input = receipt_path.expanduser() if receipt_path is not None else None
    if root_input.is_symlink():
        raise RuntimeError("voice_asset_runtime_root_symlink_forbidden")
    if receipt_input is not None and receipt_input.is_symlink():
        raise RuntimeError("voice_asset_receipt_symlink_forbidden")

    root = root_input.resolve()
    destination = canonical_native_voice_model(root)
    config_destination = canonical_native_voice_config(root)
    receipt_file = (
        receipt_input.resolve()
        if receipt_input is not None
        else native_voice_asset_receipt_path(root)
    )
    if receipt_file != native_voice_asset_receipt_path(root):
        if root != receipt_file and root not in receipt_file.parents:
            raise RuntimeError("voice_asset_receipt_must_be_under_eira2")
    _reject_symlinked_relative_path(root, destination, "voice_asset_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, config_destination, "voice_asset_config_destination_symlink_forbidden")
    _reject_symlinked_relative_path(root, receipt_file, "voice_asset_receipt_symlink_forbidden")

    try:
        payload = json.loads(receipt_file.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise RuntimeError("voice_asset_takeover_receipt_unreadable") from error
    if not isinstance(payload, dict):
        raise RuntimeError("voice_asset_takeover_receipt_invalid")
    if payload.get("schema") != _RECEIPT_SCHEMA or payload.get("ok") is not True:
        raise RuntimeError("voice_asset_takeover_receipt_not_qualified")
    if payload.get("complete_piper_voice_pair") is not True:
        raise RuntimeError("voice_asset_complete_piper_pair_not_verified")
    if payload.get("destination_under_eira2") is not True:
        raise RuntimeError("voice_asset_destination_ownership_not_verified")
    if payload.get("config_destination_under_eira2") is not True:
        raise RuntimeError("voice_asset_config_destination_ownership_not_verified")
    if payload.get("destination_executable") is not False:
        raise RuntimeError("voice_asset_destination_execute_policy_invalid")
    if payload.get("config_destination_executable") is not False:
        raise RuntimeError("voice_asset_config_destination_execute_policy_invalid")
    if payload.get("eira1_code_imported") is not False or payload.get("eira1_runtime_delegation") is not False:
        raise RuntimeError("voice_asset_takeover_contains_eira1_runtime_dependency")
    if payload.get("source_unchanged") is not True or payload.get("config_source_unchanged") is not True:
        raise RuntimeError("voice_asset_takeover_source_preservation_not_verified")

    recorded_destination_raw = Path(str(payload.get("destination_path") or "")).expanduser()
    recorded_config_raw = Path(str(payload.get("config_destination_path") or "")).expanduser()
    if recorded_destination_raw.is_symlink():
        raise RuntimeError("voice_asset_takeover_destination_not_canonical")
    if recorded_config_raw.is_symlink():
        raise RuntimeError("voice_asset_takeover_config_destination_not_canonical")
    if recorded_destination_raw.resolve() != destination:
        raise RuntimeError("voice_asset_takeover_destination_not_canonical")
    if recorded_config_raw.resolve() != config_destination:
        raise RuntimeError("voice_asset_takeover_config_destination_not_canonical")

    if not destination.is_file():
        raise RuntimeError("voice_asset_native_model_missing")
    if not config_destination.is_file():
        raise RuntimeError("voice_asset_native_config_missing")
    if destination.stat().st_size <= 0:
        raise RuntimeError("voice_asset_native_model_empty")
    if config_destination.stat().st_size <= 0:
        raise RuntimeError("voice_asset_native_config_empty")
    if destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_native_model_executable")
    if config_destination.stat().st_mode & 0o111:
        raise RuntimeError("voice_asset_native_config_executable")

    recorded_sha = str(payload.get("destination_sha256") or "").strip().casefold()
    recorded_config_sha = str(payload.get("config_destination_sha256") or "").strip().casefold()
    actual_sha = _sha256(destination)
    actual_config_sha = _sha256(config_destination)
    if len(recorded_sha) != 64 or actual_sha != recorded_sha:
        raise RuntimeError("voice_asset_native_model_hash_mismatch")
    if len(recorded_config_sha) != 64 or actual_config_sha != recorded_config_sha:
        raise RuntimeError("voice_asset_native_config_hash_mismatch")

    verified = dict(payload)
    verified["verified_now"] = True
    verified["destination_sha256"] = actual_sha
    verified["config_destination_sha256"] = actual_config_sha
    return verified

from __future__ import annotations

import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any


# EIRA 2.0 is a full replacement. Legacy adapters may exist temporarily while
# migration/parity work is in progress, but they are never sufficient evidence
# for final cutover. Final runtime authority must be native to EIRA2.
CUTOVER_STATES = {"native"}
MIGRATION_ONLY_STATES = {"parity_verified_adapter"}
KNOWN_STATES = CUTOVER_STATES | MIGRATION_ONLY_STATES | {"partial", "missing"}
LIVE_EIRA_EXTRA_CATALOGS = {
    "catalog.source_active_extension_candidates",
    "catalog.neural_inventory_76056",
    "catalog.neural_conductive_fiber_evidence",
    "catalog.neural_walkable_ar_device_verification",
    "catalog.fraternal_twin_capability_parity",
    "catalog.unique_eira_identity_continuity",
    "catalog.experiential_learning_validation",
    "catalog.capability_growth_beyond_legacy",
    "catalog.jellyfish_immune_device_enforcement",
}


@dataclass(frozen=True, slots=True)
class PreservationReport:
    total: int
    native: int
    adapters: int
    partial: int
    missing: int
    blockers: tuple[str, ...]
    dynamic_catalogs: tuple[str, ...]

    @property
    def cutover_ready(self) -> bool:
        return not self.blockers and not self.dynamic_catalogs


def default_contract_path() -> Path:
    return Path(__file__).resolve().parents[1] / "preservation_contract.json"


def load_contract(path: Path | None = None) -> dict[str, Any]:
    target = (path or default_contract_path()).resolve()
    value = json.loads(target.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise TypeError("preservation_contract_not_object")
    return value


def validate_contract(contract: dict[str, Any]) -> list[str]:
    errors: list[str] = []
    if contract.get("schema") != "eira2_functional_preservation_contract_v1":
        errors.append("invalid_preservation_schema")
    if int(contract.get("inventory_entries") or 0) != 76056:
        errors.append("inventory_entry_count_mismatch")
    if int(contract.get("active_runtime_files") or 0) != 12262:
        errors.append("active_runtime_file_count_mismatch")

    seen: set[str] = set()
    for row in contract.get("capabilities") or []:
        if not isinstance(row, dict):
            errors.append("capability_row_not_object")
            continue
        capability_id = str(row.get("id") or "").strip()
        if not capability_id:
            errors.append("capability_id_missing")
            continue
        if capability_id in seen:
            errors.append(f"duplicate_capability:{capability_id}")
        seen.add(capability_id)
        state = str(row.get("state") or "").strip()
        if state not in KNOWN_STATES:
            errors.append(f"invalid_state:{capability_id}:{state}")
        if row.get("required") is True and not row.get("target"):
            errors.append(f"required_target_missing:{capability_id}")
        legacy = row.get("legacy")
        if not isinstance(legacy, list) or not legacy:
            errors.append(f"legacy_evidence_missing:{capability_id}")

    catalogs = contract.get("dynamic_catalogs") or []
    catalog_ids: set[str] = set()
    for row in catalogs:
        if not isinstance(row, dict):
            errors.append("catalog_row_not_object")
            continue
        catalog_id = str(row.get("id") or "").strip()
        if not catalog_id:
            errors.append("catalog_id_missing")
            continue
        if catalog_id in catalog_ids:
            errors.append(f"duplicate_catalog:{catalog_id}")
        catalog_ids.add(catalog_id)
        if row.get("required") is True and not row.get("coverage_rule"):
            errors.append(f"catalog_coverage_rule_missing:{catalog_id}")
    return errors


def report(contract: dict[str, Any] | None = None) -> PreservationReport:
    value = contract or load_contract()
    errors = validate_contract(value)
    if errors:
        raise ValueError(";".join(errors))

    rows = list(value.get("capabilities") or [])
    blockers = tuple(
        str(row["id"])
        for row in rows
        if row.get("required") is True and str(row.get("state")) not in CUTOVER_STATES
    )
    catalogs = {
        str(row["id"])
        for row in value.get("dynamic_catalogs") or []
        if row.get("required") is True
    }
    # The real EIRA 1.x replacement contract carries additional evidence gates
    # discovered during forensic reinspection. Synthetic unit-test contracts do
    # not inherit these EIRA-specific requirements.
    if value.get("source_system") == "EIRA 1.x LIVE":
        catalogs.update(LIVE_EIRA_EXTRA_CATALOGS)

    counts = {state: 0 for state in KNOWN_STATES}
    for row in rows:
        counts[str(row["state"])] += 1
    return PreservationReport(
        total=len(rows),
        native=counts["native"],
        adapters=counts["parity_verified_adapter"],
        partial=counts["partial"],
        missing=counts["missing"],
        blockers=blockers,
        dynamic_catalogs=tuple(sorted(catalogs)),
    )


def assert_cutover_ready(
    contract: dict[str, Any] | None = None,
    *,
    completed_catalogs: set[str] | None = None,
) -> None:
    value = contract or load_contract()
    current = report(value)
    done = set(completed_catalogs or ())
    pending_catalogs = tuple(x for x in current.dynamic_catalogs if x not in done)
    blockers = current.blockers
    if blockers or pending_catalogs:
        details = []
        if blockers:
            details.append("capabilities=" + ",".join(blockers))
        if pending_catalogs:
            details.append("catalogs=" + ",".join(pending_catalogs))
        raise RuntimeError("eira2_cutover_blocked:" + ";".join(details))

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable, Mapping

from .preservation_catalog import LegacyCatalog, build_catalog


_ALLOWED: dict[str, frozenset[str]] = {
    "registered_command": frozenset({"native_replacement", "native_consolidation"}),
    "direct_route": frozenset({"native_replacement", "native_consolidation", "retired_with_evidence"}),
    "http_endpoint": frozenset({"native_replacement", "retired_with_evidence"}),
}


@dataclass(frozen=True, slots=True)
class BehaviorExpectation:
    category: str
    legacy_key: str

    def as_dict(self) -> dict[str, str]:
        return {"category": self.category, "legacy_key": self.legacy_key}


def expectations_from_catalog(catalog: LegacyCatalog) -> tuple[BehaviorExpectation, ...]:
    rows: list[BehaviorExpectation] = []
    rows.extend(BehaviorExpectation("registered_command", value) for value in catalog.registered_commands)
    rows.extend(BehaviorExpectation("direct_route", value) for value in catalog.direct_routes)
    rows.extend(BehaviorExpectation("http_endpoint", value) for value in catalog.http_endpoints)
    return tuple(sorted(rows, key=lambda row: (row.category, row.legacy_key)))


def source_behavior_expectations(root: Path) -> tuple[BehaviorExpectation, ...]:
    catalog = build_catalog(root)
    if catalog.qualification_ok is not True:
        raise RuntimeError("legacy_behavior_catalog_extension_qualification_not_clean:" + repr(catalog.qualification_errors[:10]))
    return expectations_from_catalog(catalog)


def build_behavior_disposition_manifest(root: Path) -> dict[str, object]:
    expected = source_behavior_expectations(root)
    rows: list[dict[str, object]] = []
    for item in expected:
        rendered: dict[str, object] = item.as_dict()
        rendered.update({
            "disposition": "pending",
            "native_eira2_targets": [],
            "parity_verified": False,
            "parity_receipts": [],
            "eira1_runtime_invocation": None,
            "disposition_reason": "",
            "disposition_evidence": [],
        })
        rows.append(rendered)
    counts = {
        category: sum(1 for row in expected if row.category == category)
        for category in _ALLOWED
    }
    return {
        "schema": "eira2_legacy_behavior_disposition_manifest_v1",
        "qualification_complete": False,
        "expected_counts": counts,
        "total_expected": len(expected),
        "rows": rows,
        "rules": {
            "silent_drop_allowed": 0,
            "eira1_runtime_invocation_must_be_false": True,
            "registered_commands_must_be_native_or_consolidated": True,
            "retirement_requires_evidence": True,
        },
    }


def _strings(value: object) -> tuple[str, ...]:
    if not isinstance(value, (list, tuple)):
        return ()
    return tuple(str(item).strip() for item in value if str(item).strip())


def grade_behavior_dispositions(
    expectations: Iterable[BehaviorExpectation],
    receipt_rows: Iterable[Mapping[str, Any]],
) -> dict[str, object]:
    expected_rows = tuple(expectations)
    expected = {(row.category, row.legacy_key): row for row in expected_rows}
    supplied: dict[tuple[str, str], Mapping[str, Any]] = {}
    duplicates: list[str] = []
    unknown: list[str] = []

    for raw in receipt_rows:
        category = str(raw.get("category") or "").strip().casefold()
        legacy_key = str(raw.get("legacy_key") or "").strip()
        key = (category, legacy_key)
        rendered = f"{category}:{legacy_key}"
        if key not in expected:
            unknown.append(rendered)
            continue
        if key in supplied:
            duplicates.append(rendered)
            continue
        supplied[key] = raw

    missing = [f"{category}:{legacy_key}" for category, legacy_key in sorted(set(expected) - set(supplied))]
    results: list[dict[str, object]] = []

    for key in sorted(set(expected) & set(supplied)):
        expectation = expected[key]
        raw = supplied[key]
        disposition = str(raw.get("disposition") or "").strip().casefold()
        targets = _strings(raw.get("native_eira2_targets"))
        receipts = _strings(raw.get("parity_receipts"))
        evidence = _strings(raw.get("disposition_evidence"))
        reason = str(raw.get("disposition_reason") or "").strip()
        violations: list[str] = []

        if disposition not in _ALLOWED[expectation.category]:
            violations.append("invalid_disposition:" + (disposition or "missing"))
        if raw.get("eira1_runtime_invocation") is not False:
            violations.append("eira1_runtime_invocation_not_proven_false")

        if disposition in {"native_replacement", "native_consolidation"}:
            if not targets:
                violations.append("native_eira2_targets_missing")
            if raw.get("parity_verified") is not True:
                violations.append("parity_not_verified")
            if not receipts:
                violations.append("parity_receipts_missing")
            if disposition == "native_consolidation" and not reason:
                violations.append("native_consolidation_reason_missing")
        elif disposition == "retired_with_evidence":
            if not reason:
                violations.append("retirement_reason_missing")
            if not evidence:
                violations.append("retirement_evidence_missing")

        results.append({
            "category": expectation.category,
            "legacy_key": expectation.legacy_key,
            "disposition": disposition,
            "ok": not violations,
            "violations": violations,
            "native_eira2_targets": list(targets),
        })

    failures = [row for row in results if not row["ok"]]
    category_totals: dict[str, int] = {}
    category_passed: dict[str, int] = {}
    for category in _ALLOWED:
        category_totals[category] = sum(1 for row in expected_rows if row.category == category)
        category_passed[category] = sum(1 for row in results if row["category"] == category and row["ok"])

    complete_by_category = {
        category: category_passed[category] == category_totals[category]
        for category in _ALLOWED
    }
    ok = (
        not missing
        and not duplicates
        and not unknown
        and not failures
        and len(results) == len(expected_rows)
        and all(complete_by_category.values())
    )
    passed = sum(1 for row in results if row["ok"])
    return {
        "schema": "eira2_legacy_behavior_disposition_grade_v1",
        "ok": ok,
        "legacy_behavior_parity_complete": ok,
        "expected_total": len(expected_rows),
        "passed_total": passed,
        "coverage_percent": round((100.0 * passed / len(expected_rows)), 3) if expected_rows else 100.0,
        "category_expected": category_totals,
        "category_passed": category_passed,
        "category_complete": complete_by_category,
        "missing_behaviors": missing,
        "duplicate_behaviors": sorted(set(duplicates)),
        "unknown_behaviors": sorted(set(unknown)),
        "failure_count": len(failures),
        "failure_samples": failures[:40],
        "results": results,
        "rules": {
            "silent_drop_allowed": 0,
            "eira1_runtime_invocation_must_be_false": True,
            "registered_commands_must_be_native_or_consolidated": True,
            "retirement_requires_evidence": True,
        },
    }

from __future__ import annotations

import ast
import json
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Iterable

from .extensions.legacy_static_inventory import read_legacy_extension_report


_LEGACY_SOURCE_ENV = "EIRA2_LEGACY_SOURCE_ROOT"


@dataclass(frozen=True, slots=True)
class LegacyCatalog:
    extensions: tuple[dict, ...]
    qualified_active_extensions: tuple[str, ...]
    qualification_ok: bool
    qualification_errors: tuple[str, ...]
    registered_commands: tuple[str, ...]
    direct_routes: tuple[str, ...]
    http_endpoints: tuple[str, ...]

    def summary(self) -> dict:
        return {
            "schema": "eira2_legacy_behavior_catalog_v4",
            "extension_catalog_source": "eira2_static_legacy_inventory",
            "static_manifest_enabled_extensions": len(self.extensions),
            "qualified_active_extensions": len(self.qualified_active_extensions),
            "qualification_ok": self.qualification_ok,
            "qualification_error_count": len(self.qualification_errors),
            "qualification_errors": list(self.qualification_errors),
            "expected_live_qualified_extensions": 93,
            "qualified_extension_names": list(self.qualified_active_extensions),
            "registered_command_prefixes": len(self.registered_commands),
            "direct_route_literals": len(self.direct_routes),
            "http_endpoints": len(self.http_endpoints),
            "manifest_extensions": list(self.extensions),
            "registered_commands": list(self.registered_commands),
            "direct_routes": list(self.direct_routes),
            "http_paths": list(self.http_endpoints),
            "legacy_files_executed": False,
            "legacy_modules_imported": False,
            "read_only": True,
        }


def legacy_source_root(default: Path) -> Path:
    """Resolve the authoritative read-only EIRA 1.x source evidence root.

    Self-mod validation runs in an isolated copy of EIRA 2.0.  It may inspect
    the original repository through this explicit pointer, but the self-mod
    engine never includes that root in its writable promotion boundary.
    """
    configured = os.getenv(_LEGACY_SOURCE_ENV, "").strip()
    candidate = Path(configured).expanduser() if configured else default
    return candidate.resolve()


def _parse(path: Path) -> ast.AST:
    return ast.parse(path.read_text(encoding="utf-8", errors="replace"), filename=str(path))


def enabled_extensions(root: Path) -> tuple[dict, ...]:
    rows: list[dict] = []
    for manifest in sorted((root / "extensions").glob("*/manifest.json")):
        try:
            value = json.loads(manifest.read_text(encoding="utf-8"))
        except Exception:
            continue
        if not isinstance(value, dict) or value.get("status") != "enabled":
            continue
        rows.append({
            "name": str(value.get("name") or value.get("extension") or manifest.parent.name),
            "entrypoint": str(value.get("entrypoint") or ""),
            "kind": str(value.get("kind") or ""),
        })
    return tuple(rows)


def qualification_catalog(root: Path) -> tuple[tuple[str, ...], bool, tuple[str, ...]]:
    """Qualify EIRA1 extensions by static EIRA2-native inspection only.

    Legacy Python is never imported or executed.  The same static inventory used by
    extension parity is reused here so the behavior-preservation path cannot create
    a hidden EIRA1 execution authority during final qualification.
    """
    report = read_legacy_extension_report(root)
    errors: list[str] = []

    if report.get("read_only") is not True:
        errors.append("static_inventory_not_read_only")
    if report.get("legacy_files_executed") is not False:
        errors.append("legacy_files_executed_during_inventory")
    if report.get("legacy_modules_imported") is not False:
        errors.append("legacy_modules_imported_during_inventory")
    if report.get("mutated") is not False:
        errors.append("legacy_inventory_mutated_source")

    names: set[str] = set()
    for row in report.get("extensions") or []:
        if isinstance(row, dict) and row.get("enabled") is True:
            name = str(row.get("name") or "").strip()
            if name:
                names.add(name)
    for row in report.get("referenced_manifestless") or []:
        if not isinstance(row, dict):
            continue
        name = str(row.get("name") or "").strip()
        if name:
            names.add(name)

    for item in report.get("boot_critical_errors") or []:
        if not isinstance(item, dict):
            continue
        name = str(item.get("name") or "unknown")
        details = ",".join(str(x) for x in item.get("errors") or [])
        errors.append(f"{name}:{details}")

    return tuple(sorted(names)), bool(report.get("ok")) and not errors, tuple(sorted(errors))


def _register_prefixes(tree: ast.AST) -> Iterable[str]:
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not node.args:
            continue
        func = node.func
        name = func.id if isinstance(func, ast.Name) else func.attr if isinstance(func, ast.Attribute) else ""
        if name != "register":
            continue
        arg = node.args[0]
        if isinstance(arg, ast.Constant) and isinstance(arg.value, str):
            value = arg.value.strip().lower()
            if value:
                yield value


def registered_commands(root: Path) -> tuple[str, ...]:
    prefixes: set[str] = set()
    for path in sorted((root / "commands").rglob("*.py")):
        try:
            prefixes.update(_register_prefixes(_parse(path)))
        except (SyntaxError, OSError):
            continue
    return tuple(sorted(prefixes))


def _string_constants(node: ast.AST) -> Iterable[str]:
    for child in ast.walk(node):
        if isinstance(child, ast.Constant) and isinstance(child.value, str):
            yield child.value


def direct_routes(root: Path) -> tuple[str, ...]:
    routes: set[str] = set()
    for relative in ("main.py", "brain/executive.py"):
        path = root / relative
        try:
            tree = _parse(path)
        except (SyntaxError, OSError):
            continue
        for node in ast.walk(tree):
            if isinstance(node, ast.If):
                for value in _string_constants(node.test):
                    clean = " ".join(value.strip().lower().split())
                    if clean and len(clean) <= 120:
                        routes.add(clean)
    return tuple(sorted(routes))


def http_endpoints(root: Path) -> tuple[str, ...]:
    path = root / "extensions" / "eira_voice_input_ai" / "server.py"
    try:
        tree = _parse(path)
    except (SyntaxError, OSError):
        return ()
    endpoints: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.If):
            continue
        for value in _string_constants(node.test):
            clean = value.strip()
            if clean.startswith("/") and len(clean) <= 160:
                endpoints.add(clean)
    return tuple(sorted(endpoints))


def build_catalog(root: Path) -> LegacyCatalog:
    root = legacy_source_root(root)
    qualified, qualification_ok, qualification_errors = qualification_catalog(root)
    return LegacyCatalog(
        extensions=enabled_extensions(root),
        qualified_active_extensions=qualified,
        qualification_ok=qualification_ok,
        qualification_errors=qualification_errors,
        registered_commands=registered_commands(root),
        direct_routes=direct_routes(root),
        http_endpoints=http_endpoints(root),
    )

from __future__ import annotations

import ast
import importlib
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Any

from ..contracts import Event, Health, RuntimeContext, Service, ServiceSpec, ServiceState
from ..kernel.supervisor import Supervisor
from .graph import NodeRegistryService


_SCHEMA = "eira2_extension_manifest_v1"


@dataclass(frozen=True, slots=True)
class ExtensionManifest:
    name: str
    module: str
    factory: str
    dependencies: tuple[str, ...]
    capabilities: tuple[str, ...]
    shadow_safe: bool
    required: bool = False

    @classmethod
    def parse(cls, value: dict[str, Any]) -> "ExtensionManifest":
        if not isinstance(value, dict) or value.get("schema") != _SCHEMA:
            raise ValueError("extension_manifest_schema_invalid")
        manifest = cls(
            name=str(value.get("name") or "").strip(),
            module=str(value.get("module") or "").strip(),
            factory=str(value.get("factory") or "create_service").strip(),
            dependencies=tuple(str(x).strip() for x in value.get("dependencies", ()) if str(x).strip()),
            capabilities=tuple(str(x).strip() for x in value.get("capabilities", ()) if str(x).strip()),
            shadow_safe=bool(value.get("shadow_safe", False)),
            required=bool(value.get("required", False)),
        )
        if not manifest.name.startswith("extension.") or len(manifest.name) > 200:
            raise ValueError(f"extension_manifest_name_invalid:{manifest.name}")
        if not manifest.module.startswith("eira2.extensions."):
            raise ValueError(f"extension_manifest_module_outside_namespace:{manifest.name}")
        if not manifest.factory.isidentifier():
            raise ValueError(f"extension_manifest_factory_invalid:{manifest.name}")
        if manifest.required:
            raise ValueError(f"dynamic_extension_required_forbidden:{manifest.name}")
        if len(set(manifest.dependencies)) != len(manifest.dependencies):
            raise ValueError(f"extension_duplicate_dependency:{manifest.name}")
        if len(set(manifest.capabilities)) != len(manifest.capabilities):
            raise ValueError(f"extension_duplicate_capability:{manifest.name}")
        return manifest


def _literal_assignment(node: ast.Assign | ast.AnnAssign) -> bool:
    value = node.value
    if value is None:
        return True
    try:
        ast.literal_eval(value)
        return True
    except (ValueError, TypeError):
        return False


def validate_import_safety(path: Path) -> list[str]:
    """Reject obvious import-time execution; extensions boot only via factory/service.start."""
    source = path.read_text(encoding="utf-8", errors="strict")
    tree = ast.parse(source, filename=str(path))
    errors: list[str] = []
    for node in tree.body:
        if isinstance(node, ast.Expr) and isinstance(node.value, ast.Constant) and isinstance(node.value.value, str):
            continue
        if isinstance(node, (ast.Import, ast.ImportFrom, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
            continue
        if isinstance(node, (ast.Assign, ast.AnnAssign)) and _literal_assignment(node):
            continue
        errors.append(f"import_time_execution:{type(node).__name__}:{getattr(node, 'lineno', 0)}")
    return errors


class ExtensionManagerService:
    """Discovers and attaches optional EIRA2 services under Supervisor authority."""

    spec = ServiceSpec(
        "registry.extensions",
        required=True,
        dependencies=("registry.graph", "kernel.events"),
        start_timeout_seconds=15.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(self, project_root: Path) -> None:
        self.project_root = project_root.expanduser().resolve()
        self.manifest_root = self.project_root / "eira2" / "extensions" / "manifests"
        self._state = ServiceState.DECLARED
        self._context: RuntimeContext | None = None
        self._attached: dict[str, ExtensionManifest] = {}
        self._errors: list[str] = []

    async def start(self, context: RuntimeContext) -> None:
        self._context = context
        self.manifest_root.mkdir(parents=True, exist_ok=True)
        self._state = ServiceState.READY

    async def stop(self) -> None:
        self._context = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        state = ServiceState.DEGRADED if self._errors else self._state
        return Health(state, f"attached={len(self._attached)} errors={len(self._errors)}")

    def discover(self) -> tuple[ExtensionManifest, ...]:
        rows: list[ExtensionManifest] = []
        names: set[str] = set()
        for path in sorted(self.manifest_root.glob("*.json")):
            value = json.loads(path.read_text(encoding="utf-8"))
            manifest = ExtensionManifest.parse(value)
            if manifest.name in names:
                raise ValueError(f"duplicate_dynamic_extension:{manifest.name}")
            names.add(manifest.name)
            rows.append(manifest)
        return tuple(rows)

    def _module_path(self, manifest: ExtensionManifest) -> Path:
        relative = Path(*manifest.module.split(".")).with_suffix(".py")
        path = (self.project_root / relative).resolve()
        try:
            path.relative_to(self.project_root)
        except ValueError as error:
            raise ValueError(f"extension_module_path_escape:{manifest.name}") from error
        if not path.is_file():
            package = (self.project_root / Path(*manifest.module.split(".")) / "__init__.py").resolve()
            if package.is_file():
                return package
            raise FileNotFoundError(f"extension_module_missing:{manifest.name}:{manifest.module}")
        return path

    def validate(self, manifest: ExtensionManifest, registry: NodeRegistryService) -> None:
        path = self._module_path(manifest)
        safety = validate_import_safety(path)
        if safety:
            raise ValueError(f"extension_import_safety_failed:{manifest.name}:{','.join(safety[:8])}")
        known = {str(row.get("name")) for row in registry.snapshot().get("nodes", []) if isinstance(row, dict)}
        for dependency in manifest.dependencies:
            if dependency not in known:
                raise ValueError(f"extension_dependency_missing:{manifest.name}:{dependency}")

    def instantiate(self, manifest: ExtensionManifest) -> Service:
        module = importlib.import_module(manifest.module)
        factory = getattr(module, manifest.factory, None)
        if not callable(factory):
            raise ValueError(f"extension_factory_missing:{manifest.name}:{manifest.factory}")
        service = factory()
        spec = getattr(service, "spec", None)
        if not isinstance(spec, ServiceSpec):
            raise TypeError(f"extension_service_spec_invalid:{manifest.name}")
        if spec.name != manifest.name:
            raise ValueError(f"extension_service_name_mismatch:{manifest.name}:{spec.name}")
        if spec.required:
            raise ValueError(f"dynamic_extension_required_forbidden:{manifest.name}")
        if tuple(spec.dependencies) != manifest.dependencies:
            raise ValueError(f"extension_dependency_mismatch:{manifest.name}")
        return service

    async def attach_all(self, supervisor: Supervisor, *, shadow_mode: bool) -> dict[str, Any]:
        if self._context is None:
            raise RuntimeError("extension_manager_not_ready")
        registry = self._context.get_service("registry.graph")
        if not isinstance(registry, NodeRegistryService):
            raise RuntimeError("canonical_registry_missing")
        attached: list[str] = []
        skipped: list[str] = []
        errors: list[str] = []
        for manifest in self.discover():
            if manifest.name in self._attached:
                continue
            if shadow_mode and not manifest.shadow_safe:
                skipped.append(manifest.name)
                continue
            try:
                self.validate(manifest, registry)
                service = self.instantiate(manifest)
                await supervisor.attach_service(service)
                try:
                    await registry.register_node(
                        manifest.name,
                        kind="extension",
                        capabilities=manifest.capabilities,
                        metadata={"module": manifest.module, "factory": manifest.factory},
                    )
                    for dependency in manifest.dependencies:
                        await registry.add_bridge(
                            manifest.name,
                            dependency,
                            kind="service_dependency",
                            conductive=True,
                            evidence="dynamic_extension_manifest",
                        )
                except BaseException:
                    # Cleanup must run even for lifecycle cancellation, but cancellation
                    # itself is re-raised and must remain Supervisor authority.
                    await supervisor.detach_service(manifest.name)
                    raise
                self._attached[manifest.name] = manifest
                attached.append(manifest.name)
            except Exception as error:
                rendered = f"{manifest.name}:{type(error).__name__}:{error}"
                errors.append(rendered[:600])
        self._errors = errors
        self._state = ServiceState.DEGRADED if errors else ServiceState.READY
        await self._context.publish(Event("registry.extension_reconcile", {
            "attached": len(attached),
            "skipped": len(skipped),
            "errors": len(errors),
        }))
        return {
            "ok": not errors,
            "attached": attached,
            "skipped_shadow_unsafe": skipped,
            "errors": errors,
            "total_attached": len(self._attached),
        }

    def snapshot(self) -> dict[str, Any]:
        return {
            "schema": "eira2_dynamic_extensions_v1",
            "ok": not self._errors,
            "attached": sorted(self._attached),
            "errors": list(self._errors),
        }

from __future__ import annotations

import asyncio
from dataclasses import dataclass, field
from typing import Any, Iterable

from ..contracts import Event, Health, RuntimeContext, ServiceSpec, ServiceState


@dataclass(frozen=True, slots=True)
class NodeRecord:
    name: str
    kind: str = "service"
    required: bool = False
    capabilities: tuple[str, ...] = ()
    metadata: dict[str, str] = field(default_factory=dict)


@dataclass(frozen=True, slots=True)
class BridgeRecord:
    source: str
    target: str
    kind: str = "service_dependency"
    conductive: bool = True
    evidence: str = "service_spec_dependency"


class NodeRegistryService:
    """Canonical discoverability and bridge-integrity authority.

    The registry describes topology only. It never imports or boots a node.
    Lifecycle remains exclusively owned by the supervisor.
    """

    spec = ServiceSpec(
        "registry.graph",
        required=True,
        dependencies=("state.store", "kernel.events"),
    )

    def __init__(self) -> None:
        self._nodes: dict[str, NodeRecord] = {}
        self._bridges: dict[tuple[str, str, str], BridgeRecord] = {}
        self._state = ServiceState.DECLARED
        self._context: RuntimeContext | None = None
        self._lock = asyncio.Lock()

    def seed(
        self,
        specs: Iterable[ServiceSpec],
        *,
        capabilities: dict[str, Iterable[str]] | None = None,
    ) -> None:
        if self._state not in {ServiceState.DECLARED, ServiceState.STOPPED}:
            raise RuntimeError("registry_seed_after_start")
        cap_map = capabilities or {}
        for spec in specs:
            name = str(spec.name or "").strip()
            if not name:
                raise ValueError("registry_node_name_missing")
            if name in self._nodes:
                raise ValueError(f"registry_duplicate_node:{name}")
            self._nodes[name] = NodeRecord(
                name=name,
                kind="service",
                required=bool(spec.required),
                capabilities=tuple(sorted({str(x) for x in cap_map.get(name, ()) if str(x)})),
                metadata={"start_timeout_seconds": str(spec.start_timeout_seconds)},
            )
        for spec in specs:
            for dependency in spec.dependencies:
                self._add_bridge_sync(
                    BridgeRecord(
                        source=spec.name,
                        target=dependency,
                        kind="service_dependency",
                        conductive=True,
                        evidence="service_spec_dependency",
                    )
                )
        self.validate()

    def _add_bridge_sync(self, bridge: BridgeRecord) -> None:
        if bridge.source == bridge.target:
            raise ValueError(f"registry_self_bridge:{bridge.source}")
        if bridge.source not in self._nodes:
            raise ValueError(f"registry_bridge_source_missing:{bridge.source}")
        if bridge.target not in self._nodes:
            raise ValueError(f"registry_bridge_target_missing:{bridge.target}")
        key = (bridge.source, bridge.target, bridge.kind)
        existing = self._bridges.get(key)
        if existing is not None and existing != bridge:
            raise ValueError(f"registry_bridge_conflict:{bridge.source}:{bridge.target}:{bridge.kind}")
        self._bridges[key] = bridge

    def validate(self) -> None:
        for bridge in self._bridges.values():
            if bridge.source not in self._nodes or bridge.target not in self._nodes:
                raise ValueError("registry_orphan_bridge")
            if bridge.kind == "anatomical_membership" and bridge.conductive:
                raise ValueError("registry_synthetic_bridge_cannot_conduct")

        graph: dict[str, list[str]] = {name: [] for name in self._nodes}
        for bridge in self._bridges.values():
            if bridge.kind == "service_dependency":
                graph[bridge.source].append(bridge.target)

        visiting: set[str] = set()
        visited: set[str] = set()

        def visit(name: str) -> None:
            if name in visited:
                return
            if name in visiting:
                raise ValueError(f"registry_dependency_cycle:{name}")
            visiting.add(name)
            for dependency in graph[name]:
                visit(dependency)
            visiting.remove(name)
            visited.add(name)

        for name in sorted(graph):
            visit(name)

    async def start(self, context: RuntimeContext) -> None:
        self.validate()
        self._context = context
        self._state = ServiceState.READY
        for node in sorted(self._nodes.values(), key=lambda row: row.name):
            await context.publish(Event("registry.node_registered", {
                "name": node.name,
                "kind": node.kind,
                "cluster": self.cluster_for(node.name),
            }))

    async def stop(self) -> None:
        self._context = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        detail = f"nodes={len(self._nodes)} bridges={len(self._bridges)}"
        return Health(self._state, detail)

    @staticmethod
    def cluster_for(name: str) -> str:
        head = str(name or "").split(".", 1)[0] or "runtime"
        return f"eira2:{head}"

    async def register_node(
        self,
        name: str,
        *,
        kind: str = "runtime_node",
        required: bool = False,
        capabilities: Iterable[str] = (),
        metadata: dict[str, str] | None = None,
    ) -> NodeRecord:
        clean = str(name or "").strip()
        if not clean:
            raise ValueError("registry_node_name_missing")
        async with self._lock:
            if clean in self._nodes:
                raise ValueError(f"registry_duplicate_node:{clean}")
            node = NodeRecord(
                name=clean,
                kind=str(kind or "runtime_node")[:80],
                required=bool(required),
                capabilities=tuple(sorted({str(x) for x in capabilities if str(x)})),
                metadata={str(k): str(v) for k, v in (metadata or {}).items()},
            )
            self._nodes[clean] = node
            self.validate()
        if self._context is not None:
            await self._context.publish(Event("registry.node_registered", {
                "name": node.name,
                "kind": node.kind,
                "cluster": self.cluster_for(node.name),
            }))
        return node

    async def add_bridge(
        self,
        source: str,
        target: str,
        *,
        kind: str = "runtime_call",
        conductive: bool = True,
        evidence: str = "runtime_registration",
    ) -> BridgeRecord:
        bridge = BridgeRecord(
            source=str(source or "").strip(),
            target=str(target or "").strip(),
            kind=str(kind or "runtime_call")[:80],
            conductive=bool(conductive),
            evidence=str(evidence or "runtime_registration")[:160],
        )
        async with self._lock:
            self._add_bridge_sync(bridge)
            self.validate()
        if self._context is not None:
            await self._context.publish(Event("registry.bridge_registered", {
                "source": bridge.source,
                "target": bridge.target,
                "kind": bridge.kind,
                "conductive": bridge.conductive,
                "evidence": bridge.evidence,
            }))
        return bridge

    def find(self, query: str) -> tuple[NodeRecord, ...]:
        clean = str(query or "").casefold().strip()
        if not clean:
            return tuple(sorted(self._nodes.values(), key=lambda row: row.name))
        rows = []
        for node in self._nodes.values():
            haystack = " ".join((node.name, node.kind, *node.capabilities)).casefold()
            if clean in haystack:
                rows.append(node)
        return tuple(sorted(rows, key=lambda row: row.name))

    def snapshot(self) -> dict[str, Any]:
        self.validate()
        return {
            "schema": "eira2_node_registry_v1",
            "ok": True,
            "node_count": len(self._nodes),
            "bridge_count": len(self._bridges),
            "nodes": [
                {
                    "name": row.name,
                    "kind": row.kind,
                    "required": row.required,
                    "capabilities": list(row.capabilities),
                    "metadata": dict(row.metadata),
                }
                for row in sorted(self._nodes.values(), key=lambda item: item.name)
            ],
            "bridges": [
                {
                    "source": row.source,
                    "target": row.target,
                    "kind": row.kind,
                    "conductive": row.conductive,
                    "evidence": row.evidence,
                }
                for row in sorted(
                    self._bridges.values(),
                    key=lambda item: (item.source, item.target, item.kind),
                )
            ],
        }

from __future__ import annotations

import json
import re
from dataclasses import dataclass
from pathlib import Path
from typing import Any


_SCHEMA = "eira2_service_manifest_v1"
_NAME = re.compile(r"^[a-z][a-z0-9_]*(?:\.[a-z][a-z0-9_]*)*$")
_MODULE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*(?:\.[A-Za-z_][A-Za-z0-9_]*)*$")
_SYMBOL = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


@dataclass(frozen=True, slots=True)
class Manifest:
    name: str
    module: str
    factory: str
    required: bool
    dependencies: tuple[str, ...]
    capabilities: tuple[str, ...]
    timeout_seconds: float

    @property
    def startup_timeout_seconds(self) -> float:
        return self.timeout_seconds

    @classmethod
    def parse(cls, value: dict[str, Any]) -> "Manifest":
        if not isinstance(value, dict):
            raise TypeError("manifest_not_object")
        if value.get("schema") != _SCHEMA:
            raise ValueError("manifest_schema_invalid")
        try:
            name = str(value["name"]).strip()
            module = str(value["module"]).strip()
        except KeyError as error:
            raise ValueError(f"manifest_required_field_missing:{error.args[0]}") from error
        factory = str(value.get("factory") or "create_service").strip()
        dependencies = tuple(str(x).strip() for x in value.get("dependencies", ()) if str(x).strip())
        capabilities = tuple(str(x).strip() for x in value.get("capabilities", ()) if str(x).strip())
        manifest = cls(
            name=name,
            module=module,
            factory=factory,
            required=bool(value.get("required", False)),
            dependencies=dependencies,
            capabilities=capabilities,
            timeout_seconds=float(value.get("timeout_seconds", 15.0)),
        )
        if not _NAME.fullmatch(manifest.name):
            raise ValueError(f"manifest_name_invalid:{manifest.name}")
        if not _MODULE.fullmatch(manifest.module):
            raise ValueError(f"manifest_module_invalid:{manifest.name}:{manifest.module}")
        if not _SYMBOL.fullmatch(manifest.factory):
            raise ValueError(f"manifest_factory_invalid:{manifest.name}:{manifest.factory}")
        if len(set(manifest.dependencies)) != len(manifest.dependencies):
            raise ValueError(f"manifest_duplicate_dependency:{manifest.name}")
        if manifest.name in manifest.dependencies:
            raise ValueError(f"manifest_self_dependency:{manifest.name}")
        if len(set(manifest.capabilities)) != len(manifest.capabilities):
            raise ValueError(f"manifest_duplicate_capability:{manifest.name}")
        if not 0.1 <= manifest.timeout_seconds <= 300.0:
            raise ValueError(f"manifest_startup_timeout_invalid:{manifest.name}")
        return manifest


def discover(directory: Path) -> list[Manifest]:
    if not directory.is_dir():
        raise FileNotFoundError(f"manifest_directory_missing:{directory}")
    manifests: list[Manifest] = []
    names: set[str] = set()
    for path in sorted(directory.glob("*.json")):
        value = json.loads(path.read_text(encoding="utf-8"))
        manifest = Manifest.parse(value)
        if manifest.name in names:
            raise ValueError(f"duplicate_manifest:{manifest.name}")
        names.add(manifest.name)
        manifests.append(manifest)
    if not manifests:
        raise ValueError("manifest_set_empty")
    return manifests

from __future__ import annotations

import asyncio
import hashlib
import json
import time
from pathlib import Path
from typing import Any, Iterable

from ..contracts import Event, Health, RuntimeContext, ServiceSpec, ServiceState
from ..operations.doctor import DoctorService


class ActivationService:
    """Separates code promotion on disk from activation in a fresh process."""

    spec = ServiceSpec(
        "repair.activation",
        required=True,
        dependencies=("operations.doctor", "state.checkpoints", "registry.graph"),
        start_timeout_seconds=20.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(self, root: Path, project_root: Path) -> None:
        self.root = root.expanduser().resolve()
        self.project_root = project_root.expanduser().resolve()
        self._state = ServiceState.DECLARED
        self._context: RuntimeContext | None = None
        self._last: dict[str, Any] = {}

    @property
    def pending_path(self) -> Path:
        return self.root / "pending_restart.json"

    @property
    def activated_path(self) -> Path:
        return self.root / "last_activation.json"

    async def start(self, context: RuntimeContext) -> None:
        self._context = context
        self.root.mkdir(parents=True, exist_ok=True)
        self._state = ServiceState.READY
        if self.pending_path.is_file():
            await self._verify_pending_after_restart()

    async def stop(self) -> None:
        self._context = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        detail = "no_pending_restart"
        if self.pending_path.is_file():
            detail = "restart_pending"
        elif self._last:
            detail = f"last_activation={self._last.get('proposal_id', 'unknown')}"
        return Health(self._state, detail)

    @staticmethod
    def _digest_files(project_root: Path, paths: Iterable[str]) -> str:
        digest = hashlib.sha256()
        for relative in sorted({str(x).replace("\\", "/") for x in paths if str(x)}):
            path = (project_root / relative).resolve()
            try:
                path.relative_to(project_root)
            except ValueError as error:
                raise ValueError(f"activation_path_escape:{relative}") from error
            if not path.is_file():
                raise FileNotFoundError(f"activation_file_missing:{relative}")
            digest.update(relative.encode("utf-8"))
            digest.update(b"\0")
            digest.update(path.read_bytes())
            digest.update(b"\0")
        return digest.hexdigest()

    def request_restart(
        self,
        *,
        proposal_id: str,
        changed_paths: Iterable[str],
        checkpoint_id: str,
    ) -> dict[str, Any]:
        proposal = str(proposal_id or "").strip()
        paths = tuple(sorted({str(x).replace("\\", "/") for x in changed_paths if str(x)}))
        if not proposal or not paths:
            raise ValueError("restart_request_identity_required")
        receipt = {
            "schema": "eira2_restart_activation_v1",
            "proposal_id": proposal,
            "changed_paths": list(paths),
            "changed_digest": self._digest_files(self.project_root, paths),
            "checkpoint_id": str(checkpoint_id or ""),
            "requested_at_unix": time.time(),
            "restart_required": True,
            "activated": False,
        }
        temp = self.pending_path.with_suffix(".json.new")
        temp.write_text(json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        temp.replace(self.pending_path)
        return {"ok": True, **receipt}

    async def _verify_pending_after_restart(self) -> None:
        if self._context is None:
            raise RuntimeError("activation_context_missing")
        try:
            pending = await asyncio.to_thread(self._read_pending)
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            self._state = ServiceState.FAILED
            raise RuntimeError(f"activation_receipt_invalid:{error}") from error
        if pending.get("schema") != "eira2_restart_activation_v1":
            self._state = ServiceState.FAILED
            raise RuntimeError("activation_receipt_schema_invalid")
        paths = tuple(str(x) for x in pending.get("changed_paths") or ())
        current_digest = await asyncio.to_thread(self._digest_files, self.project_root, paths)
        if current_digest != str(pending.get("changed_digest") or ""):
            self._state = ServiceState.FAILED
            raise RuntimeError("activation_source_digest_mismatch")
        doctor = self._context.get_service("operations.doctor")
        if not isinstance(doctor, DoctorService):
            self._state = ServiceState.FAILED
            raise RuntimeError("activation_doctor_missing")
        report = await asyncio.to_thread(doctor.evaluate, project_root=self.project_root)
        if not report.ok:
            self._state = ServiceState.FAILED
            raise RuntimeError("activation_doctor_failed:" + ";".join(report.errors[:8]))
        activated = {
            **pending,
            "restart_required": False,
            "activated": True,
            "activated_at_unix": time.time(),
            "doctor_verified": True,
        }
        await asyncio.to_thread(self._write_activation, activated)
        self._last = activated
        await self._context.publish(Event("repair.activation_verified", {
            "proposal_id": activated["proposal_id"],
            "changed_count": len(paths),
        }))

    def _read_pending(self) -> dict[str, Any]:
        return json.loads(self.pending_path.read_text(encoding="utf-8"))

    def _write_activation(self, activated: dict[str, Any]) -> None:
        temp = self.activated_path.with_suffix(".json.new")
        temp.write_text(json.dumps(activated, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        temp.replace(self.activated_path)
        self.pending_path.unlink(missing_ok=True)

    def status(self) -> dict[str, Any]:
        return {
            "ok": self._state != ServiceState.FAILED,
            "state": self._state.value,
            "restart_pending": self.pending_path.is_file(),
            "last_activation": dict(self._last),
        }

from __future__ import annotations

import asyncio
import hashlib
import json
import os
import shutil
import subprocess
import sys
import time
from dataclasses import asdict, dataclass, field
from pathlib import Path, PurePosixPath
from typing import Any, Awaitable, Callable, Iterable
from uuid import uuid4

from ..contracts import Event, Health, RuntimeContext, ServiceSpec, ServiceState
from ..operations.doctor import DoctorReport, DoctorService, audit_project
from .coordinator import RepairCandidate, RepairCoordinator


_PROTECTED = {
    "preservation_contract.json",
    "CANONICAL_ORDER.md",
    "FUNCTIONAL_PRESERVATION.md",
    "REPLACEMENT_CONTRACT.md",
    "pyproject.toml",
}
_ALLOWED_PREFIXES = ("eira2/", "manifests/")
_MAX_FILES = 64
_MAX_FILE_BYTES = 2_000_000
_MAX_TOTAL_BYTES = 8_000_000


@dataclass(frozen=True, slots=True)
class FileChange:
    path: str
    content: str
    reason: str = ""


@dataclass(frozen=True, slots=True)
class ChangeProposal:
    changes: tuple[FileChange, ...]
    purpose: str
    proposal_id: str = field(default_factory=lambda: uuid4().hex)


@dataclass(frozen=True, slots=True)
class ValidationReceipt:
    proposal_id: str
    staged_digest: str
    doctor_ok: bool
    tests_ok: bool
    doctor_errors: tuple[str, ...]
    doctor_warnings: tuple[str, ...]
    test_output_tail: str
    validated_at_unix: float

    @property
    def accepted(self) -> bool:
        return self.doctor_ok and self.tests_ok


ProposalProvider = Callable[[DoctorReport], Awaitable[ChangeProposal | None]]


def _safe_relative(value: str) -> str:
    raw = str(value or "").replace("\\", "/").strip()
    path = PurePosixPath(raw)
    if not raw or path.is_absolute() or ".." in path.parts or "." in path.parts:
        raise ValueError(f"selfmod_path_rejected:{raw}")
    clean = path.as_posix()
    if clean in _PROTECTED or clean.startswith("tests/") or clean.startswith("tools/"):
        raise ValueError(f"selfmod_protected_path:{clean}")
    if not any(clean.startswith(prefix) for prefix in _ALLOWED_PREFIXES):
        raise ValueError(f"selfmod_path_outside_implementation:{clean}")
    return clean


def _checked_target(root: Path, relative: str, label: str) -> Path:
    """Return a lexical child path only when every existing component is non-symlink.

    Resolving a candidate path first is unsafe because resolution hides the fact that
    an intermediate component was a symlink. Repair paths are already restricted by
    ``_safe_relative``; this walk adds the filesystem containment half of the rule.
    """
    rel = _safe_relative(relative)
    base = root.expanduser().resolve()
    parts = PurePosixPath(rel).parts
    cursor = base
    for index, part in enumerate(parts):
        cursor = cursor / part
        if cursor.is_symlink():
            raise RuntimeError(f"selfmod_{label}_symlink_rejected:{rel}:{'/'.join(parts[:index + 1])}")
        if index < len(parts) - 1 and cursor.exists() and not cursor.is_dir():
            raise RuntimeError(f"selfmod_{label}_parent_not_directory:{rel}:{'/'.join(parts[:index + 1])}")
    return cursor


def _proposal_digest(workspace: Path, proposal: ChangeProposal) -> str:
    digest = hashlib.sha256()
    for change in sorted(proposal.changes, key=lambda row: row.path):
        rel = _safe_relative(change.path)
        path = _checked_target(workspace, rel, "staged")
        if not path.is_file() or path.is_symlink():
            raise RuntimeError(f"selfmod_staged_file_invalid:{rel}")
        digest.update(rel.encode("utf-8"))
        digest.update(b"\0")
        digest.update(path.read_bytes())
        digest.update(b"\0")
    return digest.hexdigest()


class SelfEvolutionService:
    spec = ServiceSpec(
        "repair.self_evolution",
        required=False,
        dependencies=("repair.coordinator", "operations.doctor", "registry.graph"),
        start_timeout_seconds=30.0,
        stop_timeout_seconds=10.0,
    )

    def __init__(
        self,
        project_root: Path,
        var_root: Path,
        *,
        enabled: bool = False,
        provider: ProposalProvider | None = None,
        interval_seconds: float = 900.0,
    ) -> None:
        self.project_root = project_root.expanduser().resolve()
        self.var_root = var_root.expanduser().resolve()
        self.enabled = bool(enabled)
        self.provider = provider
        self.interval_seconds = max(60.0, float(interval_seconds))
        self._state = ServiceState.DECLARED
        self._context: RuntimeContext | None = None
        self._task: asyncio.Task[None] | None = None
        self._cycle_lock = asyncio.Lock()
        self._last_validation: dict[str, ValidationReceipt] = {}
        self._last_cycle: dict[str, Any] = {}

    @property
    def work_root(self) -> Path:
        return self.var_root / "selfmod"

    async def start(self, context: RuntimeContext) -> None:
        self._context = context
        self.work_root.mkdir(parents=True, exist_ok=True)
        if self.enabled and self.provider is None:
            self._state = ServiceState.FAILED
            raise RuntimeError("self_evolution_provider_required")
        self._state = ServiceState.READY if self.enabled else ServiceState.DEGRADED
        if self.enabled:
            self._task = asyncio.create_task(self._loop(), name="eira2-self-evolution")

    async def stop(self) -> None:
        task = self._task
        self._task = None
        if task is not None:
            task.cancel()
            try:
                await task
            except asyncio.CancelledError:
                pass
        self._context = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        if self.enabled and self.provider is None:
            return Health(ServiceState.FAILED, "provider_missing")
        detail = "enabled" if self.enabled else "disabled_by_isolation"
        if self._last_cycle:
            detail += f" last={self._last_cycle.get('status', 'unknown')}"
        return Health(self._state, detail)

    def validate_proposal(self, proposal: ChangeProposal) -> tuple[FileChange, ...]:
        if not isinstance(proposal, ChangeProposal):
            raise TypeError("selfmod_proposal_type_invalid")
        if not proposal.purpose.strip():
            raise ValueError("selfmod_purpose_required")
        if not proposal.changes:
            raise ValueError("selfmod_changes_empty")
        if len(proposal.changes) > _MAX_FILES:
            raise ValueError("selfmod_change_count_exceeded")
        total = 0
        seen: set[str] = set()
        normalized: list[FileChange] = []
        for change in proposal.changes:
            rel = _safe_relative(change.path)
            if rel in seen:
                raise ValueError(f"selfmod_duplicate_path:{rel}")
            seen.add(rel)
            raw = change.content.encode("utf-8")
            if len(raw) > _MAX_FILE_BYTES:
                raise ValueError(f"selfmod_file_too_large:{rel}")
            total += len(raw)
            normalized.append(FileChange(rel, change.content, change.reason))
        if total > _MAX_TOTAL_BYTES:
            raise ValueError("selfmod_total_payload_exceeded")
        return tuple(normalized)

    def _workspace(self, proposal_id: str) -> Path:
        return self.work_root / "workspaces" / proposal_id

    def _receipt_path(self, proposal_id: str) -> Path:
        return self.work_root / "receipts" / f"{proposal_id}.json"

    def stage(self, proposal: ChangeProposal) -> Path:
        changes = self.validate_proposal(proposal)
        for change in changes:
            _checked_target(self.project_root, change.path, "source")
        workspace = self._workspace(proposal.proposal_id)
        if workspace.exists():
            shutil.rmtree(workspace)
        workspace.parent.mkdir(parents=True, exist_ok=True)
        shutil.copytree(
            self.project_root,
            workspace,
            symlinks=True,
            ignore=shutil.ignore_patterns("var", "__pycache__", ".pytest_cache", "*.pyc"),
        )
        for change in changes:
            target = _checked_target(workspace, change.path, "staged")
            target.parent.mkdir(parents=True, exist_ok=True)
            if target.exists() and target.is_symlink():
                raise RuntimeError(f"selfmod_staged_symlink_rejected:{change.path}")
            target.write_text(change.content, encoding="utf-8")
        return workspace

    def validate_staged(self, proposal: ChangeProposal, workspace: Path) -> ValidationReceipt:
        doctor = audit_project(
            workspace,
            state_path=None,
            run_external_checks=True,
        )
        tests_ok = False
        output = ""
        if doctor.ok:
            try:
                completed = subprocess.run(
                    [sys.executable, "-m", "pytest", "-q"],
                    cwd=workspace,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    check=False,
                    env={**os.environ, "EIRA2_SELFMOD_VALIDATION": "1"},
                )
                tests_ok = completed.returncode == 0
                output = completed.stdout[-4000:]
            except (OSError, subprocess.SubprocessError) as error:
                output = f"{type(error).__name__}:{error}"
        digest = _proposal_digest(workspace, proposal)
        receipt = ValidationReceipt(
            proposal_id=proposal.proposal_id,
            staged_digest=digest,
            doctor_ok=doctor.ok,
            tests_ok=tests_ok,
            doctor_errors=tuple(doctor.errors),
            doctor_warnings=tuple(doctor.warnings),
            test_output_tail=output,
            validated_at_unix=time.time(),
        )
        self._last_validation[proposal.proposal_id] = receipt
        path = self._receipt_path(proposal.proposal_id)
        path.parent.mkdir(parents=True, exist_ok=True)
        temp = path.with_suffix(".json.new")
        temp.write_text(json.dumps(asdict(receipt), indent=2, sort_keys=True) + "\n", encoding="utf-8")
        os.replace(temp, path)
        return receipt

    async def promote(self, proposal: ChangeProposal, *, safe_boundary: bool) -> dict[str, Any]:
        if not self.enabled:
            raise RuntimeError("self_evolution_disabled")
        if self._context is None:
            raise RuntimeError("self_evolution_not_started")
        workspace = self._workspace(proposal.proposal_id)
        receipt = self._last_validation.get(proposal.proposal_id)
        if receipt is None or not receipt.accepted:
            raise RuntimeError("selfmod_validation_required")
        if not workspace.is_dir() or _proposal_digest(workspace, proposal) != receipt.staged_digest:
            raise RuntimeError("selfmod_staged_digest_changed")

        repair = self._context.get_service("repair.coordinator")
        if not isinstance(repair, RepairCoordinator):
            raise RuntimeError("repair_coordinator_missing")
        candidate = RepairCandidate(
            commit=f"selfmod:{proposal.proposal_id}",
            validation_passed=True,
            rollback_available=True,
            safe_boundary=bool(safe_boundary),
        )
        if not repair.authorize(candidate):
            raise RuntimeError("selfmod_repair_not_authorized")

        backup_root = self.work_root / "backups" / proposal.proposal_id
        journal_path = self.work_root / "journals" / f"{proposal.proposal_id}.json"
        journal: list[dict[str, Any]] = []
        backup_root.mkdir(parents=True, exist_ok=True)
        try:
            for change in self.validate_proposal(proposal):
                live = _checked_target(self.project_root, change.path, "live")
                staged = _checked_target(workspace, change.path, "staged")
                if not staged.is_file() or staged.is_symlink():
                    raise RuntimeError(f"selfmod_staged_file_invalid:{change.path}")
                existed = live.is_file()
                backup = _checked_target(backup_root, change.path, "backup")
                if existed:
                    backup.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(live, backup)
                live.parent.mkdir(parents=True, exist_ok=True)
                temp = live.with_name(live.name + ".eira2-new")
                if temp.exists() or temp.is_symlink():
                    raise RuntimeError(f"selfmod_live_temp_already_exists:{change.path}")
                shutil.copy2(staged, temp)
                os.replace(temp, live)
                journal.append({"path": change.path, "existed": existed})

            journal_path.parent.mkdir(parents=True, exist_ok=True)
            temp_journal = journal_path.with_suffix(".json.new")
            temp_journal.write_text(
                json.dumps({
                    "schema": "eira2_selfmod_journal_v1",
                    "proposal_id": proposal.proposal_id,
                    "purpose": proposal.purpose,
                    "changes": journal,
                    "promoted_at_unix": time.time(),
                }, indent=2, sort_keys=True) + "\n",
                encoding="utf-8",
            )
            os.replace(temp_journal, journal_path)

            doctor_service = self._context.get_service("operations.doctor")
            if not isinstance(doctor_service, DoctorService):
                raise RuntimeError("doctor_service_missing_after_promotion")
            post = doctor_service.evaluate(project_root=self.project_root)
            if not post.ok:
                raise RuntimeError("post_promotion_doctor_failed:" + ";".join(post.errors[:8]))
        except BaseException:
            self.rollback(proposal.proposal_id, journal=journal)
            raise

        for change in self.validate_proposal(proposal):
            event = "runtime.file_changed" if any(row["path"] == change.path and row["existed"] for row in journal) else "runtime.file_added"
            await self._context.publish(Event(event, {
                "path": change.path,
                "reason": "validated_self_modification",
                "proposal_id": proposal.proposal_id,
            }))
            if change.path.startswith("manifests/"):
                await self._context.publish(Event("registry.manifest_changed", {
                    "path": change.path,
                    "proposal_id": proposal.proposal_id,
                }))
        return {
            "ok": True,
            "proposal_id": proposal.proposal_id,
            "promoted_files": len(journal),
            "rollback_available": True,
            "filesystem_containment": "all_existing_path_components_non_symlink",
        }

    def rollback(self, proposal_id: str, *, journal: list[dict[str, Any]] | None = None) -> dict[str, Any]:
        backup_root = self.work_root / "backups" / proposal_id
        if journal is None:
            journal_path = self.work_root / "journals" / f"{proposal_id}.json"
            if not journal_path.is_file():
                raise FileNotFoundError(f"selfmod_journal_missing:{proposal_id}")
            payload = json.loads(journal_path.read_text(encoding="utf-8"))
            journal = list(payload.get("changes") or [])
        restored = 0
        removed = 0
        for row in reversed(journal):
            rel = _safe_relative(str(row.get("path") or ""))
            live = _checked_target(self.project_root, rel, "rollback_live")
            if bool(row.get("existed")):
                backup = _checked_target(backup_root, rel, "rollback_backup")
                if not backup.is_file() or backup.is_symlink():
                    raise RuntimeError(f"selfmod_backup_missing_or_invalid:{rel}")
                live.parent.mkdir(parents=True, exist_ok=True)
                temp = live.with_name(live.name + ".eira2-rollback")
                if temp.exists() or temp.is_symlink():
                    raise RuntimeError(f"selfmod_rollback_temp_already_exists:{rel}")
                shutil.copy2(backup, temp)
                os.replace(temp, live)
                restored += 1
            elif live.exists():
                live.unlink()
                removed += 1
        return {
            "ok": True,
            "proposal_id": proposal_id,
            "restored": restored,
            "removed": removed,
            "filesystem_containment": "all_existing_path_components_non_symlink",
        }

    async def cycle(self) -> dict[str, Any]:
        async with self._cycle_lock:
            if not self.enabled:
                self._last_cycle = {"status": "disabled", "at_unix": time.time()}
                return dict(self._last_cycle)
            if self.provider is None or self._context is None:
                raise RuntimeError("self_evolution_not_configured")
            doctor = self._context.get_service("operations.doctor")
            if not isinstance(doctor, DoctorService):
                raise RuntimeError("doctor_service_missing")
            report = doctor.evaluate()
            if report.ok:
                self._last_cycle = {"status": "healthy_no_change", "at_unix": time.time()}
                return dict(self._last_cycle)
            proposal = await self.provider(report)
            if proposal is None:
                self._last_cycle = {"status": "diagnosed_no_proposal", "at_unix": time.time(), "errors": len(report.errors)}
                return dict(self._last_cycle)
            workspace = await asyncio.to_thread(self.stage, proposal)
            receipt = await asyncio.to_thread(self.validate_staged, proposal, workspace)
            if not receipt.accepted:
                self._last_cycle = {
                    "status": "proposal_rejected",
                    "proposal_id": proposal.proposal_id,
                    "doctor_ok": receipt.doctor_ok,
                    "tests_ok": receipt.tests_ok,
                    "at_unix": time.time(),
                }
                return dict(self._last_cycle)
            promoted = await self.promote(proposal, safe_boundary=True)
            self._last_cycle = {"status": "promoted", **promoted, "at_unix": time.time()}
            return dict(self._last_cycle)

    async def _loop(self) -> None:
        while True:
            try:
                await self.cycle()
            except asyncio.CancelledError:
                raise
            except BaseException as error:
                self._last_cycle = {
                    "status": "cycle_failed",
                    "error": f"{type(error).__name__}:{error}"[:500],
                    "at_unix": time.time(),
                }
            await asyncio.sleep(self.interval_seconds)

from __future__ import annotations

import json
import re
from pathlib import Path
from typing import Any

from ..operations.doctor import DoctorReport
from ..reasoning.provider import Generate
from .evolution import ChangeProposal, FileChange


_PATH = re.compile(r"([A-Za-z0-9_./-]+\.(?:py|json|js|css|html|toml|yaml|yml))")
_ALLOWED_CONTEXT_PREFIXES = ("eira2/", "manifests/")


def _extract_json(raw: str) -> dict[str, Any]:
    text = str(raw or "").strip()
    if text.startswith("```"):
        lines = text.splitlines()
        if lines and lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        text = "\n".join(lines).strip()
        if text.casefold().startswith("json\n"):
            text = text[5:].lstrip()
    try:
        value = json.loads(text)
    except json.JSONDecodeError:
        start = text.find("{")
        end = text.rfind("}")
        if start < 0 or end <= start:
            raise ValueError("self_build_provider_json_missing")
        try:
            value = json.loads(text[start : end + 1])
        except json.JSONDecodeError as error:
            raise ValueError(f"self_build_provider_json_invalid:{error.msg}") from error
    if not isinstance(value, dict):
        raise TypeError("self_build_provider_result_not_object")
    return value


class StructuredProposalProvider:
    """Uses a candidate generator only to propose code; validation owns truth."""

    def __init__(
        self,
        project_root: Path,
        generate: Generate,
        *,
        max_context_chars: int = 24_000,
    ) -> None:
        self.project_root = project_root.expanduser().resolve()
        self.generate = generate
        self.max_context_chars = max(4_000, min(80_000, int(max_context_chars)))

    def _safe_context_paths(self, values: list[str]) -> list[str]:
        out: list[str] = []
        for value in values:
            clean = str(value or "").replace("\\", "/").lstrip("./")
            if ".." in Path(clean).parts:
                continue
            if not any(clean.startswith(prefix) for prefix in _ALLOWED_CONTEXT_PREFIXES):
                continue
            if clean not in out:
                out.append(clean)
        return out

    def _doctor_context_paths(self, report: DoctorReport) -> list[str]:
        candidates: list[str] = []
        for error in report.errors:
            candidates.extend(_PATH.findall(str(error)))
        return self._safe_context_paths(candidates)

    def _context(self, paths: list[str]) -> str:
        remaining = self.max_context_chars
        chunks: list[str] = []
        for rel in self._safe_context_paths(paths):
            path = (self.project_root / rel).resolve()
            try:
                path.relative_to(self.project_root)
            except ValueError:
                continue
            if not path.is_file():
                continue
            try:
                text = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            take = text[:remaining]
            chunks.append(f"\n--- {rel} ---\n{take}")
            remaining -= len(take)
            if remaining <= 0:
                break
        return "".join(chunks)

    @staticmethod
    def _proposal(value: dict[str, Any], fallback_purpose: str) -> ChangeProposal | None:
        raw_changes = value.get("changes")
        if raw_changes in (None, []):
            return None
        if not isinstance(raw_changes, list):
            raise TypeError("self_build_provider_changes_not_list")
        changes: list[FileChange] = []
        for row in raw_changes:
            if not isinstance(row, dict):
                raise TypeError("self_build_provider_change_not_object")
            changes.append(FileChange(
                path=str(row.get("path") or ""),
                content=str(row.get("content") or ""),
                reason=str(row.get("reason") or ""),
            ))
        purpose = str(value.get("purpose") or fallback_purpose).strip()
        return ChangeProposal(changes=tuple(changes), purpose=purpose)

    async def _generate_proposal(
        self,
        *,
        purpose: str,
        evidence: str,
        context_paths: list[str],
    ) -> ChangeProposal | None:
        prompt = f"""You are the non-authoritative EIRA 2.0 self-build candidate generator.
Return ONLY one JSON object, no prose and no markdown.
Schema:
{{"purpose":"short purpose","changes":[{{"path":"eira2/... or manifests/...","content":"complete UTF-8 file contents","reason":"why"}}]}}
If no safe implementation change can be justified from the evidence, return {{"purpose":"{purpose}","changes":[]}}.
Never propose edits to tests, pyproject.toml, preservation_contract.json, CANONICAL_ORDER.md, FUNCTIONAL_PRESERVATION.md, or REPLACEMENT_CONTRACT.md.
Do not use shell commands. Do not output patches: each changed file must contain its complete replacement contents.
The staged Doctor and full tests decide whether the candidate is accepted.

PURPOSE:
{purpose}

EVIDENCE:
{evidence[:12000]}

RELEVANT SOURCE CONTEXT:
{self._context(context_paths)}
"""
        raw = await self.generate(prompt)
        return self._proposal(_extract_json(raw), purpose)

    async def __call__(self, report: DoctorReport) -> ChangeProposal | None:
        if report.ok:
            return None
        evidence = "\n".join(report.errors[:30])
        return await self._generate_proposal(
            purpose="repair Doctor-detected EIRA 2.0 defects",
            evidence=evidence,
            context_paths=self._doctor_context_paths(report),
        )

    async def propose_instruction(
        self,
        instruction: str,
        *,
        context_paths: tuple[str, ...] = (),
    ) -> ChangeProposal | None:
        clean = " ".join(str(instruction or "").split())
        if not clean:
            raise ValueError("self_build_instruction_required")
        return await self._generate_proposal(
            purpose=clean[:500],
            evidence="explicit EIRA self-build instruction",
            context_paths=list(context_paths),
        )

from __future__ import annotations

import hashlib
import json
import sqlite3
import threading
import time
from pathlib import Path
from typing import Any, Iterable

from ..contracts import Health, RuntimeContext, ServiceSpec, ServiceState


class StateStore:
    spec = ServiceSpec("state.store", required=True, dependencies=("kernel.events",))

    def __init__(self, path: Path) -> None:
        self.path = path
        self._db: sqlite3.Connection | None = None
        self._state = ServiceState.DECLARED
        self._lock = threading.RLock()

    async def start(self, context: RuntimeContext) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        db = sqlite3.connect(
            self.path,
            timeout=10.0,
            check_same_thread=False,
        )
        db.execute("PRAGMA journal_mode=WAL")
        db.execute("PRAGMA synchronous=FULL")
        db.execute("PRAGMA foreign_keys=ON")
        db.execute("PRAGMA busy_timeout=5000")
        db.executescript("""
        CREATE TABLE IF NOT EXISTS schema_version (
            version INTEGER PRIMARY KEY,
            applied_at REAL NOT NULL
        );
        CREATE TABLE IF NOT EXISTS kv_state (
            namespace TEXT NOT NULL,
            key TEXT NOT NULL,
            value_json TEXT NOT NULL,
            updated_at REAL NOT NULL,
            PRIMARY KEY(namespace, key)
        );
        CREATE TABLE IF NOT EXISTS migration_provenance (
            source_path_hash TEXT PRIMARY KEY,
            source_sha256 TEXT,
            disposition TEXT NOT NULL,
            migrated_at REAL NOT NULL
        );
        CREATE TABLE IF NOT EXISTS state_journal (
            sequence INTEGER PRIMARY KEY AUTOINCREMENT,
            namespace TEXT NOT NULL,
            key TEXT NOT NULL,
            value_sha256 TEXT NOT NULL,
            updated_at REAL NOT NULL
        );
        CREATE INDEX IF NOT EXISTS state_journal_lookup
            ON state_journal(namespace, key, sequence DESC);
        """)
        now = time.time()
        db.execute(
            "INSERT OR IGNORE INTO schema_version(version, applied_at) VALUES(1, ?)",
            (now,),
        )
        db.execute(
            "INSERT OR IGNORE INTO schema_version(version, applied_at) VALUES(2, ?)",
            (now,),
        )
        db.commit()
        self._db = db
        integrity = self.integrity_check()
        if not integrity["ok"]:
            self._db.close()
            self._db = None
            self._state = ServiceState.FAILED
            raise RuntimeError(f"state_integrity_failed:{integrity['detail']}")
        self._state = ServiceState.READY

    async def stop(self) -> None:
        with self._lock:
            if self._db is not None:
                self._db.commit()
                try:
                    self._db.execute("PRAGMA wal_checkpoint(TRUNCATE)")
                except sqlite3.Error:
                    pass
                self._db.close()
                self._db = None
        self._state = ServiceState.STOPPED

    async def health(self) -> Health:
        if self._state == ServiceState.READY:
            check = self.integrity_check(quick=True)
            if not check["ok"]:
                return Health(ServiceState.FAILED, check["detail"])
        return Health(self._state)

    @staticmethod
    def _identity(namespace: str, key: str) -> tuple[str, str]:
        namespace = str(namespace or "").strip()
        key = str(key or "").strip()
        if not namespace or len(namespace) > 256:
            raise ValueError("state_namespace_invalid")
        if not key or len(key) > 1024:
            raise ValueError("state_key_invalid")
        return namespace, key

    def _ready(self) -> sqlite3.Connection:
        if self._db is None or self._state not in {ServiceState.READY, ServiceState.STARTING}:
            raise RuntimeError("state_store_not_ready")
        return self._db

    @staticmethod
    def _encode(value: Any) -> tuple[str, str]:
        payload = json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        digest = hashlib.sha256(payload.encode("utf-8")).hexdigest()
        return payload, digest

    def put(self, namespace: str, key: str, value: Any) -> None:
        self.put_many(((namespace, key, value),))

    def put_many(self, rows: Iterable[tuple[str, str, Any]]) -> None:
        prepared: list[tuple[str, str, str, str, float]] = []
        for namespace, key, value in rows:
            namespace, key = self._identity(namespace, key)
            payload, digest = self._encode(value)
            prepared.append((namespace, key, payload, digest, time.time()))
        if not prepared:
            return
        with self._lock:
            db = self._ready()
            try:
                db.execute("BEGIN IMMEDIATE")
                for namespace, key, payload, digest, updated_at in prepared:
                    db.execute(
                        """INSERT INTO kv_state(namespace,key,value_json,updated_at)
                           VALUES(?,?,?,?)
                           ON CONFLICT(namespace,key) DO UPDATE SET
                           value_json=excluded.value_json,updated_at=excluded.updated_at""",
                        (namespace, key, payload, updated_at),
                    )
                    db.execute(
                        """INSERT INTO state_journal(namespace,key,value_sha256,updated_at)
                           VALUES(?,?,?,?)""",
                        (namespace, key, digest, updated_at),
                    )
                db.commit()
            except BaseException:
                db.rollback()
                raise

    def get(self, namespace: str, key: str, default: Any = None) -> Any:
        namespace, key = self._identity(namespace, key)
        with self._lock:
            db = self._ready()
            row = db.execute(
                "SELECT value_json FROM kv_state WHERE namespace=? AND key=?",
                (namespace, key),
            ).fetchone()
        return json.loads(row[0]) if row else default

    def namespace_snapshot(self, namespace: str) -> dict[str, Any]:
        namespace = str(namespace or "").strip()
        if not namespace or len(namespace) > 256:
            raise ValueError("state_namespace_invalid")
        with self._lock:
            db = self._ready()
            rows = db.execute(
                "SELECT key,value_json FROM kv_state WHERE namespace=? ORDER BY key",
                (namespace,),
            ).fetchall()
        return {str(key): json.loads(value_json) for key, value_json in rows}

    def integrity_check(self, *, quick: bool = False) -> dict[str, Any]:
        with self._lock:
            if self._db is None:
                return {"ok": False, "detail": "state_store_closed"}
            pragma = "quick_check" if quick else "integrity_check"
            try:
                rows = self._db.execute(f"PRAGMA {pragma}").fetchall()
                foreign = self._db.execute("PRAGMA foreign_key_check").fetchall()
            except sqlite3.Error as error:
                return {"ok": False, "detail": f"{type(error).__name__}:{error}"}
        messages = [str(row[0]) for row in rows]
        ok = bool(messages) and all(message.casefold() == "ok" for message in messages) and not foreign
        detail = "ok" if ok else f"integrity={messages[:4]} foreign_key_failures={len(foreign)}"
        return {"ok": ok, "detail": detail, "foreign_key_failures": len(foreign)}

    def checkpoint(self, mode: str = "PASSIVE") -> dict[str, int]:
        mode = str(mode or "PASSIVE").strip().upper()
        if mode not in {"PASSIVE", "FULL", "RESTART", "TRUNCATE"}:
            raise ValueError("state_checkpoint_mode_invalid")
        with self._lock:
            db = self._ready()
            row = db.execute(f"PRAGMA wal_checkpoint({mode})").fetchone()
        busy, log_frames, checkpointed = (int(x) for x in (row or (0, 0, 0)))
        return {
            "busy": busy,
            "log_frames": log_frames,
            "checkpointed_frames": checkpointed,
        }

    def backup_to(self, destination: Path) -> dict[str, Any]:
        target = destination.expanduser().resolve()
        target.parent.mkdir(parents=True, exist_ok=True)
        temp = target.with_name(target.name + ".new")
        if temp.exists():
            temp.unlink()
        with self._lock:
            source = self._ready()
            source.commit()
            backup = sqlite3.connect(temp, timeout=10.0)
            try:
                source.backup(backup)
                backup.commit()
                integrity = backup.execute("PRAGMA integrity_check").fetchone()
                foreign = backup.execute("PRAGMA foreign_key_check").fetchall()
            finally:
                backup.close()
        if not integrity or str(integrity[0]).casefold() != "ok" or foreign:
            temp.unlink(missing_ok=True)
            raise RuntimeError("state_backup_integrity_failed")
        digest = hashlib.sha256(temp.read_bytes()).hexdigest()
        temp.replace(target)
        return {
            "ok": True,
            "path": str(target),
            "bytes": target.stat().st_size,
            "sha256": digest,
        }

