from __future__ import annotations

import hashlib
import json
import os
import shlex
import subprocess
import time
from dataclasses import dataclass, asdict
from pathlib import Path
from typing import Any


@dataclass
class VerifiedBridge:
    name: str
    configured: bool
    resolvable: bool
    verified: bool
    latency_ms: float | None
    detail: str

    @property
    def healthy(self) -> bool:
        return self.configured and self.resolvable and self.verified

    def payload(self) -> dict[str, Any]:
        out = asdict(self)
        out["healthy"] = self.healthy
        return out


def _resolve_executable(raw: str) -> tuple[bool, str]:
    if not raw:
        return False, "command_not_configured"
    try:
        argv = shlex.split(raw)
    except Exception as exc:
        return False, f"invalid_command:{type(exc).__name__}:{exc}"
    if not argv:
        return False, "empty_command"
    exe = argv[0]
    if os.path.sep in exe:
        ok = Path(exe).exists()
    else:
        from shutil import which
        ok = which(exe) is not None
    return ok, "resolved" if ok else f"executable_not_found:{exe}"


def verify_command_bridge(
    name: str,
    command: str,
    probe_command: str = "",
    *,
    cwd: Path,
    env: dict[str, str],
    timeout: float = 6.0,
) -> VerifiedBridge:
    configured = bool(command)
    resolvable, detail = _resolve_executable(command)
    if not configured or not resolvable:
        return VerifiedBridge(name, configured, resolvable, False, None, detail)

    # Verification is intentionally separate from simple executable resolution.
    # A side-effect-free probe command must be supplied for a bridge to become green.
    probe = probe_command.strip()
    if not probe:
        return VerifiedBridge(name, True, True, False, None, "probe_not_configured")
    probe_resolvable, probe_detail = _resolve_executable(probe)
    if not probe_resolvable:
        return VerifiedBridge(name, True, True, False, None, f"probe_{probe_detail}")

    started = time.perf_counter()
    try:
        cp = subprocess.run(
            shlex.split(probe),
            input=json.dumps({"probe": True, "source": "eira2_super_server"}),
            text=True,
            capture_output=True,
            cwd=str(cwd),
            env=env,
            timeout=timeout,
            check=False,
        )
    except subprocess.TimeoutExpired:
        return VerifiedBridge(name, True, True, False, round((time.perf_counter()-started)*1000, 2), "probe_timeout")
    latency = round((time.perf_counter() - started) * 1000, 2)
    if cp.returncode != 0:
        err = (cp.stderr or cp.stdout or "probe_failed").strip()[-1200:]
        return VerifiedBridge(name, True, True, False, latency, f"probe_exit_{cp.returncode}:{err}")
    text = (cp.stdout or "").strip()
    if not text:
        return VerifiedBridge(name, True, True, False, latency, "probe_empty")
    try:
        payload = json.loads(text)
    except Exception:
        payload = {"ok": text.lower() in {"ok", "pass", "ready"}}
    ok = bool(payload.get("ok", True)) if isinstance(payload, dict) else True
    return VerifiedBridge(name, True, True, ok, latency, "verified" if ok else "probe_reported_not_ready")


def verify_json_source(name: str, raw: str, live_root: Path) -> VerifiedBridge:
    if not raw:
        return VerifiedBridge(name, False, False, False, None, "json_source_not_configured")
    path = Path(raw)
    if not path.is_absolute():
        path = live_root / path
    if not path.exists():
        return VerifiedBridge(name, True, False, False, None, f"missing:{path}")
    started = time.perf_counter()
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
        if not isinstance(payload, (dict, list)):
            raise ValueError("top_level_not_object_or_array")
    except Exception as exc:
        return VerifiedBridge(name, True, True, False, round((time.perf_counter()-started)*1000,2), f"invalid_json:{type(exc).__name__}:{exc}")
    return VerifiedBridge(name, True, True, True, round((time.perf_counter()-started)*1000,2), str(path))


def verify_ar_roots(roots: list[Path]) -> VerifiedBridge:
    configured = bool(roots)
    live = [p for p in roots if p.exists() and p.is_dir()]
    if not configured:
        return VerifiedBridge("apple_ar", False, False, False, None, "ar_roots_not_configured")
    if not live:
        return VerifiedBridge("apple_ar", True, False, False, None, "ar_roots_unavailable")
    count = 0
    for root in live:
        try:
            count += sum(1 for _ in root.rglob("*.usdz"))
        except Exception:
            pass
    return VerifiedBridge("apple_ar", True, True, count > 0, None, f"verified_usdz={count}" if count else "no_usdz_artifacts")


def verify_manifest(manifest_path: str, root: Path) -> dict[str, Any]:
    if not manifest_path:
        return {"configured": False, "healthy": False, "detail": "package_manifest_not_configured", "checked": 0}
    manifest = Path(manifest_path)
    if not manifest.is_absolute():
        manifest = root / manifest
    if not manifest.exists():
        return {"configured": True, "healthy": False, "detail": f"manifest_missing:{manifest}", "checked": 0}
    try:
        data = json.loads(manifest.read_text(encoding="utf-8"))
        files = data.get("files", data) if isinstance(data, dict) else data
        if not isinstance(files, (list, dict)):
            raise ValueError("manifest_files_invalid")
        entries = files.items() if isinstance(files, dict) else ((e.get("path"), e) for e in files if isinstance(e, dict))
        checked = 0
        for rel, meta in entries:
            if not rel or not isinstance(meta, dict):
                raise ValueError("manifest_entry_invalid")
            p = (root / rel).resolve()
            if root != p and root not in p.parents:
                raise ValueError(f"manifest_path_escape:{rel}")
            if not p.is_file():
                raise FileNotFoundError(rel)
            if "size" in meta and p.stat().st_size != int(meta["size"]):
                raise ValueError(f"size_mismatch:{rel}")
            expected = str(meta.get("sha256", "")).lower().strip()
            if expected:
                actual = hashlib.sha256(p.read_bytes()).hexdigest()
                if actual != expected:
                    raise ValueError(f"sha256_mismatch:{rel}")
            checked += 1
        return {"configured": True, "healthy": True, "detail": "verified", "checked": checked, "manifest": str(manifest)}
    except Exception as exc:
        return {"configured": True, "healthy": False, "detail": f"{type(exc).__name__}:{exc}", "checked": 0, "manifest": str(manifest)}

#!/usr/bin/env python3
"""Fail-closed transactional migration for the isolated EIRA 2 super server.

This migrates only the eira2_server_revamp package. It does not modify EIRA1,
conversation/core architecture, or unrelated LIVE files. Dry-run is the default.
A committed cutover requires --commit and an explicit --target path.
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import shutil
import subprocess
import sys
import tempfile
import time
from pathlib import Path
from typing import Any

HERE = Path(__file__).resolve().parent
REQUIRED = (
    "server.py", "doctor.py", "hardening.py", "qualify.py",
    "static/index.html", "static/reference.css",
)


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


def package_manifest(root: Path) -> dict[str, Any]:
    files: dict[str, Any] = {}
    for rel in REQUIRED:
        p = (root / rel).resolve()
        if root.resolve() not in p.parents and p != root.resolve():
            raise RuntimeError(f"source_path_escape:{rel}")
        if not p.is_file():
            raise RuntimeError(f"required_source_missing:{rel}")
        st = p.stat()
        files[rel] = {"size": st.st_size, "sha256": sha256(p)}
    return {"format": 1, "package": "eira2_server_revamp", "files": files}


def verify_tree(root: Path, manifest: dict[str, Any]) -> None:
    for rel, expected in manifest["files"].items():
        p = (root / rel).resolve()
        if root.resolve() not in p.parents and p != root.resolve():
            raise RuntimeError(f"verify_path_escape:{rel}")
        if not p.is_file():
            raise RuntimeError(f"verify_missing:{rel}")
        if p.stat().st_size != int(expected["size"]):
            raise RuntimeError(f"verify_size_mismatch:{rel}")
        if sha256(p) != expected["sha256"]:
            raise RuntimeError(f"verify_sha256_mismatch:{rel}")


def compile_python(root: Path) -> None:
    files = [root / x for x in ("server.py", "doctor.py", "hardening.py", "qualify.py")]
    cp = subprocess.run([sys.executable, "-m", "py_compile", *map(str, files)], capture_output=True, text=True)
    if cp.returncode:
        raise RuntimeError(f"python_compile_failed:{(cp.stderr or cp.stdout).strip()[-3000:]}")


def js_check(root: Path) -> None:
    node = shutil.which("node")
    if not node:
        raise RuntimeError("node_required_for_migration_js_check")
    html = (root / "static/index.html").read_text(encoding="utf-8")
    start = html.find("<script>")
    end = html.rfind("</script>")
    if start < 0 or end <= start:
        raise RuntimeError("inline_javascript_not_found")
    script = html[start + len("<script>"):end]
    cp = subprocess.run([node, "--check"], input=script, capture_output=True, text=True)
    if cp.returncode:
        raise RuntimeError(f"javascript_syntax_failed:{(cp.stderr or cp.stdout).strip()[-3000:]}")


def copy_package(src: Path, dst: Path) -> None:
    if dst.exists():
        shutil.rmtree(dst)
    dst.mkdir(parents=True, exist_ok=False)
    for rel in REQUIRED:
        s = src / rel
        d = dst / rel
        d.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(s, d)


def atomic_json(path: Path, payload: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(path.name + ".tmp")
    tmp.write_text(json.dumps(payload, indent=2, sort_keys=True), encoding="utf-8")
    os.replace(tmp, path)


def refuse_live_owner(target: Path) -> None:
    # Migration never guesses whether another server is safe to kill.
    for candidate in (target / ".state/server.pid", target.parent / ".state/server.pid"):
        if not candidate.is_file():
            continue
        try:
            pid = int(candidate.read_text(encoding="utf-8").strip())
            os.kill(pid, 0)
        except ProcessLookupError:
            continue
        except Exception as exc:
            raise RuntimeError(f"cannot_validate_existing_server_owner:{candidate}:{exc}") from exc
        raise RuntimeError(f"existing_server_process_alive:{pid}:{candidate}")


def safe_target(target: Path, live_root: Path) -> None:
    target = target.resolve()
    live_root = live_root.resolve()
    if target == live_root:
        raise RuntimeError("target_must_not_equal_live_root")
    if live_root not in target.parents:
        raise RuntimeError(f"target_must_be_inside_live_root:{target}")
    if target.name in {"", ".", "..", "LIVE", "eira", "eira2"}:
        raise RuntimeError(f"unsafe_target_name:{target.name}")


def run(args: argparse.Namespace) -> dict[str, Any]:
    src = HERE.resolve()
    live_root = Path(args.live_root).expanduser().resolve()
    target = Path(args.target).expanduser().resolve()
    safe_target(target, live_root)
    if not live_root.is_dir():
        raise RuntimeError(f"live_root_missing:{live_root}")

    manifest = package_manifest(src)
    verify_tree(src, manifest)
    compile_python(src)
    js_check(src)
    refuse_live_owner(target)

    txn_root = live_root / ".eira2_server_migrations"
    txn_id = time.strftime("%Y%m%dT%H%M%S") + f"-{os.getpid()}"
    stage = txn_root / f"stage-{txn_id}"
    backup = txn_root / f"backup-{txn_id}"
    receipt = txn_root / f"receipt-{txn_id}.json"

    copy_package(src, stage)
    verify_tree(stage, manifest)
    atomic_json(stage / "package_manifest.json", manifest)

    report: dict[str, Any] = {
        "ok": True,
        "mode": "commit" if args.commit else "dry-run",
        "transaction_id": txn_id,
        "source": str(src),
        "live_root": str(live_root),
        "target": str(target),
        "stage": str(stage),
        "backup": None,
        "manifest_sha256": hashlib.sha256(json.dumps(manifest, sort_keys=True).encode()).hexdigest(),
        "files": sorted(manifest["files"]),
        "cutover": False,
        "rollback_ready": False,
    }

    if not args.commit:
        shutil.rmtree(stage)
        report["stage"] = None
        return report

    txn_root.mkdir(parents=True, exist_ok=True)
    had_target = target.exists()
    try:
        if had_target:
            os.replace(target, backup)
            report["backup"] = str(backup)
            report["rollback_ready"] = True
        os.replace(stage, target)
        verify_tree(target, manifest)
        atomic_json(target / "package_manifest.json", manifest)
        report["cutover"] = True
        atomic_json(receipt, report)
        return report
    except Exception:
        # Roll back atomically wherever possible. Never leave an unverified target active.
        try:
            if target.exists():
                failed = txn_root / f"failed-{txn_id}"
                os.replace(target, failed)
            if backup.exists():
                os.replace(backup, target)
        finally:
            raise


def main() -> int:
    p = argparse.ArgumentParser(description="Transactional EIRA 2 server package migration")
    p.add_argument("--live-root", required=True, help="Existing Easystore LIVE root")
    p.add_argument("--target", required=True, help="Explicit server package destination inside LIVE")
    p.add_argument("--commit", action="store_true", help="Perform atomic cutover; default is dry-run")
    args = p.parse_args()
    try:
        print(json.dumps(run(args), indent=2, sort_keys=True))
        return 0
    except Exception as exc:
        print(json.dumps({"ok": False, "error": f"{type(exc).__name__}:{exc}"}, indent=2), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

