    exe = argv[0]
    if os.path.sep in exe:
        ok = Path(exe).is_file()
    else:
        from shutil import which
        ok = which(exe) is not None
    return Bridge(name, True, ok, "resolved" if ok else f"executable_not_found:{exe}")


